quests[10316] = { id = 10316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Beweisen", description = "Wer auch immer hinter den Veränderungen der Geister stehen mag, hat seine Ziele mit Bedacht ausgewählt, und darauf geachtet, dass er zuerst die mächtigsten Magier erwischt. Aber warum? Die Magie, die eingesetzt wird, um die Geister der getöteten Kirin Tor zu beeinflussen, muss sehr mächtig sein.\n\nWarum würde ein mächtiger Magier all diese Mühen auf sich nehmen? Ich bin versucht zu glauben, dass dies ein weiterer teuflischer Plan von Kael'thas ist, um hier weiteres Unheil anzurichten. Wenn es hier in der Nähe Blutelfen gibt, verstecken sie sich bestimmt in den Häusern hinter der überdachten Brücke.", sourceObjective = "Durchsucht die Häuser auf dem Kapellenhof von Kirin'Var nach Hinweisen darauf, wer sich hinter der Beeinflussung der Geister verbirgt.", completion = "Eine leuchtende Kugel liegt auf einem quadratischen Podest. Auf den ersten Blick scheint sie ein Behältnis für magische Energie zu sein, aber welche Art von Energie und zu welchem Zweck?", sourceObjectiveStatus = "unverified-source-field" }
quests[10317] = { id = 10317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Großknecht erledigen", description = "Die Blutelfen nennen die Mine unter der Manaschmiede Ara Trelleummine. Seit sie die Mine unter der Manaschmiede Ultris verloren haben, ist sie der einzige Ort, von dem sie den Nachschub zum Betrieb ihrer Schmieden bekommen.\n\nIch brauche nicht zu erwähnen, dass es ein großer Vorteil für uns wäre, wenn wir ihre Bergbauaktivitäten dort verhindern könnten. Vielleicht könnten wir sogar dort einfallen und die Mine für uns selbst nutzen?\n\nWie auch immer, ich möchte, dass Ihr Euch um Großknecht Sonnenend kümmert. Die Mine befindet sich am hinteren Ende der Insel links von uns.", sourceObjective = "Vernichtet Großknecht Sonnenend in der Trelleummine, die sich unter der Manaschmiede Ara im Nethersturm befindet.", completion = "<Der Großknecht flüstert.>\n\nSeid Ihr hier um mich zu töten? Hmm. Nun, ich glaube, die Astralen wissen nicht alles, was?\n\nIch bin nicht der, den Ihr sucht, glaubt mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[10318] = { id = 10318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Übermeister erledigen", description = "Ich war früher hier der Großknecht. Aber jetzt, da ich degradiert wurde, geht mir auf, dass unsere ganze Pilgerreise von Quel'Thalas in die Scherbenwelt eine einzige Lüge war!\n\nEine Lüge, die von Kael'thas eingefädelt wurde, um seine Streitkräfte hier im Nethersturm zu stärken.\n\nIch habe versucht, meine Brüder davon zu überzeugen, dass wir fortgehen sollten, besonders wegen der Brennenden Legion, aber sie sind alle zu stur.\n\nKönnt Ihr mir einen Gefallen tun? Tötet Übermeister Grindgarr. Kehrt dann zu Eurem Astralen zurück und sagt ihm, dass ich kein Feind mehr bin.", sourceObjective = "Tötet Übermeister Grindgarr. Kehrt dann zu Windhändler Tuluman auf Tulumans Landeplatz im Nethersturm.", completion = "Ein Übermeister der Verdammniswache? Das ist merkwürdig! Was macht denn die Brennende Legion dort?\n\nHm, einige der Blutelfen werden also abtrünnig. Wir werden das im Hinterkopf behalten, falls wir uns je entschließen sollten, den Ort mit Gewalt einzunehmen. Zumindest sind das ein paar gute Nachrichten, oder?\n\nBitte, {name}, nehmt dieses Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10319] = { id = 10319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Phylakterium entwenden", description = "Ich glaube, es wird Zeit für eine Erklärung. Ihr habt einen der Lehrlinge des Erzmagiers getroffen, Ravandwyr. Es gab jedoch noch einen weiteren mit dem Namen Naberius.\n\nEr war ein sehr fleißiger Schüler, hegte aber großes Interesse an der Nekromantie. Als Kael'thas mit seinen Streitmächten auftauchte, nutzte Naberius die Gelegenheit, um den Erzmagier zu verraten und die geheimen Verteidigungsmechanismen des Turms preiszugeben.\n\nJetzt, so scheint es, ist er zu einem Lich geworden. Wenn wir ihn aufhalten wollen, müssen wir uns sein Phylakterium besorgen. So wie ich ihn kenne, hat er es sicher irgendwo in seinem Gebiet sicher vergraben.", sourceObjective = "Holt Naberius' Phylakterium vom Kapellenhof in Kirin'Var und bringt es zu Hüter Dierwert.", progress = "Wir müssen erst Naberius' Phylakterium beschaffen, bevor wir ihn angreifen können. Er ist sonst unverwundbar!", completion = "Ausgezeichnete Arbeit, {name}. Der Besitz des Phylakteriums ist der Schlüssel zu unserem Sieg. Wenn Ihr gegen Naberius in die Schlacht zieht, werde ich es zerstören und ihn so für Eure Angriffe verwundbar machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10320] = { id = 10320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet Naberius!", description = "Erzmagier Vargoth hat die Gefahr in Naberius' Interesse an der Nekromantie erkannt, aber ich bin mir sicher, dass er niemals geglaubt hätte, dass sein Lehrling den Kirin Tor so viel Schaden zufügen würde.\n\nIhr müsst ihn besiegen, {name}, sonst wird er weiterhin die Geister unserer gefallenen Brüder versklaven, sie ihrer Ruhe berauben und das letzte bisschen, was noch von Kirin'Var übrig ist, zerstören.\n\nOhne sein Phylakterium kann er mit den vereinten Kräften von zwei oder drei Kämpfern vernichtet werden, aber wer weiß, was seine Magie mehr Gegnern gegenüber anrichten könnte?", sourceObjective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr Naberius auf dem Kapellenhof des Dorfes besiegt.", completion = "Der Sieg über Naberius ist ein große Leistung, {name}. Ich kann mir nicht helfen, aber ich glaube, wir hätten eine Chance gegen Kael'thas' Streitkräfte gehabt, wenn der Lehrling auf der richtigen Seite gestanden hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[10321] = { id = 10321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede Coruu abschalten", description = "Euer Erfolg in B'naar hat und sehr große Hoffnung gemacht, {name}.\n\nWir haben unsere Entdeckungen den Sehern mitgeteilt, und sie haben uns im Gegenzug mehr Informationen über die übrigen Manaschmieden gegeben.\n\nEs stehen immer noch drei weitere Manaschmieden, die von der Armee des Sonnenzorns kontrolliert werden.\n\nDie Manaschmiede Coruu findet Ihr im Osten. Vorarbeiterin Seylanna ist dort im Besitz des Zugangskristalls. Besorgt ihn und schaltet damit die Steuerungskonsole ab.\n\nWir zählen auf Euch, {name}.", sourceObjective = "Reist zur Manaschmiede Coruu, östlich von Area 52, und besorgt den Zugangskristall von Coruu von Vorarbeiterin Seylanna. Benutzt ihn, um die Manaschmiede abzuschalten, und kehrt dann zu Anachoret Karja zurück.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr Eure Aufgabe schon erledigt, {name}?", completion = "Ausgezeichnete Arbeit. Jetzt sind nur noch zwei Manaschmieden aktiv.\n\nBald wird Kael'thas von seiner Hauptenergiequelle abgeschnitten sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10322] = { id = 10322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede Duro abschalten", description = "Wir haben Neuigkeiten von einer der Manaschmieden, die noch in Betrieb sind, erhalten. Die Armee des Sonnenzorns ist im Begriff, die Kontrolle über die Manaschmiede Duro zu verlieren.\n\nWegen ihrer erhöhten Energieproduktion werden ganze Schwärme von Manakreaturen von ihr angelockt - die Manaschmiede versinkt im Chaos.\n\nEine Explosion von Duro könnte eine Kettenreaktion auslösen, die die ganze Scherbenwelt in Gefahr bringen würde. Vorarbeiter Athanel ist im Besitz des Zugangskristalls, mit dem Ihr die Manaschmiede abschalten könnt.", sourceObjective = "Anachoret Karja möchte, dass Ihr zur Manaschmiede Duro geht und den Zugangskristall von Vorarbeiter Athanel besorgt. Benutzt ihn, um die Steuerungskonsole von Duro abzuschalten.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr Eure Aufgabe schon erledigt, {name}?", completion = "Ihr seid von den Naaru gesegnet, {name}. Euer Einsatz für die Sache wird nicht unbemerkt oder unbelohnt bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10323] = { id = 10323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede Ara abschalten", description = "Nur noch eine Manaschmiede hält die Festung der Stürme in Betrieb. Nachdem wir die Manaschmiede Ara abgeschaltet haben, muss sich Kael mit seinen gespeicherten Energien zufrieden geben.\n\nReist zur Manaschmiede Ara im Nordwesten und gebt Kael den Rest, indem Ihr sie abschaltet.\n\nDer letzte Zugangskristall befindet sich im Besitz von Vorarbeiter Azarad. Seid jedoch vorsichtig; wir erwarten heftigen Widerstand in Kaels letzter funktionierender Schmiede. Ihr werdet wahrscheinlich die Unterstützung einiger Freunde brauchen.", sourceObjective = "Reist zur Manaschmiede Ara und besorgt Euch einen Zugangskristall von Vorarbeiter Azarad. Benutzt ihn, um die Steuerungskonsole von Ara abzuschalten.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr die Aufgabe, die ich Euch gegeben habe, schon erledigt, {name}?", completion = "Die Brennende Legion? Verbündet mit Kael'thas Sonnenwanderer?\n\nDas sind erschütternde Nachrichten. Das erklärt vieles, was wir hier und in Schattenmond beobachtet haben.\n\nWir müssen Shattrath sofort informieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10324] = { id = 10324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Mondweidenjagd", description = "Gut gemacht, {name}! Gut gemacht!\n\nJetzt, da Ihr Euch die Hörner an den Mondweidenhirschen abgestoßen habt, ist es an der Zeit, dass Ihr Euch einer würdigeren Beute zuwendet. Lasst Euch von der Gelassenheit der Mondweidenböcke nicht täuschen, wenn sie sich provoziert fühlen, sind sie ein gefährlicher Gegner.\n\nIhr findet die Böcke nördlich von hier. Weidmannsheil.", sourceObjective = "Bringt 6 Bälge eines Mondweidenbocks zu Acteon in der Azurwacht.", progress = "Die Bälge der Böcke sind grob und stark und halten das Fleisch zäh. Es ist kaum essbar, aber wir können es für andere Zwecke einsetzen.", completion = "Wunderbar! Ihr entwickelt Euch zu einem beachtlichen Jäger, {name}.\n\nWürdet Ihr mir gerne ähnlich sehen? Nun, hier ist Eure Chance! Während Ihr auf der Jagd wart, habe ich diese Gegenstände aus den Bälgen, die ich hier noch herumliegen hatte, gefertigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10325] = { id = 10325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Male von Kil'jaeden", description = "Wie Ihr vielleicht wisst, {name}, sind die Aldor die Hüter des Lichts und die Diener der Naaru.\n\nUns direkt gegenüber stehen die Agenten der Brennenden Legion - Dämonen, die die Welten zerstören und die Unschuldigen verderben wollen.\n\nWenn Ihr Euch den Aldor gegenüber beweisen wollt, bringt mir die Insignien der niederrangigen Mitglieder der Legion und ihrer Anhänger des Schattenrats. Uns ist ein Versteck des Schattenrats in der Knochenwüste bekannt. Die Lager der Legion findet Ihr in Nagrand und dem Schergrat.", sourceObjective = "Bringt 10 Male von Kil'jaeden zu Adyen dem Lichtwächter in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Tragt Ihr irgendwelche Insignien des Feindes bei Euch, {name}?", completion = "Sich den Dämonen der Brennenden Legion und den wahnsinnigen Kultisten, die sie verehren, zu stellen ist keine geringe Tat, {name}. Ihr habt viel Hingabe und Mut bewiesen. Macht so weiter, und Euer Ruf bei den Aldor wird weiter steigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10326] = { id = 10326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Male von Kil'jaeden", progress = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, {name}? Die Brennende Legion ist auch weiterhin eine Bedrohung, und wir verfolgen sie überall, wo wir sie finden können.", completion = "Beweist Euch weiterhin als würdig, {name}. Besiegt die Feinde des Lichts, wo immer Ihr sie findet. Eure Taten sollen angemessen belohnt werden." }
quests[10327] = { id = 10327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Male von Kil'jaeden", progress = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", completion = "Beweist Euch weiterhin als würdig, {name}. Besiegt die Feinde des Lichts, wo immer Ihr sie findet. Eure Taten sollen angemessen belohnt werden." }
quests[10328] = { id = 10328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anweisungen des Sonnenzorns", description = "Etwas an diesen Manaschmieden bereitet mir Kopfzerbrechen, {name}. Die Naarutechnologie ist sehr fortschrittlich; Kael'thas hätte Jahre brauchen müssen, um sie auch nur im Ansatz zu verstehen.\n\nDas Sammeln von Informationen zu diesem Thema ist sehr schwierig, da Kaels Armee sehr diszipliniert ist und jegliche schriftliche Kommunikation sofort vernichtet.\n\nWir haben gehört, dass die Manaschmiede Duro von Manakreaturen angegriffen wird. Vielleicht haben die Verteidiger ihre Anweisungen noch nicht zerstört. Besorgt sie Euch und bringt sie zu mir.", sourceObjective = "Reist zur Manaschmiede Duro und beschafft die Truppenbefehle des Sonnenzorns und die Arkanbefehle des Sonnenzorns von den Einheiten des Sonnenzorns, die dort postiert sind. Kehrt zu Exarch Orelis zurück, wenn Ihr Eure Aufgabe erledigt habt.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Hattet Ihr Glück mit den Anweisungen der Manaschmiede Duro?", completion = "Ausgezeichnete Arbeit, {name}! Wollen wir mal schauen, was uns diese Anweisungen verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10329] = { id = 10329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede B'naar abschalten", description = "Während Ihr fort wart, hatte ich eine freundliche Diskussion mit den Aldor. Die Manaschmieden bestehen aus der Naarutechnologie der Festung der Stürme. Offensichtlich gibt es bei dieser Technologie Mechanismen, die ein dauerhaftes Abschalten im Notfall ermöglichen.\n\nAlles, was wir brauchen, um diesen Vorgang einzuleiten, ist ein Zugangskristall zur Steuerungskonsole. Der praktischen Stammrolle, die Ihr uns gebracht habt, nach, befinden sich die Kristalle im Besitz eines Typen namens Vorarbeiter Theredis. Besorgt ihn und schaut, was Ihr tun könnt.", sourceObjective = "Geht zurück zur Manaschmiede B'naar und besorgt Euch den Zugangskristall von Vorarbeiter Theredis. Benutzt ihn bei der Steuerkonsole von B'naar um sie abzuschalten und meldet Euch danach bei Spionagemeister Thalodien zurück.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Hat der Plan funktioniert? Ehrlich gesagt habe ich fast befürchtet, dass Ihr in die Luft gejagt werdet.", completion = "Natürlich hat es funktioniert! Ich bin Spionagemeister, meine Informationen sind immer genau.\n\nWie auch immer, da wartet ein brandneuer und spannender Auftrag auf Euch. Wollt Ihr davon hören? Natürlich wollt Ihr das.", sourceObjectiveStatus = "unverified-source-field" }
quests[10330] = { id = 10330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede Coruu abschalten", description = "Thalodien hat uns von Eurem Erfolg beim Abschalten der Manaschmiede B'naar erzählt. Er erwartet, dass Ihr Eure Leistung hier wiederholt und hat uns gebeten, ein Auge darauf zu haben, wer einen Kristall benutzt, um Zugang zu der Konsole im Inneren zu erhalten. Vorarbeiterin Seylanna hat den Zugangskristall, da sind wir uns sicher.\n\nGeht hinein und vollendet das Werk. Es besteht kein Grund zur Heimlichkeit mehr. Besorgt Euch den Kristall, schaltet die Konsole ab, tötet alle Techniker, die Euch daran hindern wollen, und macht Euch dann aus dem Staub.\n\nBeeilt Euch, Kaels Spürhunde kommen uns sicher bald auf die Schliche.", sourceObjective = "Besorgt den Zugangskristall von Coruu von Vorarbeiterin Seylanna. Benutzt ihn, um die Steuerkonsole der Manaschmiede abzuschalten und meldet Euch dann bei Caledis Morgenhell.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr Eure Aufgabe schon erledigt, {name}?", completion = "Wir haben den Aufruhr gehört und wollten gerade gehen. Ich bin froh, dass Ihr nicht allzu viel Prügel einstecken musstet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10331] = { id = 10331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unverzichtbare Werkzeuge", description = "Ihr habt hier nicht zufällig einen schweren Schmiedehammer herumliegen sehen, oder? Ich habe ihn hierher mitgenommen, um ein paar Hufeisen für das Pferd des alten Amorlin fertig zu stellen, aber ich kann ihn nicht finden.\n\nIch habe die ganze Scheune mindestens ein dutzend Mal abgesucht, aber ohne Erfolg. Vielleicht hat einer der anderen Lehrlinge ihn gefunden und ihn zurück zur Schmiede gebracht? Könntet Ihr für mich dorthin gehen und danach suchen? Sie befindet sich südöstlich des Turms auf dem Ratsplatz.", sourceObjective = "Besorgt den Schmiedehammer von den Lehrlingen von Kirin'Var und bringt ihn zurück zu Lehrling Andrethan in Kirin'Var.", progress = "Hattet Ihr Glück bei der Suche nach meinem Hammer?", completion = "Dem Himmel sei Dank! Jetzt kann ich zurück an die Arbeit. Ich weiß, dass Ihr denkt, dass ich verrückt bin, so weit von einer richtigen Schmiede an meinem Gesellenstück zu arbeiten, aber ich darf nicht riskieren, dass die anderen Lehrlinge meine Entwürfe stehlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10332] = { id = 10332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterschmied Rhonsus", description = "Endlich ist mein Gesellenstück fertig! Ich kann es kaum abwarten, es Meister Rhonsus zu zeigen.\n\n<Der Lehrling schaut Euch an, als Ihr ihm erzählt, was passiert ist, als Ihr den Hammer zurückholen wolltet.>\n\nSie haben Euch angegriffen? Alle? Beim Licht, sie sind verrückt geworden!\n\nWas sollen wir tun, {name}? Es schmerzt mich, das zu sagen, aber vielleicht müssen wir Meister Rhonsus umbringen. Dann wäre ich der einzige Schmied in Kirin'Var, aber ich denke, dass meine Ausbildung ausreicht, um die Bedürfnisse des Dorfs zu befriedigen.", sourceObjective = "Lehrling Andrethan in Kirin'Var möchte, dass Ihr den Geist von Rhonsus, dem Meisterschmied des Dorfes, vernichtet.", completion = "Meister Rhonsus hat mir alles beigebracht, was ich über mein Handwerk wissen muss. Ich werde seine Erinnerung in Ehren halten, indem ich den Leuten von Kirin'Var mit meinem Geschick diene.", sourceObjectiveStatus = "unverified-source-field" }
quests[10333] = { id = 10333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Mama Mauschel", description = "Sagt mal, {name}, ich habe mich gefragt, ob Ihr mir noch einen Gefallen tun könntet.\n\nMeine Partnerin da draußen im Feld könnte sicher etwas Hilfe gebrauchen. Könnt Ihr ihr vielleicht helfen?\n\nIch bin sicher, dass Mama Mauschel dafür sehr dankbar wäre. Kümmert Euch nicht um ihre scharfe Zunge.\n\nSie bemüht sich um unsere Interessen im Osten. Ihr findet sie in der Biokuppel Mittelreich beim Mittelreichposten.", sourceObjective = "Sprecht mit Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.", completion = "Was? Er hat mich seine \"Partnerin\" genannt? Ich bin seine Frau!\n\nUnd er sagt, ich hätte eine scharfe Zunge. Oh, wenn ich zurück nach Area 52 komme, werde ich ihm die großen grünen Ohren langziehen!\n\nAber ich bin froh, dass Ihr hier seid. Mit einer Sache hatte er Recht; ich kann ganz sicher Eure Hilfe brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10334] = { id = 10334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braucht mehr Kuhglocke", description = "Wo, oh, wo ist meine Bessy? Nach dem Angriff habe ich die Felder und den Kapellenhof nach Ihr abgesucht, aber ich konnte sie nicht finden!\n\nAlles, was ich von ihr noch habe, ist diese alte Kuhglocke. Normalerweise kommt sie gleich gerannt, wenn sie sie hört, aber vielleicht können diese alten Hände sie nicht stark genug läuten.\n\nIch leihe Euch Bessys Glocke, wenn Ihr hinaus auf die Felder geht und sie so fest Ihr nur könnt läutet. Vielleicht wartet Bessy einfach nur auf ein wenig mehr Kuhglocke.", sourceObjective = "Sucht Bessy in den Feldern nordöstlich des Kapellenhügels von Kirin'Var im Nethersturm.", progress = "<Die Kuh schaut Euch misstrauisch an, bleibt aber stehen.>", completion = "<Als Ihr die Glocke aus Eurer Tasche holt, läutet Ihr sie ein paar Mal und zeigt sie Bessy, die sie zu erkennen scheint. Die Kuh lässt zu, dass Ihr ihr die Glocke um den Hals hängt und schaut Euch erwartungsvoll an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10335] = { id = 10335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen beobachten", description = "Ich muss in die Ruinen von Farahlon gehen, um meine Ausgrabungen zu beginnen! Das Problem ist, dass dieser Ort von Dämonen heimgesucht wird.\n\nVielleicht könntet Ihr schon einmal ein wenig Vorarbeit für mich leisten?\n\nEs gibt drei Orte in den Ruinen im Nordosten, an dem Ihr für mich Vermessungsmarkierungen aufstellen sollt. Jede befindet sich in der Nähe eines Draeneibanners.\n\nKehrt zu mir zurück, wenn Ihr alle drei Markierungen erfolgreich aufgestellt habt.", sourceObjective = "Platziert die drei Vermessungsmarkierungen und kehrt dann zu Zephirion in der Sturmsäule im Nethersturm zurück.", progress = "Das ging aber schnell. Ihr müsst sehr effektiv arbeiten, wenn Ihr alle drei Markierungen schon aufgestellt habt.", completion = "Ihr wollt mir keinen Bären in die Bandagen binden, oder? Das sind ausgezeichnete Nachrichten!\n\nJetzt, da Ihr die Routinearbeiten für die Vermessung für mich ausgeführt habt, kann ich mein Team in die Ruinen führen und schauen, was wir bergen können.\n\nIhr habt meinen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10336] = { id = 10336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener von Culuthas", description = "Vor ein paar Wochen hat die Brennende Legion in den Ruinen von Farahlon Einzug gehalten und damit all unsere Pläne, die Artefakte dort auszugraben, zunichtegemacht.\n\nDann habe ich heute erfahren, dass einer ihrer Schreckenslords, Culuthas, aus irgendeinem Grund alle anderen Mitglieder der Brennenden Legion dort getötet hat. Seitdem ruft er Dämonen, die ihm dienen.\n\n{class}, ich möchte, dass Ihr zu den Ruinen im Nordosten geht und die Dämonen vernichtet!", sourceObjective = "Tötet 10 Hunde von Culuthas und 5 Augen von Culuthas", completion = "Wirklich ausgezeichnete Arbeit.\n\nJetzt, da die Dämonen von Culuthas tot sind, kann Zephirion mit seinem Ausgrabungsteam sicher in die Ruinen von Farahlon zurückkehren.\n\nNehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10337] = { id = 10337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Almabtrieb", description = "Als Ihr merkt, dass Bessy Euch immer noch anstarrt, deutet Ihr nach Westen, zu dem Ort, an dem Thadell sich befindet. Ihr erwischt Euch selbst dabei, wie Ihr der Kuh versprecht, sie auf ihrem Nachhauseweg zu beschützen. Als Ihr Euren Satz beendet habt, wird Euch klar, dass die Kuh gar nicht verstehen kann, was Ihr sagt.\n\nMit einem Schulterzucken bereitet Ihr Euch darauf vor, das Rindvieh zu Thadell zurückzubegleiten.", sourceObjective = "Begleitet Bessy sicher zu ihrem Besitzer Thadell zurück.", progress = "Habt Ihr meine Bessy gefunden?", completion = "Bessy, bist Du das?\n\n<Der Bauer dreht sich zu Euch um.>\n\nVielen Dank, dass Ihr mir meine Bessy zurückgebracht habt, {name}. Ich könnte ohne sie nicht leben!", sourceObjectiveStatus = "unverified-source-field" }
quests[10338] = { id = 10338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede Duro abschalten", description = "Die Manaschmiede Duro wird also angegriffen und die Streitkräfte des Sonnenzorns haben die Kontrolle verloren? Was für ein Dilemma! Wenn Duro fällt, fällt die Festung der Stürme. Der einzige Nachteil ist... wenn die Festung der Stürme zerstört wird, wird die Explosion wahrscheinlich die kläglichen Überreste dieses verlassenen Landes mit sich reißen.\n\nKael'thas Tod ist gut. Jedermanns Tod ist... nicht so gut, glaube ich. Es schmerzt mich, Euch darum zu bitten, aber geht zur Manaschmiede Duro und schaltet sie ab, bevor sie in Flammen aufgeht. Vorarbeiter Athanel hat den Zugangskristall.", sourceObjective = "Kehrt zur Manaschmiede Duro zurück und besorgt Euch den Zugangskristall von Vorarbeiter Athanel. Benutzt ihn, um die Steuerkonsole von Duro abzuschalten, und meldet Euch danach bei Spionagemeister Thalodien.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Konsole abgeschaltet? Ihr solltet Euch beeilen, bevor ich meine Meinung dazu ändere.", completion = "Jetzt habt Ihr schon drei Manaschmieden abgeschaltet, {name}. Kael'thas muss sich gerade furchtbar über Euch aufregen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10339] = { id = 10339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Astraleum", description = "Direkt südlich von hier findet Ihr den Stützpunkt des Astraleums. Das Astraleum bereitet sich dort auf irgendetwas vor... Vielleicht einen Angriff auf Ultris.\n\nWir können jedoch nichts dem Zufall überlassen, {class}. Durchbrecht ihre Verteidigung und zerstört ihr Trainingslager.\n\nSobald Ihr ihre Soldaten und Hauptmann Zovax vernichtet habt, sucht den Transponder des Astraleums Zeta und benutzt ihn, um mit mir Kontakt aufzunehmen. Dann werdet Ihr Eure neuen Befehle erhalten.", sourceObjective = "Kommandant Ameer möchte, dass Ihr 5 Auftragsmörder des Astraleums, 5 Stoßtruppsoldaten des Astraleums, 2 Forscher des Astraleums und Hauptmann Zovax tötet und dann den Transponder des Astraleums Zeta aktiviert.", progress = "Gut gemacht, Fleischling...", completion = "Wir müssen alle Daten, die sie in diesem Gebiet aufbewahren, sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[10340] = { id = 10340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trümmerposten", description = "{name}, Ihr habt gute Arbeit hier an der Front geleistet und großes Talent mit den gepanzerten Greifen bewiesen... Ich glaube, ich habe eine weitere Aufgabe für Euch.\n\nStartpunkt für Eure neue Mission ist der Trümmerposten, eine Angriffsbasis der Wildhämmer auf einer schwebenden Insel in der Nähe des Portals. Es ist etwas anstrengend dort, aber Ihr habt starke Nerven. Ihr packt das schon.\n\nSprecht mit Schwadronskommandant Dabir'ee und lasst Euch von ihm zum Trümmerposten schicken. Meldet Euch dann bei Greifenmeister Runetog Wildhammer.", sourceObjective = "Vorpostenkommandant Königstein möchte, dass Ihr mit Schwadronskommandant Dabir'ee sprecht, auf einem Greifen zum Trümmerposten fliegt und Euch bei Runetog Wildhammer meldet.", completion = "Ha ha! Ein frischer {race} vom Festland! Nun, keine Sorge - der Trümmerposten kann Euch vielleicht etwas seekrank machen, aber er treibt nicht weit weg!\n\nUnd bisher hat er sich nur einmal auf den Kopf gedreht... oder zweimal.", sourceObjectiveStatus = "unverified-source-field" }
quests[10341] = { id = 10341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tretet sie, solange sie am Boden liegen", description = "Das sind günstige Nachrichten, die Ihr bringt, {name}. Ihr könnt nicht nur ungehindert in die Manaschmiede Duro reinspazieren, es eröffnet sich auch noch eine großartige Gelegenheit, Kaels Armee einen Schlag zu versetzen.\n\nNutzt den Angriff der Manakreaturen und vernichtet alle Nachzügler des Sonnenzorns, die Euch in die Arme laufen.\n\nIch habe keinen besonderen Spaß daran, mein eigenes Volk abzuschlachten, wie Tahlodien, aber diesen taktischen Vorteil dürfen wir nicht ungenutzt vorübergehen lassen.", sourceObjective = "Tötet 8 Beschwörer des Sonnenzorns, 6 Jadgschützen des Sonnenzorns und 4 Zenturios des Sonnenzorns. Kehrt zu Magistrix Larynna in Area 52 zurück, wenn Ihr die Aufgabe erledigt habt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Das habt Ihr gut gemacht, {name}. Kaels Armee wird sich nicht so leicht von diesem Schlag erholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10342] = { id = 10342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schieferhautschiefer", description = "Ich verdiene gut daran, den Trunkenbolden hier Getränke zu verkaufen. Aber ich will mehr!\n\nDer Raketenchef sagt mir immer, dass er den Raketentreibstoff, den er braucht, um die X-52 abheben zu lassen, nicht verbessern kann.\n\nWir können dieses kleine Problem für ihn lösen.\n\nZuerst muss ich das Öl aus dem Schiefer der hiesigen Schieferhautschinder pressen. Daraus mache ich einen konzentrierten, wenn auch leicht entzündlichen, Grundstoff für die Mischung, die mir vorschwebt.\n\nSucht die Schinder und ihren Schiefer! Sie sind überall bei den violetten Felsen.", sourceObjective = "Sammelt 5 Stück Schieferhautschiefer und bringt sie zu Stiefels in Area 52 im Nethersturm.", progress = "Habt Ihr schon genug Schiefer? Ich brauche eine ganze Menge, wenn ich genug Öl für den Raketentreibstoff der X-52 herstellen will.", completion = "Ok! Zutat Nummer eins erledigt.\n\nWenn Ihr noch Lust habt, besorgen wir jetzt etwas, das dem Schieferöl den kleinen Extrakick gibt, um die Rakete in den wirbelnden Nether zu katapultieren... oder in Stücke zu sprengen, was immer zuerst geschehen mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[10343] = { id = 10343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unendliche Invasion", description = "Kael'thas Angriff auf Kirin'Var begann mit einem donnernden Geräusch und einem hellen Lichtblitz im Offiziersquartier im Nordwesten. Die Zerstörung war dort am größten. Nach dem Rückzug der Blutelfen geschah etwas Merkwürdiges.\n\nWesen aus reinem Mana begannen, von überall her in das Dorf zu strömen. Bis jetzt versuchen wir, sie so gut es geht im Zaum zu halten, aber ich hoffe, dass wir den Ansturm komplett abwehren können, wenn wir mehr über die Waffe in Erfahrung bringen, die Kael'thas benutzt hat.", sourceObjective = "Sucht die von Manakreaturen heimgesuchte Gegend in Kirin'Var nach einem Manabombenfragment ab und bringt sie zu Zaubererleutnant Morran.", progress = "Habt Ihr die Überreste der Waffe, die Kael'thas gegen das Dorf eingesetzt habt, gefunden?", completion = "Eine Manabombe?\n\n<Morran dreht das Fragment in den Händen.>\n\nEs ist unglaublich! Sogar die hellsten Köpfe in Dalaran hätte eine Waffe wie diese nicht entwerfen können. Das schiere Ausmaß der Explosion muss einen Riss im Nether geöffnet und diesen Kreaturen einen Zugang zu unserem Land verschafft haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10344] = { id = 10344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwadronskommandant Greifgar", description = "Schwadronskommandant Greifgar hat die Leitung über die Wildhämmer hier. Wenn Ihr zum ersten Mal im Trümmerposten seid, solltet Ihr Euch bei ihm melden.\n\nIhr findet ihn in den Überresten des Turms da drüben.", sourceObjective = "Sprecht mit Schwadronskommandant Greifgar im Trümmerposten.", completion = "Ihr habt mit Runetog gesprochen? Er ist ein guter Zwerg, hält seine Greifen gut in Schuss und immer kampfbereit.\n\nIch bin Greifgar, Kommandant des Trümmerpostens. Ich weiß, es ist nicht gerade hübsch hier, aber dieser Felsklotz ist ein wichtiger Stützpunkt für Operationen auf der Höllenfeuerhalbinsel. Man kann hier rund um die Uhr Greifen ein- und ausfliegen sehen.\n\nEinen Rat? Hier ist einer: haltet Eure Ausrüstung bereit, Euren Magen leer und Eure Augen am Horizont... wenn der Trümmerposten anfängt auseinanderzufallen, haltet Euch an etwas fest, was nicht wegfliegen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[10345] = { id = 10345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleisch geworden", description = "Seht Ihr diese Leichen, {race}? Arconus ist für diese Massaker verantwortlich. Er hat sie ausgesaugt, sodass nur noch eine Fleischhülle übrig geblieben ist. Aber lasst Euch von den Körpern nicht täuschen! In diesen Leichen liegen Fleischbestien, die nur darauf warten, ahnungslose Dummköpfe, die sich zu nahe heranwagen, anzufallen.\n\nIch habe meine Befehle. Ich muss hierbleiben, bis meine Verstärkung eintrifft. Das bedeutet aber nicht, dass Ihr nicht meinen Anzünder nehmen und die siechenden Leichen, die überall in den Minen herumliegen, zerstören könnt. So oder so muss diese Aufgabe erledigt werden.", sourceObjective = "Benutzt den Anzünder des Protektorats um 12 siechende Leichen zu zerstören. Bringt den Anzünder des Protektorats zu Agent Araxes außerhalb des Zugangsschachts Zeon zurück, wenn Ihr erfolgreich wart.", progress = "Konntet Ihr Sechs-Uhr finden?", completion = "Ihr habt meine Bandagen gerettet, {name}. Dass Protektorat wird erfahren, was Ihr heute getan habt, Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[10346] = { id = 10346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Abyssischen Untiefe", description = "{name}, Ihr habt Euch als fähiger Greifenreiter bewiesen. Wir könnten Euch für weitere Einsätze bei der Abyssischen Untiefe brauchen. Was sagt Ihr, {class}? Wollt Ihr noch ein paar Flugstunden sammeln?", sourceObjective = "Greifnerin Heulwind im Trümmerposten auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen zerstört.", progress = "In der abyssischen Untiefe sind immer noch genügend ziele, {name}. Schnappt Euch einen Greifen, wenn Ihr für eine weitere Runde bereit seid.", completion = "Wie ist es gelaufen? Ihr seid ja in guter Verfassung... Ist sie gut genug für einen weiteren Flug?", sourceObjectiveStatus = "unverified-source-field" }
quests[10347] = { id = 10347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Abyssischen Untiefe", description = "{name}, seid Ihr bereit für einen weiteren Flug zu Abyssischen Untiefe? Ich fürchte, dass uns die Dämonen der Legion von Norden her angreifen werden, wenn wir sie nicht weiter unter Druck setzen und zulassen, dass sie Ihre Festung verstärken.\n\nWas sagt Ihr, {name}? Habt Ihr Lust, Euch erneut auf einen Windreiter zu schwingen und zur Abyssischen Untiefe zu fliegen?", sourceObjective = "Schwadronskommandant Brack im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen zerstört.", progress = "Die Legion darf sich auf der abyssischen Untiefe nicht in Sicherheit wiegen! Wir müssen immer und immer wieder zuschlagen!", completion = "Die anderen Windreiterführer halten sehr viel von Euch, {name}. Ihr habt in der abyssischen Untiefe ganz schön aufgeräumt. Macht weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[10348] = { id = 10348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Möglichkeiten", description = "Ich habe gehört, dass eine Gruppe von 'Druiden' aus Azeroth sich für die Wirkung unserer Biokuppeltechnologie interessiert.\n\nDie Expedition des Cenarius ist sehr begierig darauf, Zugang zu den Pflanzen in den Kuppeln zu erlangen, besonders zu der einen, die sie Elfenbeinglocke nennen, und die für ihre heilenden Kräfte bekannt ist. Sie wächst in der Biokuppel Mittelreich in kleinen Büschen um größere Pflanzen herum.\n\nIch teile den Gewinn mit Euch, wenn Ihr mir ein paar der Kräuter für meine erste Lieferung sammelt.", sourceObjective = "Sammelt 15 Elfenbeinglocken und kehrt dann zu Mehrdad im Mittelreichposten zurück.", progress = "Konntet Ihr die Pflanzen sammeln?", completion = "Interessante Wahl, oder? Die heilende Wirkung der Pflanze muss überragend sein. Ich bekomme eine Menge Geld für eine Blume, die eine der unspektakulärsten der Kuppeln ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10349] = { id = 10349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erdbinderin", description = "Ihr solltet dieses Kristallstück zur Erdbinderin bringen. Sie ist wie Ihr... immer muss sie einem Geheimnis auf die Spur kommen und darüber nachgrübeln.\n\nWenn Ihr mich fragt, denkt sie zu viel.\n\nGebt ihr den Kristall und ich bin sicher, dass sie Euch beim Versuch herauszufinden, was im Grat vor sich geht, in ganz schöne Schwierigkeiten bringen wird.", sourceObjective = "Bringt den Purpurkristallsplitter zu Erdbinderin Galandria Nachtluft im Posten des Cenarius auf der Höllenfeuerhalbinsel.", progress = "Ist das ein Stück des riesigen Kristallsplitters oben auf dem Himmelssturzgrat?", completion = "Oh, ausgezeichnet!\n\nIch habe die ganze Zeit gehofft, an ein Stück davon zu kommen, aber Tola'thion kommt nicht in die Gänge. Er sollte mir eigentlich helfen herauszufinden, was im Himmelssturzgrat vor sich geht. Stattdessen schickt er nur arme Tölpel wie Euch - nichts für ungut - dort hoch auf die Schlachtbank.\n\nWenn Ihr mir den Kristall gebt, kann ich vielleicht herausfinden, in welcher Verbindung er zu den Kolossen steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10350] = { id = 10350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behomat", description = "Ihr habt viele harte Lektionen in unserer Zeit zusammen von mir gelernt, doch nun ist es an der Zeit, dass ich Euch in weisere Hände übergebe.\n\nBehomat, der mich ausbildete, als ich noch grün wie Gras hinter den Ohren war, wird Euer neuer Lehrer sein. Ich habe ihm gesagt, dass ich Euch zu ihm schicken werde, er erwartet Euch also.\n\nIhr findet ihn in der Mitte der Terrasse der Krieger, am höchsten Punkt der Händlertreppe der Exodar.", sourceObjective = "Sprecht mit Behomat bei der Händlertreppe in der Exodar.", completion = "Ah, Ihr seid also endlich gekommen. Ich bin Behomat und werde Euch in den Künsten eines Kriegers unterweisen. Ruada hat mir von Eurer Prüfung gegen den Felshetzer erzählt und ich bin sehr beeindruckt. Ich habe ein Geschenk für Euch.\n\nWir konnten nur wenig aus den Trümmern der Exodar retten, und das verteilen wir nur an die Würdigsten. Bitte nehmt Euch eine Waffe, die Eurem Kampfstil entspricht, und führt sie mit dem Wissen, dass Ihr sie verdient habt.\n\nWo wir gerade von Kampfstilen sprechen - es ist Zeit, dass Ihr etwas Neues lernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10351] = { id = 10351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natürliche Heilmittel", description = "Es müssen die bösen Strahlungen von dem riesigen roten Kristall sein, die die Bergriesen herbeirufen und sie wahnsinnig machen.\n\nEr ist zu groß, um ihn weg zu bringen, und unsere Fertigkeiten reichen nicht aus, um ihn zu zerstören, aber mir ist ein Weg eingefallen, wie wir seine Macht bezwingen können.\n\nIch habe einen Zirkel beim nordwestlichen Ende des Kristalls auf dem Grat beschworen. Bringt diesen Samen dorthin und setzt seine Macht ein, um das Land durch die natürlichen Kräfte des Regens, des Wachstums und der Insekten zu heilen.\n\nSeid vorsichtig, {name}. Ich spüre, dass hier eine außenstehende Macht am Werk ist... und sie ist nicht natürlich!", sourceObjective = "Benutzt den Samen der Wiederbelebung beim Zirkel des Erdbinders, um das Land um den Kristall herum zu heilen. Kehrt dann zu Erdbinderin Galandria Nachtluft im Posten des Cenarius auf der Höllenfeuerhalbinsel mit Euren Beobachtungen zurück.", progress = "Hat es funktioniert? Was habt Ihr beobachtet? Habt Ihr herausgefunden, was im Himmelssturzgrat passiert ist?", completion = "Goliathon? Pathaleon der Kalkulator?\n\nKAEL'THAS!?\n\nPrinz Kael'thas hat seine Hand im Spiel?!\n\n<Die Erdbinderin schäumt vor Wut.>\n\nWas er getan hat ist Wahnsinn! Riesige Kristalle vom Himmel zu werfen und das Land zu dezimieren kann nur die Arbeit eines Verrückten sein!\n\nIch verspreche Euch, dass der Zirkel des Cenarius nun, da wir wissen was zu tun ist, jegliche weitere Versuche von Illidan und seinen Streitmächten, so etwas noch einmal zu tun, von uns vereitelt werden.\n\nWir stehen tief in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10352] = { id = 10352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Wolle", progress = "Wir nehmen zurzeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Darnassus einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Fabelhaft! Wir danken Euch für Eure großzügige Spende, {name}!" }
quests[10353] = { id = 10353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arconus der Unersättliche", description = "Araxes und ich wurden vor zwei Tagen nach Ultris geschickt. Unser Auftrag: findet und vernichtet den Leerenfürsten Arconus. Wir haben ihn bis zu seiner Mine verfolgt und herausgefunden, dass er sich von den Energien der Kreaturen in dieser Gegend ernährt.\n\nEs brach ein Feuerwechsel aus, bei dem Araxes und ich getrennt wurden. Jetzt bin ich hier gefangen und schwer verletzt. Unser Auftrag ist dahin!\n\nWenn Ihr Arconus erledigen könntet, wäre die oberste Führung Euch sehr dankbar. Wenn Ihr den Auftrag annehmt, werde ich Euch eine Reflexion meiner selbst als Wächter mitschicken.", sourceObjective = "Agent Sechs-Uhr beim Zugangsschacht Zeon im Nethersturm möchte, dass Ihr Arconus den Unersättlichen tötet und dann zu Kommandant Ameer im Wachposten des Protektorats im Nethersturm zurückkehrt.", completion = "Und Sechs-Uhr? Hat er es geschafft?\n\nWollen wir verdammt noch mal hoffen. Ich konnte keine Verstärkung zu ihnen schicken... Das Astraleum hat nun die ganze Gegend in Beschlag genommen.\n\nEntschuldigt, fast hätte ich Eure Belohnung vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10354] = { id = 10354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Seide", progress = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Lasst Euch für Eure großzügige Spende gedankt sein, {name}!" }
quests[10355] = { id = 10355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siechendes Fleisch", description = "Wir müssen herausfinden, wie weit der Schaden reicht. Das Basidium, das Ihr mir gebracht habt, stammt von einem Sumpfriesen. Ihre größeren, zäheren Vettern, die Sumpflords, sollten der Degenerierung, die die Riesen befallen hat, gegenüber unempfindlicher sein.\n\nEs wäre auch schön zu wissen, inwiefern die Veränderungen die anderen Kreaturen des Todesmoors betroffen haben.\n\nKehrt zum Todesmoor zurück und schaut, ob Ihr Proben von den Sumpflords und Hydras in der Gegend sammeln könnt.", sourceObjective = "Sammelt 5 Proben einer verdurstenden Hydra und 5 Proben eines siechenden Sumpflords und bringt sie zu Ruam in Telredor.", progress = "Konntet Ihr die Proben sammeln?", completion = "<Ruam betrachtet die Proben und sieht besorgt aus.>\n\nEs ist so, wie ich es befürchtet habe, {name}. Die Austrocknung der Umwelt macht den Kreaturen, die außerhalb eines Sumpfgebiets nie überleben würden, sehr zu schaffen. Wir müssen die Umgebung weiterhin überwachen und die Expedition des Cenarius fragen, ob es etwas gibt, was wir tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10356] = { id = 10356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Magiestoff", progress = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Wir danken Euch für Eure großzügige Spende, {name}!" }
quests[10357] = { id = 10357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Runenstoff", progress = "{name}, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", completion = "Fantastisch - Ich kann Euch versichern, dass wir sofort Gebrauch davon machen werden. Lasst Euch erneut für Eure Mithilfe gedankt sein! Ohne Euch wären wir mit Sicherheit verloren.\n\nDa ihr schon so viel gespendet habt, wäre ich natürlich bereit, mich auch um jede weitere Spende Runenstoff zu kümmern, die Ihr in Zukunft tätigen wollt. Kommt einfach zu mir, ich werde dann persönlich dafür sorgen, dass Eure guten Taten bei den Anführern auf der Exodar nicht unbeachtet bleiben!" }
quests[10358] = { id = 10358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Runenstoff", progress = "Seid gegrüßt, {name}! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", completion = "{name} - ohne Helden, die sich wie Ihr einsetzen, müssten wir so einiges in Kauf nehmen. Danke für Eure redlichen Bemühungen!" }
quests[10359] = { id = 10359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Wolle", progress = "Wir nehmen zurzeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Silbermond einbringen.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Fabelhaft! Wir danken Euch für Eure großzügige Spende, {name}!" }
quests[10360] = { id = 10360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Seide", progress = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in Silbermond mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Lasst Euch für Eure großzügige Spende gedankt sein, {name}!" }
quests[10361] = { id = 10361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Magiestoff", progress = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit in Silbermond nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Wir danken Euch für Eure großzügige Spende, {name}!" }
quests[10362] = { id = 10362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Runenstoff", progress = "{name}, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", completion = "Fantastisch - Ich kann Euch versichern, dass wir sofort Gebrauch davon machen werden. Lasst Euch erneut für Eure Mithilfe gedankt sein! Ohne Euch wären wir mit Sicherheit verloren.\n\nDa ihr schon so viel gespendet habt, wäre ich natürlich bereit, mich auch um jede weitere Spende Runenstoff zu kümmern, die Ihr in Zukunft tätigen wollt. Kommt einfach zu mir, ich werde dann persönlich dafür sorgen, dass Eure guten Taten in Silbermond nicht unbeachtet bleiben!" }
quests[10363] = { id = 10363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Runenstoff", progress = "Seid gegrüßt, {name}! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber Silbermond erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", completion = "{name} - ohne Helden, die sich wie Ihr einsetzen, müssten wir so einiges in Kauf nehmen. Danke für Eure redlichen Bemühungen!" }
quests[10364] = { id = 10364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caedmos", description = "Ihr seid in kurzer Zeit sehr weit gekommen, {name}. Schneller, als ich erwartet oder gehofft hätte. Es ist an der Zeit, dass Ihr Eure Ausbildung unter der Anleitung meines Meisters, Caedmos, fortsetzt.\n\nIch habe ihm gesagt, dass er Euch in der Exodar erwarten soll. Ihr findet ihn im Sanktum der Anachoreten in der Nähe des Eingangs zur Halle des Lichts.", sourceObjective = "Sprecht mit Caedmos in der Halle des Lichts der Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10365] = { id = 10365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede Ara abschalten", description = "Ihr habt Eure Arbeit besser erledigt, als wir dachten. Die Manaschmiede Ara ist die letzte von Kaels Schmieden, die noch in Betrieb ist. Ihr findet sie nordwestlich von hier, aber Ihr müsst wahrscheinlich um sie herumgehen, um dorthin zu gelangen. Wir möchten, dass Ihr sie abschaltet.\n\nDer letzte Zugangskristall befindet sich im Besitz von Vorarbeiter Azarad. Seid jedoch vorsichtig; wir erwarten heftigen Widerstand in Kaels letzter funktionierender Schmiede. Ihr werdet wahrscheinlich die Unterstützung einiger Freunde brauchen.\n\nHmm... Azarad. Was ein komischer Name für einen Sin'dorei.", sourceObjective = "Reist zur Manaschmiede Ara und besorgt Euch einen Zugangskristall von Vorarbeiter Azarad. Benutzt ihn, um die Steuerungskonsole von Ara abzuschalten.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Aufgabe, die ich Euch gegeben habe, schon erledigt, {name}?", completion = "Die Brennende Legion? Unter einer Decke mit Kael? Daran wird Voren'thal sicher seine Freude haben.\n\nDenkt ihr, dass Tausende von Pilgern von Azeroth hierher kommen, um sich mit der Brennenden Legion zu verbünden? Ich glaube kaum!", sourceObjectiveStatus = "unverified-source-field" }
quests[10366] = { id = 10366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jol", description = "Der Pfad des Lichts und der Reinheit ist steinig, {name}. Sogar ich habe manchmal Probleme, ihm zu folgen.\n\nIhr solltet meine Meisterin, Jol, in der Exodar aufsuchen. Sie hat mich zu Beginn meiner Reise ausgebildet. Ich bin mir sicher, dass sie in Euch ihren neuen Lieblingsschüler finden wird.\n\nIhr findet Jol in der Halle des Lichts in der Exodar beim Sanktum der Verteidiger, einem Raum, der von einem pulsierenden Lichtschein umgeben ist.", sourceObjective = "Sprecht mit Jol im Sanktum der Verteidiger in der Exodar.", completion = "{name}, ich habe Euch erwartet.\n\nTullas hat Lobeshymnen auf Euch gesungen, und ich bin sehr begierig darauf, Euch im Weg des Lichts zu unterweisen. Sucht mich auf, wenn Ihr bereit seid, Eure Fähigkeiten und Eure Macht verstehen zu lernen, und ich werde Euch geleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10367] = { id = 10367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Verräter unter uns", description = "Wo immer ihr einen Stamm von versklavten Zerschlagenen seht, könnt Ihr auch einen Verräter finden. Ein verachtungswürdiges Wesen, das seine Brüder für das Versprechen von Macht verkauft hat.\n\nOben an der Treppe in der Mitte der Ruinen könnt Ihr eine Hütte finden. Das ist die Hütte des Verräters.\n\nEr ist im Augenblick nicht dort, Ihr könnt Euch also hineinschleichen, wenn Ihr Geduld habt. Innen findet Ihr einen Kasten mit einem Schlüssel darin. Dieser Schlüssel passt zu den Ketten, die die Ältesten des Lumpenpacks gefangen halten. Bringt ihn mir.\n\nSeid jedoch vorsichtig, Arzeth der Erbarmungslose treibt sich in der Nähe herum.", sourceObjective = "Naladu in den Ruinen von Sha'naar möchte, dass Ihr den Schlüssel von Sha'naar aus einer Hütte in der Nähe besorgt.", progress = "Habt Ihr den Schlüssel schon, {name}?", completion = "Ich danke Euch, {name}. Dank Eurer Hilfe wird mein Volk bald frei sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10368] = { id = 10368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ältesten des Lumpenpacks", description = "Der Geist des Lumpenpacks ist gebrochen, weil sich unsere Ältesten in Gefangenschaft befinden. Nehmt diesen Schlüssel und befreit sie.\n\nEs sind Morod der Windtreiber, Akoru der Feuerrufer und Aylaan der Wasserrufer. Sobald sie frei sind, werden die Geister zum Stamm des Lumpenpacks zurückkehren.", sourceObjective = "Befreit Morod den Windtreiber, Akoru den Feuerrufer und Aylaan den Wasserrufer aus den Ruinen von Sha'naar. Kehrt zu Naladu zurück, wenn Ihr diese Aufgabe erledigt habt.", progress = "Sagt mir, {name}. Sind die Ältesten des Lumpenpacks schon frei?", completion = "Ich kann es fühlen, {name}! Die Geister kehren zu uns zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10369] = { id = 10369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arzeths Untergang", description = "Ja, die Elementargeister sind zu uns zurückgekehrt! Wir sind nicht mehr so stark wie einst, aber auch geringe Magie kann in den richtigen Händen weit reichen.\n\nArzeth wurde von seinem dunklen Herrn große Macht verliehen. Nehmt diesen Stab. Er war einst ein großartiges Symbol unseres Volkes. Setzt ihn gegen Arzeth ein, und seine Macht wird für kurze Zeit verschwinden. Besiegt ihn, damit mein Volk endlich frei sein kann!", sourceObjective = "Benutzt den Ältestenstab des Lumpenpacks gegen Arzeth den Erbarmungslosen und tötet ihn, nachdem er seine Macht verloren hat. Kehrt danach zu Naladu in den Ruinen von Sha'naar zurück.", progress = "Ist es vollbracht, {name}? Ist Arzeth tot?", completion = "Es ist wahr, {name}. Ich war einst Naladu, der Bewahrer der Erde.\n\nIch war es, der die anderen Mitglieder des Lumpenpacks für leere Versprechungen von Macht verkauft hat. Ihr könnt mich nun verachten, wenn Ihr wollt. Wichtig ist, dass mein Stamm nun wieder frei ist und die Geister zu uns zurückgekehrt sind.\n\nIch werde mich dem Rest des Stammes nicht anschließen, aber nun kann ich in Frieden sterben. Mögen die Geister der Erde unter meinen Brüdern einen neuen Diener finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10370] = { id = 10370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazgrels Befehl" }
quests[10371] = { id = 10371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yorus Gerstenbräu", description = "Ein Zwergenkrieger namens Yorus Gerstenbräu hat eine Herausforderung für alle tüchtigen Krieger der Allianz verkündet.\n\nEr wartet im Gasthaus von Seenhain, im sogenannten Rotkammgebirge in den Östlichen Königreichen. Es wird eine lange Reise, aber sie lohnt sich, wenn Ihr Euch selbst testen wollt, {name}.", sourceObjective = "Sprecht mit Yorus Gerstenbräu im Gasthaus Seenhain im Rotkammgebirge.", sourceObjectiveStatus = "unverified-source-field" }
quests[10372] = { id = 10372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine diskrete Anfrage", description = "Eralan, eine Verbündete von mir in Tristessa, hat angefragt, ob ihr jemand bei einem eiligen Auftrag helfen könnte.\n\nIch weiß nicht, was sie vorhat, denn ich stelle keine Fragen, aber Ihr habt Euch mehr als fähig erwiesen. Ich möchte, dass Ihr nach Tristessa in den Geisterlanden reist, und mit Eralan sprecht.\n\nSie mag vielleicht ein wenig ruppig sein, aber man kann ihr vertrauen.", sourceObjective = "Sprecht mit Eralan in Tristessa.", sourceObjectiveStatus = "unverified-source-field" }
quests[10373] = { id = 10373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Sturmwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Ehrenschlag auf, der seinen Stützpunkt am Zugwindlager errichtet hat, nördlich des Alteracgebirges!", sourceObjective = "Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich am Zugwindlager, nördlich des Alteracgebirges.", sourceObjectiveStatus = "unverified-source-field" }
quests[10374] = { id = 10374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Östlichen Königreiche erheben! Sie lauern östlich von Unterstadt, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunkt am Bollwerk östlich von Tirisfal aufgeschlagen!", sourceObjective = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt.", completion = "Willkommen in den Pestländern. Dies ist eine der gefährlichsten Grenzen in Azeroth, vor allem aufgrund der sich abzeichnenden Bedrohung durch die Geißel im Osten und noch weiter östlich. Ich bin froh zu hören, dass der Ruf der Pflicht und des Dienstes für die Horde bei Euch nicht auf taube Ohren gestoßen ist!\n\nWenn Ihr bereit seid, Eure Hände schmutzig zu machen, gibt es hier am Rand der Pestländer für fähige Helden viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[10375] = { id = 10375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidiankriegsperlen", description = "Ihr habt Euch meinem Volk gegenüber als würdig erwiesen, {name}. Jetzt ist es an der Zeit, uns zu beweisen, dass Ihr bereit seid, uns jederzeit beizustehen, auch gegen unserer ärgsten Feind.\n\nDie Oger der Scherbenwelt sind" }
quests[10376] = { id = 10376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbol der Hoffnung" }
quests[10377] = { id = 10377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Angst", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[10378] = { id = 10378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magie verzehren" }
quests[10379] = { id = 10379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche" }
quests[10380] = { id = 10380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dunkler Pakt", description = "Wir waren so blind, dass wir nicht gesehen haben, dass unsere beiden größten Feinde sich verbündet haben, {name}.\n\nIch wäre nicht überrascht, wenn die Seher uns diese Information absichtlich vorenthalten hätten, aber wir müssen uns nun der Wirklichkeit stellen. Die Brennende Legion und Kael'thas Sonnenzornarmee dienen unter dem gleichen Banner.\n\nDie Dämonen sind der einzige Grund, aus dem Kael'thas je in der Lage war, die Technologie der Festung der Stürme nutzen zu können. Ich muss Euch auf Orelis' Befehl hin bitten, sie zu zerstören.", sourceObjective = "Kaylaan bei Tulumans Landeplatz in Nethersturm möchte, dass Ihr 6 Warptüftler der Gan'arg, 3 Töchter des Schicksals und 3 Warpmeister der Mo'arg tötet.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Wart Ihr bei Eurer Aufgabe erfolgreich, {name}?", completion = "Es ist also vollbracht. Wir kommen im Auftrag unserer Herren hierher, jagen und töten sie. Es gibt kein Pardon.\n\nManchmal gibt das einem zu denken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10381] = { id = 10381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie mehr Aldor", description = "Meine Mission hier ist zu Ende. Ich habe getan, was Orelis mir befohlen hat - nie habe ich ihn enttäuscht.\n\nNie wieder. Ich sehe ein großes Gemetzel voraus - einen Kreuzzug werden sie es nennen - das auf das neue Bündnis zwischen Kael'thas und der Brennenden Legion folgen wird.\n\nZuerst werden sie unsere heiligste Stadt dem Feind übergeben und uns dann bitten, im Kampf gegen ihren Feind zu sterben. Geht zurück zu Orelis und sagt ihm, dass die Naaru von nun an ihre Kämpfe alleine austragen können.", sourceObjective = "Meldet Euch bei Exarch Orelis in Area 52.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Die schlechten Nachrichten, die Ihr mir bringt, erfüllen mein Herz mit Traurigkeit. Zwei unserer tödlichsten Feinde schließen sich zusammen und einer der teuersten Söhne Shattraths hat seinen Glauben verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10382] = { id = 10382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht zur Front", description = "Nun, {name}, ich hoffe, Ihr seid für die nächste Phase unserer Operation bereit. Die Legion schläft nicht - und wir auch nicht! Nehmt einen Greifen und fliegt zum Ehrenposten, einem kleinen Lager in der Nähe der Front der Legion.\n\nSprecht mit Feldmarschall Brock. Er wird bei Eurer Ankunft Anweisungen für Euch bereithalten. Oh, und sagt diesem teiggesichtigen Schildschmuser einen Gruß von mir.", sourceObjective = "Nehmt einen Greifen zum Ehrenposten und sprecht mit Feldmarschall Brock.", completion = "Das trifft sich gut, {class}. Ich bin froh, dass dieser brummige alte Zwerg es endlich auf die Reihe bekommen hat, uns ein wenig Hilfe zu schicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[10383] = { id = 10383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies ist ein Brotkrumen!", description = "Hallo. Ihr solltet mehr über diese Kaninchen herausfinden.", sourceObjective = "Sprecht mit Jonathan LeCraft über die Kaninchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10384] = { id = 10384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daten der Astralen", description = "Seht Euch um, Fleischling. Ganz in der Nähe des Transponders sollte sich eine Datenzelle des Astraleums befinden. Sucht sie, öffnet sie und entnehmt den Inhalt.\n\nBringt sie dann sofort zu diesem Transponder zurück!", sourceObjective = "Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr die Datenzelle des Astraleums besorgt.", progress = "Habt Ihr die Datenzelle sichergestellt?", completion = "<Ihr haltet die Datenzelle so, dass Ameer die Pläne lesen kann.>\n\nNichts... Verdammt! Sie sind klug, aber nicht so klug wie Ameer!\n\nWorum ich Euch nun bitte, wird etwas gefährlich werden. Ich kann verstehen, wenn Ihr nicht weitermachen wollt, Fleischling.", sourceObjectiveStatus = "unverified-source-field" }
quests[10385] = { id = 10385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hirnschadengefahr = hoch", description = "Sie benutzen Melder, um die Informationen im Stützpunkt zu verteilen.\n\nEs gibt nur einem Weg, wie Ihr die Melder sehen und ihre Informationen extrahieren könnt. Unglücklicherweise könntet Ihr dadurch einen irreparablen Hirnschaden erlangen.\n\nWenn Ihr immer noch interessiert seid, müsst Ihr einige der Anhänger des Astraleums hier erschlagen und ihre Essenz nehmen. Wenn Ihr eine Essenz habt, trinkt sie. Mit ihrer Hilfe werdet Ihr für kurze Zeit in der Lage sein, die Melder des Astraleums zu sehen. Die Zeit reicht aus, um einen Melder zu zerstören und seine Informationen zu extrahieren.", sourceObjective = "Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr 15 Melderdaten des Astraleums besorgt.", progress = "Habt Ihr die Melderdaten schon besorgt?", completion = "Der Existenzgrund des Protektorats ist nun vollkommen bestätigt.\n\nDas Astraleum ist nicht hier, um Dimensius zu jagen! Sie sind hier, um Leere zu werden!\n\nSie manipulieren die Leerenergien bei dieser Manaschmiede um ihre eigenen Energien an eine Kreatur namens Dunkelpirscher zu binden.\n\nSie benutzen sicherlich einen Protobeschleuniger um die Umwandlung zu vervollständigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10386] = { id = 10386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Teufelshäschertöter", description = "Oberanführer Hun Stümmelfaust sucht immer nach Freiwilligen für seine selbstmörderischen Angriffe auf die Brennende Legion. Ihr verfügt definitiv über dem Mut für seine \"Missionen\".\n\nSprecht mit ihm, wenn Ihr Appetit auf noch mehr Gemetzel habt. Er feiert gerade da drüben bei dem gefallenen Teufelshäscher. Er und seine Wachen haben ihn vor ein paar Stunden vernichtet. Hätte er nicht so wild und geschickt gekämpft, wären wir jetzt alle tot.", sourceObjective = "Sprecht mit Oberanführer Hun Stümmelfaust.", sourceObjectiveStatus = "unverified-source-field" }
quests[10387] = { id = 10387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Teufelshäschertöter", description = "Oberanführer Hun Stümmelfaust sucht immer nach Freiwilligen für seine selbstmörderischen Angriffe auf die Brennende Legion. Ihr verfügt definitiv über dem Mut für seine \"Missionen\".\n\nSprecht mit ihm, wenn Ihr Appetit auf noch mehr Gemetzel habt. Er feiert gerade da drüben bei dem gefallenen Teufelshäscher. Er und seine Wachen haben ihn vor ein paar Stunden vernichtet. Hätte er nicht so wild und geschickt gekämpft, wären wir jetzt alle tot.", sourceObjective = "Sprecht mit Oberanführer Hun Stümmelfaust.", sourceObjectiveStatus = "unverified-source-field" }
quests[10388] = { id = 10388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Thrallmar", description = "Ich hoffe, Ihr hattet einen guten Flug, mein Freund. Während Ihr fort wart, ist ein Bote angekommen. Wie es aussieht, hat Nazgrel einen neuen Auftrag für Euch. Am besten geht Ihr nach Thrallmar zurück und sucht ihn auf. Ich habe das Gefühl, dass die Legion gerade erst warm geworden ist.", sourceObjective = "Kehrt nach Thrallmar zurück und sprecht mit Nazgrel.", completion = "Ah, {name}, Ihr kommt genau zur rechten Zeit. Unsere Späher haben herausgefunden, dass es sich bei den Ansammlungen der Legion auf dem Grat hinter uns tatsächlich um 'Konstruktionslager' handelt. Dort stellen die Dämonen ihre infernalen Teufelshäscher her. Wenn wir schnell gegen sie vorgehen, können wir vielleicht ihre Produktion aufhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10389] = { id = 10389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leid und die Dunkelheit", description = "Grüße, {name}. Ich habe den Schriftwechsel der Legion entziffert und ihre strategischen Pläne für die Halbinsel aufgedeckt. Offensichtlich sammelt sich in der Nähe der Teiche von Aggonar im Westen eine große Gruppe von teuflischen Terrorbestien. Das dürfen wir nicht ohne Kampf zulassen. Ihr müsst Euch dorthin begeben und ihre verfluchten Reihen ausdünnen.", sourceObjective = "Magister Blutfalke möchte, dass Ihr 10 Terrorbestien bei den Teichen von Aggonar tötet.", progress = "Nun, {class}? Habt Ihr die Terrorbestien besiegt?", completion = "Bravo, {name}. Ich wusste, dass Ihr Erfolg haben werdet! Das Ende der Legion rückt immer näher!", sourceObjectiveStatus = "unverified-source-field" }
quests[10390] = { id = 10390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager: Mageddon", description = "{name}, wir haben guten Grund zu vermuten, dass das Konstruktionslager, das sich am östlichsten befindet, noch nicht fertig ist. Die Gan'argsklaven der Legion arbeiten rund um die Uhr, um die Einrichtung zum Laufen zu bringen. Das können wir nicht zulassen.\n\nBegebt Euch nach Osten zum Konstruktionslager: Mageddon und tötet 10 Gan'arg. Bringt mir den Kopf ihres Meisters, Schmiedebestie Sägeklinge! So werden wir die Teufelshäscherproduktion der Legion zum Erliegen bringen!", sourceObjective = "Nazgrel in Thrallmar möchte, dass Ihr das Konstruktionslager: Mageddon angreift, 10 Diener der Gan'arg tötet und mit Schmiedebestie Sägeklinges Kopf zurückkehrt.", progress = "Beeilt Euch, {class}. Wir müssen das Konstruktionslager: Mageddon vernichten, bevor die Dämonen mit dem Bau fertig sind!", completion = "Gut gemacht, {class}. Ein Konstruktionslager weniger, um das wir uns sorgen müssen. Die Legion wird eine Weile brauchen, um die Einrichtung wieder zum Laufen zu bringen. Ihr habt uns das beschafft, was uns im Augenblick am meisten fehlt: Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10391] = { id = 10391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonen des Zorns", description = "Es gibt eine weitere Produktionsstätte. Das Konstruktionslager: Zorn liegt direkt im Nordosten von Thrallmar. Die Dämonen haben eine Reihe von Teufelskanonen am Grat entlang aufgestellt - und sie zielen direkt auf uns! Ihr müsst in das Lager eindringen und diese Kanonen außer Gefecht setzen.\n\n{name}, Ihr müsst sichergehen, dass Ihr alle zerstört - sonst kann die Legion nichts daran hindern, uns mit den Feuern der Hölle zu versengen!", sourceObjective = "Zerstört 3 Teufelskanonen V1 im Konstruktionslager: Zorn und kehrt dann zu Nazgrel in Thrallmar zurück.", completion = "Ich wusste, dass Ihr Biss habt, {name}, aber dieses Mal habt Ihr Euch selbst übertroffen! Wir haben die Explosionen dieser verfluchten Kanonen bis hierher gehört! Das müsste der Legion beweisen, dass sie die Söhne Durotars nicht unterschätzen sollten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10392] = { id = 10392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwelle zum Abgrund", description = "Ihr ehrt uns, {name}. Aber nun müssen wir zuschlagen, bevor die Legion sich erholt! Nördlich von Thrallmar liegt der Invasionspunkt: Vernichter. Dort befindet sich ein Warpportal, durch das die Legion ihre Verstärkung bezieht.\n\nIhr müsst dieses Portal überlasten - und es zurück in den Abgrund schicken, aus dem es gekommen ist. Den Aktivierungsschlüssel trägt vermutlich der Kommandant des Punkts, Kriegshetzer Arix'Amal, bei sich. Tötet ihn. Benutzt dann den Schlüssel bei dem Portal und tut, was getan werden muss. Möge der Segen des Kriegshäuptlings auf Euch ruhen.", sourceObjective = "Tötet Arix'Amal und nehmt Euch den Torschlüssel der Brennenden Legion. Benutzt den Schlüssel bei der Rune der Bosheit und kehrt danach zu Nazgrel in Thrallmar zurück.", progress = "Beeilt Euch, {name}. Mit jeder Sekunde, in der das Warpportal offen steht, betritt ein weiterer Dämon diese Welt.", completion = "Gelobt seien die Ahnen, Ihr habt es geschafft, {name}! Die Legion hat eine schreckliche Niederlage einstecken müssen. Thrallmar ist wieder sicher. Ach, wenn ich doch nur hundert Krieger mit Eurem Herz und Eurem Verstand hätte, dann wäre dieses zerschlagene Land schon längst gezähmt. Ich salutiere vor Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10393] = { id = 10393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boshafte Pläne", description = "Der Text auf dem Brief ist in dunklem, unentzifferbarem Gekrakel geschrieben. Je mehr Ihr sie anstarrt, desto mehr Symbole scheinen sich vor Euren Augen zu drehen und zu leuchten. Es gibt nur einen in Thrallmar, der so eine bösartige Schrift entziffern kann - der Blutelfenmagister Blutfalke.", sourceObjective = "Bringt den Schriftwechsel der Legion zu Magister Blutfalke in Thrallmar.", progress = "Ich habe nicht viel Zeit, {class}. Womit wollt Ihr mich belästigen?", completion = "Es war ganz richtig von Euch, mir dies zu bringen. Es könnte sich um einen Befehl zur Herstellung von zusätzlichen Teufelshäschern handeln - oder um neue Angriffspläne! Es wird etwas dauern, bis ich es entziffert habe. Lasst mich alleine. Ich lasse Euch rufen, wenn ich Genaueres weiß.\n\n<Magister Blutfalke nickt Euch zu, als Ihr Euch abwendet.>\n\nIhr seid sehr gescheit, {name}. Ich werde Eure Fortschritte mit Interesse verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10394] = { id = 10394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterbrechung beim Konstruktionslager: Mageddon", description = "Passt genau auf, {name}. Wir haben die Lager der Legion, die entlang des Grats vor uns liegen, überwacht. Wir haben guten Grund zur Annahme, dass die Dämonen in diesen so genannten 'Konstruktionslagern' ihre verdammten Teufelshäscher herstellen.\n\nIhr könnt das am nächsten gelegene Ziel, das Konstruktionslager: Mageddon von hier aus im Westen sehen. Unsere Geheimagenten melden, dass es sich immer noch im Bau befindet. Wenn Ihr die Gan'argdiener und ihren Meister, Schmiedebestie Sägeklinge, tötet, können wir der Teufelshäscherproduktion der Legion ein schnelles Ende machen!", sourceObjective = "Tötet 10 Diener der Gan'arg und Schmiedebestie Sägeklinge im Konstruktionslager: Mageddon und kehrt danach zu Feldmarschall Brock beim Ehrenposten zurück.", progress = "Sagt mir nicht, dass Ihr kalte Füße bekommen habt, {class}! Wenn sie die Bauarbeiten im Konstruktionslager abschließen, müsst Ihr Euch um mehr als nur die Teufelshäscher Gedanken machen. An die Arbeit!", completion = "Nun, ich muss zugeben, ich bin beeindruckt, {name}. Ich hätte nicht gedacht, dass Ihr den Schneid für diese Mission habt. Wirklich gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10395] = { id = 10395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Schriftwechsel", description = "Der Text auf dem Brief ist in dunklem, unentzifferbarem Gekrakel geschrieben. Je mehr Ihr sie anstarrt, desto mehr Symbole scheinen sich vor Euren Augen zu drehen und zu leuchten. Es gibt nur einen in der Ehrenfeste, der so eine bösartige Schrift entziffern kann - der Draeneimystiker Kryv.\n\nBringt den Schriftwechsel der Brennenden Legion zu Warpseher Kryv im Kriegsraum der Ehrenfeste.", sourceObjective = "Bringt den Schriftwechsel zu Warpseher Kryv in der Haupthalle der Ehrenfeste.", progress = "Was ist los, {class}? Ich spüre, dass Ihr etwas gefunden habt, dass von Verdammnis kündet.", completion = "Welch glücklicher Zufall, dass Ihr diesen Schriftwechsel abgefangen habt, {name}. Ich werde zwar etwas Zeit brauchen, bis ich ihn entziffert habe, aber ich kann den Hass und die Eile, die in dieser Schriftrolle stecken, deutlich spüren. Ich habe das Gefühl, dass die wahren Pläne der Legion in dieser Welt sich bald offenbaren werden...\n\nGebt mir einen Moment Zeit, um die Schrift zu entziffern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10396] = { id = 10396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind meines Feindes...", description = "Jetzt müssen wir uns auf unser zweites Ziel konzentrieren, das Konstruktionslager: Zorn. Es liegt direkt westlich von Mageddon. Das Problem ist, dass die Dämonen eine Reihe von Teufelskanonen direkt auf den Außenposten der Horde in Thrallmar gerichtet haben! Ich kann es zwar kaum fassen, aber wir müssen der Horde helfen, um unsere Linien beim Dunklen Portal aufrechtzuerhalten. Wir können es uns nicht erlauben, Thrallmar fallen zu lassen. Ihr müsst alle Kanonen zerstören, bevor die Legion unsere Verbündeten in die Luft jagt!", sourceObjective = "Zerstört 3 Teufelskanonen V1 im Konstruktionslager: Zorn und kehrt dann zu Feldmarschall Brock beim Ehrenposten zurück.", progress = "Die Legion könnte die Horde jederzeit unter Beschuss nehmen, {name}! Ihr müsst diese verdammten Kanonen zerstören!", completion = "Eines muss ich Euch lassen, {name}, Ihr seid ein geborener Kämpfer! Diese Tölpel der Horde werden vielleicht nie erfahren, wie knapp sie ihrem Ende entronnen sind. Es erfordert sehr viel Rückgrat, um dem Unheil im Namen seiner eigenen Feinde entgegenzutreten. Genau diese Ehre und dieses Pflichtgefühl machen die Allianz aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[10397] = { id = 10397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Vernichter", description = "Wir haben die letzte Basis der Legion auf dem Grat ausgemacht. Der Invasionspunkt: Vernichter liegt nordwestlich des Konstruktionslagers: Zorn. Dort befindet sich ein Warpportal, mit dessen Hilfe die Legion Verstärkung herbeiholt!\n\nIhr müsst an dieses Portal herankommen und verhindern, dass noch mehr Dämonen dadurch in unsere Welt kommen. Der Oberanführer des Punkts, Kriegshetzer Arix'Amal, hat den Aktivierungsschlüssel für das Portal. Nehmt ihn ihm ab und schaltet dieses verdammte Tor ab!", sourceObjective = "Tötet Arix'Amal. Nehmt den Torschlüssel der Brennenden Legion und benutzt ihn bei der Rune der Bosheit.", progress = "Habt Ihr das Warpportal schon geschlossen, {name}? Während Ihr hier herumtrödelt kommen immer mehr Dämonen in die Scherbenwelt!", completion = "Gute Arbeit! Das sollte die Zahl der Dämonen, die uns auf die Pelle rücken, dramatisch verringern. Ich kann Euch nicht genug für Eure Hilfe danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10399] = { id = 10399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz der Dunkelheit", description = "Es ist genau so, wie ich befürchtet habe. Der Dämon, den Ihr unlängst getötet habt, Arix'Amal, stand im Dienst des heimlichen Legionslords Arazzius des Grausamen. Wie es scheint hat dieser Bösewicht eine neue Streitmacht von höllischen Terrorbestien in der Nähe der Teiche von Aggonar aufgestellt.\n\nIhr müsst Euch dorthin begeben und die Terrorbestien vernichten, bevor sie uns angreifen können. Aber seid vorsichtig, Freund. Die Teiche von Aggonar liegen in einem gemarterten, giftigen Tal. Ihr findet die verfluchten Teiche nordwestlich von hier, hinter der Höllenfeuerzitadelle.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Tötet 10 Terrorbestien bei den Teichen von Aggonar und kehrt dann zu Warpseher Kryv in der Haupthalle der Ehrenfeste zurück.", completion = "Ich habe diesen großartigen Sieg vorausgesehen, {name}. Die gesegneten Naaru schenken Euch an diesem Tag ihr Lächeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[10400] = { id = 10400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberanführer", description = "Der ehrwürdige Warpseher hat mir von Euren waghalsigen Abenteuern erzählt, {name}. Er sprach auch von dem neuen Feind, den Ihr entdeckt habt. Dieser Arazzius der Grausame ist der mächtigste und bösartigste Feind, dem die Söhne Lothars sich je stellen mussten.\n\nWerdet Ihr uns zur Seite stehen, {name}? Werdet Ihr diesem Legionslord gegenübertreten und ihn der Gerechtigkeit des Lichts übergeben? Wenn ja, dann begebt Euch zu den Teichen von Aggonar. Wenn Ihr ihn nicht findet, wird seine Bosheit sicher Euch finden.", sourceObjective = "Tötet Arazzius den Grausamen bei den Teichen von Aggonar und kehrt danach zu Truppenkommandant Danath Trollbann in der Ehrenfeste zurück.", completion = "Dem Licht sei Dank, ich wusste, dass Ihr es schafft! Arazzius und seine Diener sind Geschichte! Bald wird die Legion nach Hause flüchten und diese geschundene Welt wird wieder sicher sein. Und dann, wenn endlich Gerechtigkeit herrscht, können auch wir nach Hause gehen. \n\nVielen Dank, {name}. Die Allianz und die Söhne Lothars feiern Euch heute!", sourceObjectiveStatus = "unverified-source-field" }
quests[10403] = { id = 10403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naladu", description = "Vielleicht ist noch nicht alle Hoffnung für das Lumpenpack verloren. Ich bin einer der vier Ältesten, die diesen Stamm leiteten, bevor wir von den Illidari versklavt wurden. Ich dachte, dass die anderen tot seien, aber dann habe ich erfahren, dass zumindest zwei weitere noch am leben sind - angekettet und machtlos, so wie ich.\n\nIch habe Naladu noch nicht finden können und befürchte das Schlimmste. Oben in den Ruinen gibt es noch mehr Hütten, vielleicht könntet Ihr dort nach ihm suchen. Es wäre ein großes Glück für unseren Stamm, wenn alle Ältesten am Leben wären.", sourceObjective = "Sucht Naladu in den Ruinen von Sha'naar.", completion = "Ihr seid gekommen, um meinem Stamm zu helfen, {race}? Wie ungewöhnlich. Es gibt nicht viele, die sich um das Schicksal der Zerschlagenen in diesem Land scheren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10404] = { id = 10404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Legion", description = "Wir haben erfahren, dass die Brennende Legion Kael'thas mit technologischem Wissen unterstützt hat, und so die Bedrohung, die von ihm ausgeht, noch um ein Vielfaches vergrößert hat.\n\nDa die Legion in der Gegend so zahlreich vertreten ist, können wir den größten Schaden nur durch einen gezielten Angriff auf die Konstruktionsbasen im Norden erreichen.\n\nGeht zur Konstruktionsbasis: Vergessenheit und zur Konstruktionsbasis: Gehenna und zerstört unsere Feinde. Möge das Licht Eure Klinge führen, {name}.", sourceObjective = "Exarch Orelis in Area 52 möchte, dass Ihr zur Konstruktionsbasis: Vergessenheit und zur Konstruktionsbasis: Gehenna geht und 12 Feuerfäuste der Gan'arg, 6 Konstruktionsherren der Gan'arg und 6 Zornschaffer tötet.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10405] = { id = 10405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "S-A-B-O-T-A-G-E", description = "Wir müssen die Maschinen zerstören, die diese abnormalen Dunkelpirscher hervorbringen. Ihren Protobeschleuniger anzugreifen ist sinnlos, da es sich um eine astrale Erfindung handelt. Wir müssen stattdessen die Rohre der Manaschmiede, die sie als Energieleitung verwenden, zerstören.\n\nIch habe fast alles, was ich brauche, um ein Gerät herzustellen, das die Energieleitung überlasten kann. Ich brauche nur noch die Bandagen eines Archon oder Oberanführers, der sich bald verwandeln wird, um das Gerät einzustellen.", sourceObjective = "Das Bild von Kommandant Ameer bei dem Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr eine vorbereitete Bandage des Astraleums besorgt.", progress = "Habt Ihr die Bandage besorgt?", completion = "Ausgezeichnet! Jetzt kann ich das Gerät einstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10406] = { id = 10406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachricht überbringen", description = "Ich schicke einen meiner Demolierer los, um das Störgerät zu platzieren. Sorgt nur dafür, dass ihm kein Leid geschieht, während er den Störer aufstellt.\n\nBeschützt ihn! Er wird sich nicht wehren, wenn er von Feinden angegriffen wird, da er nur ein holografisches Bild ist, aber auch das kann zerstört werden!\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Das Bild von Kommandant Ameer bei dem Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr den Demolierer des Protektorats zur Energieleitung der Manaschmiede Ultris begleitet und ihn beschützt, während er die Leitung sabotiert.", progress = "Er muss Erfolg haben!", completion = "Dank Euch sind ihre Pläne gescheitert! Jetzt bleibt nur noch Eines übrig... Salhadaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10407] = { id = 10407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Socrethars Schatten", description = "Der berüchtigte Eredar, Socrethar, führt die Brennende Legion im Nethersturm an. Allein seinen Namen zu nennen lässt die meisten Draenei erzittern. Er erteilt seine Befehle von einer Insel im Nordwesten aus, die nur seine vertrauenswürdigsten Leutnants betreten können.\n\nUm dorthin zu gelangen, müsst Ihr einen Teleportationsstein besorgen, was nicht einfach wird. Die erste Hälfte des Steins befindet sich im Besitz von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit. Die zweite Hälfte hat der Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna.", sourceObjective = "Anachoret Karja in Area 52 möchte, dass Ihr die erste Hälfte von Socrethars Stein von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit und die zweite Hälfte des Steins von Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna besorgt.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr Socrethars Teleportationsstein schon besorgt, {name}?", completion = "Eure Aufopferung für unsere Sache ist beispielhaft, {name}. Jetzt, da wir Socrethars Teleportationsstein in unserem Besitz haben, gibt es nur noch Eines zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[10408] = { id = 10408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nexuskönig Salhadaar", description = "Ich habe einen weiteren Störer in meinem Besitz. Einer, der in der Lage ist, die drei Energieleitungen, die Salhadaar umgeben, zu zerstören. Wenn die Energieleitungen einmal vernichtet sind, werden sich Salhadaars schützende Kraftschilde senken. Für diese Tat wird er Euch mit einer Wildheit angreifen, die Ihr noch nie zuvor gesehen habt, {name}.\n\nWenn Ihr bereit seid, die Welt von Salhadaar zu befreien, gebe ich Euch den Störer.", sourceObjective = "Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr den Störer des Protektorats benutzt, um Salhadaar Kraftfelder zu senken und Nexuskönig Salhadaar zu vernichten.", progress = "Ist... Ist er wirklich tot? Vernichtet?", completion = "Seit tausend Jahren, vielleicht mehr, führt Salhadaar nun seinen Kreuzzug, bei dem er alles vernichtet, was ihm im Weg steht. Ich kann kaum glauben, dass wir ihn nun zum letzten Mal gesehen haben... Ihr habt uns einen großen Dienst erwiesen, {name}, und dafür sollt Ihr belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10409] = { id = 10409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesstoß für die Legion", description = "Wenn man mit mächtigen Eredar zu tun hat, sind große Armeen meist nutzlos. Ihre verderbte Macht über die sterblichen Seelen ist so stark, dass nur die mit einem starken Willen ihnen gegenübertreten können.\n\nBringt diesen Stein zum Invasionspunkt: Oberanführer zwischen der Konstruktionsbasis: Vergessenheit und der Konstruktionsbasis: Gehenna und nehmt Eure engsten und stärksten Freunde mit. Orelis und Karja erwarten Euch bei Socrethars Sitz. Ich werde Adyen mit ihnen losschicken.\n\nMöge das Licht sich heute behaupten, {name}. Möge Socrethars Ende nahen.", sourceObjective = "Hohepriesterin Ishanah möchte, dass Ihr zum Transporter der Legion am nordwestlichsten Ende des Nethersturms geht und Euch zu Socrethars Sitz teleportiert. Wenn Ihr dort seid, besiegt Socrethar.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Es ist vollbracht, {name}. Socrethar wurde vernichtet.\n\nIch und die anderen werden uns von unseren Wunden erholen, {name}. Der Zorn der Magie Socrethars war jedoch zu viel für den jungen Kaylaan. Nicht einmal meine stärksten Gebete konnten ihn wiederbeleben.\n\nEs ist unendlich schade, dass jemand, der so jung ist, in der Schlacht sterben musste. Am Ende war jedoch sein Wille stark genug, um sich von der Verderbtheit der Legion zu erholen. Dies soll uns ein Trost sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10410] = { id = 10410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishanahs Hilfe", description = "Die Zeit ist gekommen, da Ihr Euch Socrethar stellen müsst, {name}. Einem Eredar entgegen zu treten ist eine Aufgabe, die keiner von uns auf die leichte Schulter nimmt. Schon ein kleiner Fehler kann uns das Leben kosten, wenn wir unvorbereitet sind.\n\nBringt Socrethars Teleportationsstein zu Hohepriesterin Ishanah beim Schrein des Endlosen Lichts in Shattrath. Sie wird entscheiden, wie mit der Situation umzugehen ist.", sourceObjective = "Bringt Socrethars Teleportationsstein zu Hohepriesterin Ishanah beim Schrein des endlosen Lichts auf der Aldorhöhe in Shattrath.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Was bereitet Euch Kummer, Kind?", completion = "Socrethar... Ich erinnere mich an den Namen. Er war einst ein berühmter Krieger des Lichts. Sein einziger Fehler war sein Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10411] = { id = 10411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elektroschock!", description = "Um die zerstörte Manaschmiede herum findet Ihr die Überbleibsel von Dimensius' Taten. Sickernder Schlick verschmutzt die Teiche um Ultris herum. Direkt unter diesen Teichen, wo sich nun der Stützpunkt des Astraleums befindet, findet Ihr noch mehr Müll in Form von Leerenabschaum.\n\nDer beste Weg, ihn zu entsorgen, ist, den Schleim mithilfe von Elektroschocks in Kugeln zu verwandeln. Benutzt dieses Elixier, um Eure Angriffe unter Strom zu setzen. Die Entladung, die dabei entsteht, löst den Schleim in seine Urform auf. Zerstört die Kugeln!", sourceObjective = "Forscher Navuud im Wachposten des Protektorats im Nethersturm möchte, dass Ihr 30 Leerenabschaumkugeln und 30 Sickerschlickkugeln zerstört.", progress = "Sowohl der Schlamm als auch der Abschaum sind extrem giftig. Wenn wir uns nicht um sie kümmern, verwandeln sie sich in erstarrte Schrecken der Leere!", completion = "Ich hoffe, es ist nicht zu spät. Habt Ihr irgendwelchen abnormal großen Schleim in der Gegend, zu der es den Leerabschaum zieht, gesehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10412] = { id = 10412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Feuerschwingen", description = "Es ist kein Geheimnis, dass Kael'thas Sonnenwanderer uns als große Bedrohung sieht. Nüchtern betrachtet gibt es nicht viele Sin'dorei, die frisch aus Silbermond kommen und bereit sind, sich der Gesellschaft, die Kael'thas unterhält, anzuschließen.\n\nEs ist auch kein Geheimnis, dass es sich hier nicht nur um Wortgefechte handelt. Die Seher und die vielen Armeen, die Kael'thas dienen, haben und werden sich angreifen, sobald sie sich begegnen. Der einzige Weg, wie Ihr beweisen könnt, dass Ihr auf unserer Seite steht, ist, sich dem Kampf anzuschließen, {name}.\n\nKaels niederrangige Anhänger tragen Siegel der Feuerschwingen bei sich, die ihren Rang anzeigen. Bringt sie mir.", sourceObjective = "Magistrix Fyalenn in Shattrath möchte, dass Ihr ihr 10 Siegel der Feuerschwingen bringt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Los, {name}. Sprecht.", completion = "Gut gemacht, {name}. Vielleicht stellt Ihr Euch doch noch als nützlich heraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10413] = { id = 10413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schrecken der Verschmutzung", description = "Ihr befüllt vorsichtig eine Phiole mit dem Schlamm des gefallenen Leerenschreckens.\n\nForscher Navuud im Wachposten des Protektorats wäre an einem solchen Fund sicher interessiert. Bringt ihn sofort zu ihm!", sourceObjective = "Bringt die Phiole mit Leerenschreckensschlamm zu Forscher Navuud im Wachposten des Protektorakts im Nethersturm.", progress = "Hm, Ihr seht dreckig aus... Was ist geschehen?", completion = "WAS!? Ihr habt gegen einen Schrecken der Leere gekämpft? Und überlebt?! Unglaublich!\n\nDiese Probe ist ihr Gewicht in Gold wert. Ein Fund wie dieser verlangt eine Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[10414] = { id = 10414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Siegel der Feuerschwingen", progress = "Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, {name}. Unsere Feinde sind stark, aber wir werden siegen!", completion = "Ja... Kaels Leute schwinden, während wir wachsen.\n\n<Diese Quest kann wiederholt werden, bis Ihr den Ruf 'Wohlwollend' erlangt habt.>" }
quests[10415] = { id = 10415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Siegel der Feuerschwingen", progress = "Was habt Ihr in letzter Zeit für uns getan, {name}? Der Krieg gegen Kael'thas kämpft sich nicht von alleine, verstanden?", completion = "Ausgezeichnet! Alle, die sich uns in den Weg stellen, werden vernichtet!\n\n<Diese Quest kann wiederholt werden, bis Ihr den Ruf 'Wohlwollend' erlangt habt.>" }
quests[10416] = { id = 10416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bündelung der Macht", description = "Arkane Folianten sind keine gewöhnlichen Bücher, die sich mit arkanen Themen befassen. Ihnen wohnt eine wesenhafte Macht inne - eine Macht, die ich in eine einzelne arkane Rune bündeln kann.\n\nSolltet Ihr auf Euren Reisen einen arkanen Folianten finden, werde ich Euch eine solche Rune geben. Nur die mächtigsten magiebegabten Wesen tragen die Bücher, die ich brauche, bei sich. In der Scherbenwelt sind das meistens Kaels Blutelfen, aber Ihr wärt überrascht, wo solche Bücher des Öfteren auftauchen.", sourceObjective = "Voren'thal der Seher in Shattrath möchte, dass Ihr einen arkanen Folianten besorgt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr schon einen arkanen Folianten besorgt, {name}?", completion = "Wie versprochen, {name}. Die Gesamtheit der ureigenen Macht des Buches, gepackt in eine einzelne Rune.", sourceObjectiveStatus = "unverified-source-field" }
quests[10417] = { id = 10417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Führt eine Diagnose durch!", description = "Wo auch immer das Konsortium Einzug hält, bringen wir unsere Biokuppeltechnologie mit. Diese Technologie erlaubt uns, in einer kontrollierten und lebenserhaltenden Atmosphäre zu arbeiten, da wir uns meist in feindlichen Gebieten befinden.\n\nDie bösartigen Bedingungen und Kreaturen des Nethersturms haben begonnen, die Ausrüstung, die unsere Biokuppeln aufrechterhält, zu zerstören, besonders den Generator im Osten. Ich habe einen Diagnoselauf dort begonnen, damit ich hoffentlich herausfinden kann, was gegen den Schaden getan werden kann. Könntet Ihr die Resultate dort abholen und zu mir bringen?", sourceObjective = "Beschafft die Diagnoseergebnisse und bringt sie zu Mehrdad im Mittelreichposten.", progress = "Habt Ihr die Diagnoseergebnisse?", completion = "<Mehrdad nickt und betrachtet die Diagnoseergebnisse.>\n\nDas ist beunruhigend. Der Schaden ist größer, als ich befürchtet habe. Ich kann mir aus der Sturmsäule einige Werkzeuge schicken lassen, um Reparaturen durchzuführen, aber das ist sinnlos, wenn wir nicht einmal wissen, was den Schaden verursacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10418] = { id = 10418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Saboteure ausschalten", description = "Als ich das Gebiet nach Hinweisen auf den Schaden unserer Ausrüstung abgesucht habe, habe ich Teile der Schildgeneratoren auf dem Grund des kleinen Sees im Norden gesehen. Ich bin mir nicht sicher, warum die Krokilisken sich für unsere Ausrüstung interessieren, aber wir müssen dieses Problem beseitigen.\n\nDas Konsortium ist sich in dieser Sache einig. Wenn es zu einer Entscheidung zwischen der Ausrüstung und Krokilisken kommt, müssen die Tiere gehen. Ich werde Euch angemessen belohnen, wenn Ihr Euch darum kümmert.", sourceObjective = "Mehrdad beim Mittelreichposten möchte, dass Ihr 8 Stachelschuppenkrokilisken tötet.", completion = "Das Gebiet sieht schon aufgeräumter aus. Die Kuppeln sind sehr hilfreich, aber ein großer Nachteil ist der unkontrollierte Wuchs, den sie an manchen Orten begünstigen, der die einheimischen Arten schneller wachsen und sich schneller vermehren lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10419] = { id = 10419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Folianten", progress = "Habt Ihr noch mehr arkane Folianten besorgt, {name}?", completion = "Die Macht in diesem Folianten ist enorm. Und doch kann er von jemandem mit klarem Verstand in eine einzelne Rune verwandelt werden." }
quests[10420] = { id = 10420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein reinigendes Licht", description = "Dieser Tempel ist eine der heiligsten Stätten der ganzen Scherbenwelt. Die Macht des Lichts ist hier so stark, dass es weltliche Gegenstände sogar von der schlimmsten teuflischen Verderbnis befreien kann.\n\nFalls Ihr bei Euren Kämpfen mit den dämonischen Feinden teuflische Waffen finden solltet, bringt sie zu mir. Dann werde ich Euch die reinigende Kraft des Lichts beweisen.", sourceObjective = "Bringt eine Ladung teuflische Waffen zu Ishanah in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr schon ein paar teuflische Waffen besorgt?", completion = "Schaut zu, wie die verderbten Materialien sich auflösen. Schaut zu, wie sich Metall in Staub verwandelt.\n\nDas Licht reinigt alles, und nur die reinsten Überreste bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10421] = { id = 10421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Waffen", progress = "Habt Ihr in letzter Zeit ein paar teuflische Waffen gefunden? Lasst das Licht seine Wirkung tun, {name}. Erlaubt diesen verderbten Dingen nicht, in dieser Welt zu verweilen.", completion = "Die teuflischen Materialien wurden aus dieser Welt entfernt. Nur das Licht bleibt." }
quests[10422] = { id = 10422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptmann Tyralius", description = "Hauptmann Tyralius hat eine Truppe von Soldaten vor 10 Tagen in Richtung des Stützpunkts des Astraleums geführt. Seitdem haben wir nichts von ihm oder seinen Leuten gehört.\n\nEs ist sehr wahrscheinlich, dass sie überfallen und getötet wurden, aber ich bekomme ein merkwürdiges Signal auf meinen Instrumenten.\n\nIch glaube, es ist ein Notsignal, aber diese Dinge haben sich schon öfter geirrt. Wenn Tyralius noch am Leben ist, halten sie ihn in einem Ihrer Gefängnisse fest. Ihr müsst das Gefängnis finden und es mit einem Schlüssel, den Ihr wahrscheinlich bei einem Wärter finden könnt, öffnen.", sourceObjective = "Fleischtreiber Viridius im Wachposten des Protektorats im Nethersturm möchte, dass Ihr Hauptmann Tyralius findet und befreit.", completion = "Danke, {name}. Tyralius hat schwere Wunden erlitten, aber wir denken, dass er es schaffen wird.\n\nEr hat ganze Felder voller Gefängnisse erwähnt, die so ähnlich sind wie das, aus dem Ihr ihn errettet habt. Gefängnisse voller Kreaturen aus dem ganzen Universum!\n\nWir werden uns bei Euch melden, wenn wir entschließen sollten, sie zu öffnen. Das Konsortium hat schon angemeldet, dass sie planen, ein paar Teams dorthin zu schicken. Sie arbeiten bereits an einer Technologie, mit der sie die Schlösser des Astraleums aufbrechen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10423] = { id = 10423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Sturmsäule", description = "Meisteringenieur Ghabar möchte sicher die Ergebnisse der Diagnose erfahren. Sie zeigen uns wenigstens, dass wir die Funktionalität der Kuppelgeneratoren genau im Auge behalten müssen. Wenn die Felder immer instabiler werden, können wir ihre Auswirkungen auch immer schwerer kontrollieren. Das könnte ein Desaster für unsere Expedition und alles, was sich in den Kuppeln befindet, bedeuten.\n\nIhr findet Ghabar in der Sturmsäule. Folgt einfach der Straße nördlich dieser Biokuppel und überquert die Brücke. Sie führt Euch direkt zum Aufzug unten in der Säule.", sourceObjective = "Sprecht mit Ghabar in der Sturmsäule im Nethersturm.", completion = "<Ihr stellt Euch vor und meldet die Ergebnisse von Mehrdads Diagnose bei der Biokuppel Mittelreich.>\n\nMehrdad ist nur ein einfacher Techniker, aber er hat ein gutes Auge fürs Detail. Wenn seine Beobachtungen richtig sind, müssen wir auch bei den restlichen Kuppelgeneratoren so schnell wie möglich Diagnosen durchführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10424] = { id = 10424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diagnose: kritisch", description = "Wenn Mehrdads Ergebnisse richtig sind - und ich habe keinen Grund daran zu zweifeln - könnte der Rest der Kuppeln in Gefahr sein.\n\nIch glaube jedoch, dass Mehrdad nicht den richtigen Grund für die Defekte gefunden hat. Tiere können die Generatoren bisweilen schon beschädigen, aber niemals so schwer.\n\nUm sicher zu gehen, möchte ich, dass Ihr ein paar Diagnoseläufe bei dem Hauptkuppelgenerator der Sturmsäule am östlichen Rand in der Biokuppel Sutheron durchführt.", sourceObjective = "Benutzt das Diagnosegerät in der Nähe des Generators der Biokuppel Sutheron und bringt die Diagnoseergebnisse zu Ghabar in der Sturmsäule zurück.", progress = "Habt Ihr die Diagnoseergebnisse?", completion = "Diese Ergebnisse entsprechen denen von Mehrdad genau, aber warum? Der einzige Grund, den ich mir vorstellen kann, ist, dass etwas von der Ausrüstung der Kuppelgeneratoren kaputtgegangen ist oder fehlt. Das würde dazu führen, dass die Kuppeln stark geschwächt werden und aus dem Gleichgewicht geraten, so wie es in der Diagnose deutlich wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10425] = { id = 10425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Stützpunkt", description = "K'aresh sei Dank! Er hätte mich in Stücke gerissen!\n\nIch bin ein Soldat des Protektorats, Fleischling. Meine Truppe wurde vor etwa 10 Tagen auf eine Aufklärungsmission geschickt. Als wir uns über die oberen Regionen dieser Insel bewegten, wurden wir von einer Gruppe des Astraleums überfallen. Zumindest denke ich, dass es das Astraleum war. Sie hatten die gleichen Energiefarben, aber ihre Bandagen sahen irgendwie leer aus.\n\nSie haben nur Tyralius verschont. Ich glaube, sie haben ihn in ein Gefängnis eingesperrt.\n\nIch muss zurück zum Wachposten des Protektorats! Könnt Ihr mich dorthin begleiten?", sourceObjective = "Begleitet den gefangenen Vorposten des Protektorats zurück zum Wachposten des Protektorats im Nethersturm.", completion = "<Kommandant Ameer scheint zufrieden zu sein.>\n\nGut gemacht, Fleischling! Dieser Soldat ist vielleicht der Schlüssel zur Vereitelung aller Pläne des Astraleums.", sourceObjectiveStatus = "unverified-source-field" }
quests[10426] = { id = 10426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flora der Biokuppel", description = "Schaut Euch nur um, {class}! Ist es nicht erstaunlich? Natürlich ist diese unglaubliche Fülle von Leben ein Nebenprodukt der Kuppeln der Astralen, aber stellt Euch nur vor, was diese Technologie in den Händen der Expedition bedeuten könnte.\n\nIch bereite mich darauf vor, mit den Astralen zu verhandeln, um Zugang zu ihrer Technologie zu bekommen, aber ich wüsste zuvor gerne genauer, welche Auswirkungen sie auf das pflanzliche Leben hat.\n\nIch habe ein Gerät gebaut, mit dem ich die Energien auf die Peitscher in dieser Gegend richten kann. Wärt Ihr so nett und würdet es für mich ausprobieren und mir die Ergebnisse mitteilen?", sourceObjective = "Benutzt den Energiefeldmodulator bei den Farahlonpeitschern. Beobachtet die Ergebnisse und meldet Euch bei Aurine Mondflamm in der Sturmsäule zurück, wenn Ihr 10 Tests durchgeführt habt.", progress = "Habt Ihr schon versucht, die Energie der Kuppel zu fokussieren?", completion = "Oh je! Die Energie der Kuppel zu bündeln hat zur Folge, dass die Kreaturen bis zu dem Punkt wachsen, an dem sich eine große Aggressivität entwickelt. Wenn wir die Möglichkeit bekommen, diese Technologie einzusetzen, müssen wir sie auf jeden Fall richtig einstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10427] = { id = 10427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fauna der Biokuppel", description = "Eure Arbeit bei den Peitschern stellte sich als erstaunliche Information heraus, aber ich frage mich, ob das auch für die Tiere gilt.\n\nIch fürchte jedoch, dass es schwieriger wird, Informationen über die Talbuks zu sammeln, als über die Peitscher.\n\nMit diesem Markierungsgerät könnt Ihr einen geschwächten Talbuk schlafen legen und ihn mit einer Markierung versehen, mit deren Hilfe ich das Tier während seiner Wachstumsphase verfolgen kann. Der Mechanismus des Markierungsgeräts funktioniert erst, wenn der Talbuk schon sehr erschöpft ist.", sourceObjective = "Markiert 12 Talbuks für Aurine Mondflamm in der Sturmsäule. Ihr könnt mit dem Talbukmarkierer sowohl Talbukböcke als auch Talbukkühe markieren.", progress = "Konntet Ihr ausreichend viele Talbuks markieren?", completion = "Ausgezeichnete Arbeit. Ich werde die, die Ihr markiert habt, genau im Auge behalten, um zu beobachten, ob sie genauso schnell wie die anderen Lebensformen in der Kuppel wachsen.\n\nMit der richtigen Überwachung könnten wir diese Technologie benutzen, um die zerstörten Gegenden in der Scherbenwelt und Azeroth wiederzubeleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10428] = { id = 10428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Fischer", description = "Von fiebrigen Träumen geplagt sprach unser verletzter Gast von einem Fischer, Cowlen, der auf der Silbermythosinsel im Südwesten vor der Küste der Azurmythosinsel, in Schwierigkeiten war.\n\nNach all den Geschehnissen hier hatte keiner die Gelegenheit, nachzuschauen, aber ich mache mir doch ein paar Sorgen. Vielleicht könnt Ihr etwas tun, {name}?", sourceObjective = "Sucht Cowlen bei den südöstlichen Docks der Silbermythosinsel vor der Küste der Azurmythosinsel.", completion = "Meine Familie... Was habe ich getan... Was hätte ich tun sollen?\n\nWarum werde ich so bestraft?", sourceObjectiveStatus = "unverified-source-field" }
quests[10429] = { id = 10429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn die Natur zu weit geht", description = "Die Technologie der Kuppeln ist so mächtig! Sicher gibt es Grenzen, die wir nicht zu überschreiten wagen, {name}.\n\nWesen, die zu schnell oder zu groß wachsen, können genauso schlimm sein wie eine unfruchtbare Landschaft.\n\nIch habe Gerüchte gehört, dass sich genau so eine Kreatur im Teich im Osten herumtreibt. Die Händler der Astralen wollen die übergroße Hydra aus Spaß erlegen, aber ich habe etwas anderes mit dem Riesen vor. Bringt mir das Herz dieser Kreatur, damit ich es untersuchen kann.", sourceObjective = "Aurine Mondflamm in der Sturmsäule möchte, dass Ihr ihr ein titanisches Hydraherz bringt.", progress = "Habt Ihr eine Probe von der monströsen Hydra?", completion = "<Aurine nimmt das Herz an sich.>\n\nSogar für eine Kreatur von dieser Größe ist das Herz viel zu groß. Es musste sich sehr anstrengen, um mit dem riesigen Körper Schritt halten zu können. Ich habe keine Zweifel, dass sie nach der Hälfte ihrer normalen Lebenserwartung gestorben wäre.\n\nTrotz dieser Risiken bin ich entschlossen, die Astralen davon zu überzeugen, ihre Technologie mit anderen zu teilen. Es ist zu viel versprechend, als dass wir jetzt aufgeben sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10430] = { id = 10430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Prototyp testen", description = "Ich habe an einem tragbaren Reparatursatz für den Generator gearbeitet, der in den kälteren Regionen, in denen das Konsortium Geschäfte macht, funktioniert. Zugegeben, er war nicht für den Nethersturm entwickelt worden, aber wir sollten trotzdem keine Probleme damit haben.\n\nIch habe bereits einen Test mit einem meiner besten Techniker bei der Biokuppel Fernfeld hinter dem Netherstein im Nordosten vereinbart. Bringt diesen Prototypen zu Tashar. Er wird wissen, was damit zu tun ist. Wenn er funktioniert können wir ihn benutzen, um die Schildgeneratoren bei den größeren Kuppeln zu verstärken.", sourceObjective = "Bringt das Testreparaturgerät zu Tashar in der Biokuppel Fernfeld im Nethersturm.", progress = "Sieht aus, als hättet Ihr den Prototypen. Hat Ghabar Euch geschickt?", completion = "Er sieht ein wenig merkwürdig aus. Ghabar hatte sicher nicht den Nethersturm im Hinterkopf, als er ihn entwickelt hat.\n\nSchaut nicht so überrascht drein, {name}. Der Nethersturm ist harmlos im Vergleich zu einigen Orten, an denen ich gearbeitet habe. Doch eine kaputte Kuppel ist immer ein Grund zur Sorge.", sourceObjectiveStatus = "unverified-source-field" }
quests[10431] = { id = 10431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe von außen", description = "Die Befehle des Sonnenzorns bestätigen den Verdacht, dass Kael'thas bei dem Bau und dem Betrieb der Manaschmieden Hilfe von außen bekommen hat. Wer dahinter steckt, ist immer noch ein Geheimnis, doch wir können es wahrscheinlich in der Manaschmiede Ara herausfinden.\n\nIch habe eine Gruppe meiner Leute losgeschickt, um die Gegend zu erkunden. Geht zu Tulumans Landeplatz nördlich von hier und sprecht mit Kaylaan. Hört Euch an, was er in der Manaschmiede Ara gefunden hat. Findet heraus, wer die Armee des Sonnenzorns unterstützt, und kümmert Euch um sie.", sourceObjective = "Geht zu Tulumans Landeplatz, nördlich von Area 52, und sprecht mit Kaylaan.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Seid Ihr die ganze Hilfe, die Orelis schickt? Er muss eine hohe Meinung von Euch haben.\n\nLasst es uns hinter uns bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10432] = { id = 10432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindeutige Beweise", description = "Wie Ihr sicher bemerkt habt, laufen in der Manaschmiede Ara überall Diener der Brennenden Legion herum. Kael'thas ist einen Bund mit der Brennenden Legion eingegangen. Er muss gehört haben, dass Illidan dem Wahnsinn verfallen ist, und den Meister gewechselt haben.\n\nWenn die Seher dafür einen stichhaltigen Beweis hätten, wäre das ein deutlicher politischer Vorteil für sie. Ich weiß genau, dass die Streitkräfte der Legion bei der Manaschmiede hier Befehle haben, die Kaels Siegel tragen.\n\nBesorgt diese Befehle und bringt sie zu Thalodien.", sourceObjective = "Besorgt Euch 8 Befehle von Kael'thas von den Dämonen bei der Manaschmiede Ara und bringt sie zu Spionagemeister Thalodien in Area 52.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Nun? Was hatte Theledorn zu sagen?", completion = "Das ist eine große Sache, {name}. Sehr groß!\n\nVoren'thal möchte sicher so früh wie möglich davon erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10433] = { id = 10433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schein wahren", description = "Die Astralen sind sehr klug und aufmerksam, daher ist es kein Zufall, dass ich hier als einfacher Fellhändler auftrete. Tatsächlich wurde ich von Area 52 hierher geschickt, um die Technologie, die die Astralen in ihren Biokuppeln einsetzen, zu bewerten.\n\nIch würde gerne Eure Hilfe in Anspruch nehmen, {class}. Wir wurden darum gebeten, wo es nur geht andere Völker als Goblins als Spione einzusetzen.\n\nIch möchte, dass Ihr mir als Jäger verkleidet ein paar Reißzahnpelze bringt. Ihr findet die Luchse überall bei der Biokuppel Mittelreich.", sourceObjective = "Bringt 10 Reißzahnpelze zu Shauly Pore im Mittelreichposten.", progress = "<Shauly hebt die Stimme, um die Aufmerksamkeit der Astralen in der Nähe zu erregen.>\n\nHabt Ihr ein paar Pelze für mich?", completion = "<Shauly gibt vor, die Pelze zu bewundern.>\n\nSie sind wundervoll, wirklich wundervoll! Ich werde Euch den besten Preis dafür bezahlen! Was kosten mich Eure Dienste?", sourceObjectiveStatus = "unverified-source-field" }
quests[10434] = { id = 10434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dynamische Duo", description = "Ausgezeichnete Arbeit.\n\n<Shauly zwinkert Euch zu.>\n\nIch glaube, sie kaufen es uns ab. Wenn ich Euch jetzt zu meinen Verbündeten in der Sturmsäule schicke, werden sie nicht misstrauisch werden.\n\nHaltet nach Aktion Jaxon und Audi der Nadel Ausschau. Sie werden Euch alles sagen, was Ihr wissen müsst. Sagt ihnen, dass Shauly Euch geschickt hat.", sourceObjective = "Sprecht mit Audi der Nadel auf der Sturmsäule im Nethersturm.", completion = "<Ihr stellt Euch vor und sagt, dass Shauly Euch geschickt hat.>\n\nAh, ja, wir haben jemanden erwartet, der uns dabei hilft, äh -- ein paar, mh, Güter zu transportieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10435] = { id = 10435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waren zurückholen", description = "<Audi sieht sich um und senkt die Stimme.>\n\nIch bin sicher, dass Shauly Euch ein wenig von unserer Arbeit hier erzählt hat. Als Jaxon und ich draußen im Feld auf der Jagd waren, haben wir Teile von den Generatoren der Biokuppeln der Astralen gesammelt und sie in den Nestern unserer Beute, den Raptoren bei der Biokuppel Fernfeld, versteckt.\n\nDas ist eine abgelegene Gegend nordöstlich der Sturmsäule, in der Nähe des Nethersteins. Ich nehme nicht an, dass Ihr dort auf viele Astrale treffen werdet, aber würdet Ihr uns helfen, die Kuppelgeneratorenteile zu sammeln?", sourceObjective = "Audi die Nadel bei der Sturmsäule möchte, dass Ihr 10 Kuppelgeneratorsegmente besorgt.", progress = "Habt Ihr alles gesammelt?", completion = "Ausgezeichnete Arbeit! Der schwierigste Teil unseres Projekts ist damit erledigt. Jetzt müssen wir nur noch einen Weg finden, diese hier zurück zu Area 52 zu bringen und auch das Interesse der Expedition des Cenarius zu wecken. Es sollte hier genug geben, um unsere eigenen Interessen zu decken und noch ein wenig Gewinn zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10436] = { id = 10436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freie Bahn!", description = "Bevor wir den Test beginnen können, müssen wir sicherstellen, dass das Gebiet frei von allem ist, was uns dabei stören könnte. In unserem Fall sind das diese zu groß geratenen Echsen.\n\n<Tashar zeigt auf die Sichelzahnraptoren.>\n\nEs ist nicht voraussehbar, was passiert, wenn einer von ihnen auf die Idee kommt, genüsslich in den Generator zu beißen, während er gerade auflädt. Ich habe in all den Jahren als Techniker schon viele merkwürdige Dinge gesehen, darunter auch ein paar Mutationen, die einst ganz normale Tiere waren.", sourceObjective = "Tashar bei der Biokuppel Fernfeld möchte, dass Ihr 12 Sichelzahnraptoren tötet.", progress = "Habt Ihr das Testgelände bereinigt?", completion = "Gut gemacht. Wie es aussieht, ist alles in Ordnung. Wir können anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10437] = { id = 10437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Zerstörung", description = "Auf der Manaschmiede Ultris befindet sich der Riss im Nether, durch den Dimensius, der Leerenfürst, gekommen ist. Dieser Riss bildet eine Verbindung zwischen Dimensius und der Leere und macht ihn unverwundbar. Wenn es uns gelingt, diese Energieleitung, mit der Dimensius sich aus dieser Existenzebene zurückziehen kann, zu verschließen, können wir sie und Dimensius vernichten.\n\nDazu müsst Ihr zunächst Fragmente von Dimensius von den Leerkreaturen, die für ihn die Drecksarbeit erledigen, sammeln.", sourceObjective = "Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr 8 Fragmente von Dimensius besorgt.", progress = "Habt Ihr genügend Fragmente gesammelt?", completion = "Ausgezeichnet. Mit diesen Fragmenten können wir die Bombe einstellen, die die Leerenergieversorgung auf der Manaschmiede Ultris zerstören kann. Dann wird Dimensius' Verbindung zur Leere unterbrochen und er kann sich nicht mehr verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10438] = { id = 10438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf netherischen Schwingen", description = "Hier ist es, {name}. Nehmt den Phasenstörer und steigt auf! Der Netherdrachen des Protektorats wird Euch nahe genug an Ultris heranfliegen, damit Ihr den Störer auf die Leerleitung werfen könnt.\n\nSendet so viele Störsignale wie möglich aus, um eine komplette Zerstörung zu gewährleisten!\n\nWenn Ihr bereit seid, sprecht mit dem Netherdrachen und er wird mit Euch in die Lüfte steigen.\n\nWenn Ihr das Ziel verfehlt, müsst Ihr mehr Bomben von mir besorgen, bevor Ihr weitermachen könnt.", sourceObjective = "Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr den Phasenstörer bei der Leerenleitung auf der Manaschmiede Ultris benutzt. Sendet so viele Störsignale wie möglich aus, um eine komplette Zerstörung zu gewährleisten. Die Entladungen des Phasenstörers werden automatisch das Ziel treffen, solange Ihr nahe genug seid, um ihn zu benutzen.\n\nKehrt zu Professor Dabiri zurück, wenn Ihr erfolgreich wart!", progress = "Habt Ihr das Ziel getroffen?", completion = "Es ist Zeit zuzuschlagen! Nun, da der Riss fort ist, kann Dimensius mit Kraft und Magie angegriffen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[10439] = { id = 10439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dimensius der alles Verschlingende", description = "Eure mutigen Taten haben Ameer zum handeln bewegt! Er hat Hauptmann Saeed und die Rächer Aufstellung nehmen lassen!\n\nJetzt müssen wir nur noch Dimensius vernichten.\n\nWenn Ihr bereit seid, lasse ich Saeed rufen. Wenn er nicht gerade einen anderen Auftrag ausführt, wartet er östlich von hier auf Eure Befehle.\n\nLasst ihn wissen, wenn Ihr bereit seid zu kämpfen, damit er seine Truppen in Bewegung setzen kann.\n\nViel Glück, Fleischling! Wir jagen Dimensius schon seit tausend Jahren!", sourceObjective = "Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr mit Hauptmann Saeed sprecht, seiner Armee zur Manaschmiede Ultris folgt und Dimensius den alles Verschlingenden tötet!", progress = "Was gibt es Neues vom Fürst der Leere?", completion = "Seit tausend Jahren kennen wir nur noch Krieg. Wir haben unser Volk gegen die Angriffe der Leerwesen und der Astralen verteidigt.\n\nJetzt ist einer unserer schlimmsten Feinde gefallen - endlich.\n\nIch überbringe Euch den Dank von Milliarden von Astralen, Fleischling.", sourceObjectiveStatus = "unverified-source-field" }
quests[10440] = { id = 10440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfolg!", description = "Der Test war ein großer Erfolg! Wir können das Gerät benutzen, um die Kuppeln zu reparieren.\n\nBerichtet in der Sturmsäule von den Testergebnissen und lasst Ghabar wissen, dass ich ein Muster in den Schäden an den Schildgeneratoren entdeckt habe. Wichtige Teile der Generatoreinheiten sind an verschiedenen Orten verschwunden. Das ist kein Zufall, {name}, kein technischer Fehler. Wir werden bestohlen.", sourceObjective = "Kehrt zur Sturmsäule zurück und sprecht mit Ghabar im Nethersturm.", completion = "Ich setzte meine Techniker sofort auf die Reparaturen an.\n\nTashars Vermutung, dass es sich um Sabotage handelt, macht mir jedoch Sorgen. Ich kann mir nicht vorstellen, dass jemand waghalsig genug wäre, unsere Technologie zu stehlen. Zumindest niemand, der weiß, wozu wir fähig sind. Vielleicht ist es an der Zeit, die Sturmsäule abzuriegeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[10441] = { id = 10441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waren unters Volk bringen.", description = "<Audi senkt die Stimme wieder.>\n\nJetzt, da wir die Waren haben, werde ich die meisten davon nach Area 52 schicken. Wir haben hier mehr, als wir für einen Generator brauchen, was uns eine perfekte Geschäftsmöglichkeit eröffnet.\n\nIch habe gesehen, dass die Vertreterin der Expedition des Cenarius verhandeln will. Ich möchte, dass Ihr sie wissen lasst, dass wir ihr das, was sie sucht, zu einem günstigen Preis geben können. Es gibt kein Grund für sie, sich weiter mit diesen betrügerischen Astralen herumzuschlagen.", sourceObjective = "Sprecht mit Aurine Mondflamm unten in der Sturmsäule im Nethersturm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10442] = { id = 10442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Posten des Cenarius helfen", description = "{class}, es gibt hier eine Tauren namens Thiah Rotmähne, die uns ständig um Hilfe anfleht. Sie gehört zur Expedition des Cenarius, die einen kleinen Posten im Westen, auf der südlichen Seite der Straße in Richtung Zangarmarschen, errichtet hat.\n\nWenn Ihr beim Dornnebelhügel angekommen seid, seid Ihr zu weit gegangen.\n\nKönntet Ihr vielleicht dort hingehen und nachschauen, was sie braucht? Ich möchte Waldläuferhauptmann Venn'ren nicht mit solchen Kleinigkeiten belästigen.", sourceObjective = "Falknerin Drenna Flusswind möchte, dass Ihr Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel Eure Dienste anbietet.", completion = "Oh, gut, Ihr müsst die Hilfe sein, die ich vor Wochen von der Falkenwacht angefordert habe.\n\nNun, jetzt seid Ihr hier und es gibt viel zu tun. Ich habe genau das Richtige für Euch für den Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[10443] = { id = 10443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Posten des Cenarius helfen", description = "Der Zirkel des Cenarius hat eine Expedition in die Scherbenwelt geschickt. So weit ich verstanden haben, sind sie hier, um zu untersuchen, was passiert ist, und wenn möglich die Schäden rückgängig zu machen.\n\nSie haben einen kleinen Posten im Westen, auf der südlichen Seite der Straße in Richtung Zangarmarschen, errichtet.\n\nWenn Ihr den Dornnebelhügel erreicht, seid Ihr zu weit gegangen.\n\nKönnt Ihr vielleicht dort hingehen und schauen, wie Ihr ihnen helfen könnt? Sprecht mit Thiah Rotmähne. Sie hat uns um Hilfe gebeten.", sourceObjective = "Amaan der Weise möchte, dass Ihr Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel Eure Dienste anbietet.", completion = "Oh, gut, Ihr müsst die Hilfe sein, die ich vor Wochen vom Tempel von Telhamat angefordert habe.\n\nIch bin froh, dass Ihr hier seid; es gibt viel zu tun. Ich habe genau das Richtige für Euch für den Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[10444] = { id = 10444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Allerias Posten", description = "Das erfordert sofortiges Handeln!\n\nWir haben jemanden da draußen, der sich noch näher am Posten der Feuerschwingen befindet. Ich möchte, dass Ihr mit ihm sprecht. Er weiß sicher besser, was wir als Nächstes tun sollten.\n\nMeldet Euch bei Leutnant Meridian bei Allerias Posten und setzt ihn von der Lage in Kenntnis. Ihr findet den Posten im Nordosten am südlichen Ufer des Flusses, direkt südlich vom Posten der Feuerschwingen.\n\nBeeilt Euch, {name}!", sourceObjective = "Jenai Sternwisper möchte, dass Ihr Euch bei Leutnant Meridian in Allerias Posten in den Wäldern von Terokkar meldet.", completion = "Bombenteile. Dann war mein Verdacht also berechtigt. Ich hätte mir gewünscht, dass ich falsch liege.\n\nOk, wir haben also eine grausame Aufgabe vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[10445] = { id = 10445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Phiolen der Ewigkeit", description = "Illidan entnahm sieben Phiolen aus dem Brunnen der Ewigkeit. Drei davon leerte er in den See auf dem Berg Hyjal, wodurch ein zweiter Brunnen der Ewigkeit entstand. Jahrelang glaubte man den Rest verloren.\n\nSeit der Öffnung des Dunklen Portals haben wir erfahren, dass er seinen Leutnants Kael'thas und Vashj je eine Phiole gegeben hat. Holt zurück, was von den Phiolen noch übrig ist. Wir brauchen sie als Fokus, um ein Tor zu den Geschehnissen, seien sie aktuell oder vergangen, am Berg Hyjal zu öffnen. Das Ergebnis der Schlacht um den Berg Hyjal muss erhalten bleiben.", sourceObjective = "Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole von Lady Vashj im Echsenkessel und die Überreste von Kaels Phiole von Kael'thas Sonnenwanderer in der Festung der Stürme besorgt.", progress = "Ich verlange Unmögliches von Euch, und doch erwarte ich, dass es Euch gelingt. Es hängt viel davon ab.", completion = "Sogar in diesem kleinen Rest des Wassers aus dem Brunnen der Ewigkeit schlummert unglaubliche Macht.\n\nIch kann ganz deutlich jeden Moment in der Zeit, der mit dem Berg Hyjal in Verbindung steht, sehen... die Erschaffung des zweiten Brunnens der Ewigkeit, Illidans Gefangennahme, die Verzauberung des Weltenbaums und... ja! Die Schlacht um den Berg Hyjal.\n\nWir müssen uns beeilen, die Linien der Zeit sind noch nicht in Sicherheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10446] = { id = 10446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der finale Code", description = "Sie bauen eine zweite Manabombe im Hof! Meine Agenten berichten, dass Sharth Voldoun, der Zuständige des Projekts im Posten der Feuerschwingen, den finalen Code der Bombe haben muss.\n\n{name}, Ihr müsst dorthin zurückkehren und den letzten Code von ihm besorgen. Er hält sich auf der Spitze der höchsten Säule auf.\n\nBringt den finalen Code zu der Manabombe, an der sie im mittleren Hof arbeiten, und gebt ihn ein.\n\nNur dann können wir sicher sein, dass Allerias Feste gerettet ist.", sourceObjective = "Leutnant Meridian möchte, dass Ihr den finalen Code eingebt, um die Manabombe auszulösen. Meldet euch dann bei Jenai Sternwisper in Allerias Feste in den Wäldern von Terokkar zurück.", completion = "IHR HABT ES GESCHAFFT! IHR HABT ALLERIAS FESTE GERETTET!!\n\nJetzt, da ihre Streitkräfte dezimiert sind, ihr Anführer tot und die Manabombe zerstört ist, können wir alle etwas aufatmen.\n\nNie zuvor habe ich solche Selbstlosigkeit, solchen Heldenmut gesehen! Bitte, nehmt dies in unser aller Namen an!", sourceObjectiveStatus = "unverified-source-field" }
quests[10447] = { id = 10447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der finale Code", description = "Sie bauen eine zweite Manabombe im Hof! Meine Agenten berichten, dass Sharth Voldoun, der Zuständige des Projekts im Posten der Feuerschwingen, den finalen Code der Bombe haben muss.\n\n{name}, Ihr müsst dorthin zurückkehren und den letzten Code von ihm besorgen. Er hält sich auf der Spitze der höchsten Säule auf.\n\nBringt den finalen Code zu der Manabombe, an der sie im mittleren Hof arbeiten, und gebt ihn ein.\n\nNur dann können wir sicher sein, dass die Steinbrecherfeste gerettet ist.", sourceObjective = "Unteroffizier Chawni möchte, dass Ihr den finalen Code eingebt, um die Manabombe auszulösen. Meldet euch dann bei Tooki in der Steinbrecherfeste in den Wäldern von Terokkar zurück.", completion = "IHR HABT ES GESCHAFFT! IHR HABT DIE STEINBRECHERFESTE GERETTET!!\n\nJetzt, da ihre Streitkräfte dezimiert sind, ihr Anführer tot und die Manabombe zerstört ist, können wir alle etwas aufatmen.\n\nNie zuvor habe ich solche Selbstlosigkeit, solchen Heldenmut gesehen! Bitte, nehmt dies in unser aller Namen an!", sourceObjectiveStatus = "unverified-source-field" }
quests[10448] = { id = 10448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung beim Steinbrecherlager", description = "Das erfordert sofortiges Handeln!\n\nWir haben jemanden da draußen, der sich noch näher am Posten der Feuerschwingen befindet. Ich möchte, dass Ihr mit ihr sprecht. Sie weiß sicher besser, was wir als Nächstes tun sollten.\n\nMeldet Euch bei Unteroffizier Chawni im Steinbrecherlager und setzt sie von der Lage in Kenntnis.\n\nNehmt die Straße nach Norden aus der Feste heraus. Ab der Mitte von Tuurem müsst Ihr der Straße nach Osten folgen. Ihr findet das Lager am Ufer des Flusses, der direkt südwestlich des Postens der Feuerschwingen liegt.\n\nBeeilt Euch, {name}!", sourceObjective = "Tooki möchte, dass Ihr Euch bei Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar meldet.", completion = "Bombenteile. Dann war mein Verdacht also berechtigt. Ich hätte mir gewünscht, dass ich falsch liege.\n\nOk, wir haben also eine grausame Aufgabe vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[10449] = { id = 10449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apothekerin Zelana", description = "Apothekerin Zelana hat Untersuchungen bezüglich der Kreaturen auf der Höllenfeuerhalbinsel angestellt und ist sehr an einer Probe des Blutes interessiert, das Ihr für mich gesammelt habt. Mit ein wenig Glück wird sie herausfinden können, was die Haut dieser durchgedrehten Knochenmalmer rot werden ließ!\n\nZelana befindet sich im Häschersturz, südöstlich von Thrallmar. Folgt der Straße nach Osten. Wenn Ihr einen kaputten, grünlich leuchtenden Haufen Metall seht, seid Ihr angekommen. Sie hat ihr Lager hinter den Wyvern aufgeschlagen.", sourceObjective = "Vurtok Axtbrecher in Thrallmar möchte, dass Ihr die Blutprobe eines Knochenmalmers zu Apothekerin Zelana im Häschersturz bringt.", progress = "Es ist mir eine Ehre, der Horde dienen zu können. Wie kann ich Euch helfen?", completion = "Ah ja. Das Blut des Knochenmalmerklans. Ich interessiere mich sehr für diese Orcs... sie sind zwar immer noch die verkommenen Feinde unserer Vergangenheit, aber ihre Stärke und Macht ist größer, als ich gedacht habe...\n\nNun, wollen wir beginnen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[10450] = { id = 10450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut der Knochenmalmer", description = "Knochenmalmer! Sie sollen alle sterben! Der Anblick ihrer roten Haut und ihrer Verkommenheit bringt mein Blut zum kochen!\n\nIch habe einen Auftrag für Euch, {name}. Tötet die Orcs der Knochenmalmer und sammelt ihr bösartiges Blut. Es gibt eine Apothekerin, die vielleicht herausfinden kann, wie diese Orcs der Verderbnis der Dämonen anheim fallen konnten, eine Verderbnis, derer wir uns vor so kurzer Zeit erst entledigen konnten.\n\nDie Knochenmalmer streunen in der Nähe der zerstörten Kriegsmaschinerien entlang des Pfads der Ehre im Süden herum. Kehrt zu mir zurück, wenn Euer Auftrag erfüllt ist.", sourceObjective = "Bringt 12 Phiolen mit Knochenmalmerblut zu Vurtok Axtbrecher in Thrallmar.", progress = "Habt Ihr Euch den Knochenmalmern gestellt, {name}? Ich hoffe, dass Ihr ihr Blut in rauen Mengen vergossen habt.", completion = "Hah! Ihr habt also die Knochenmalmer, unsere verkommenen Vettern getroffen. Gut gemacht, {name}. Ich bedauere nur, dass nicht mehr von ihnen ihr Leben lassen und ihr Blut vergießen konnten, um meinen Zorn zu besänftigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10451] = { id = 10451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus der Zisterne der Echsennarbe", description = "Der Erdenmutter sei Dank! Ich habe mich vor ein paar Tagen von den anderen getrennt. Ich wollte der Quelle der Veränderung des Wassers, die wir spüren, auf den Grund gehen. Meine Suche führte mich zur Echsennarbe, wo ich herausgefunden habe, dass die Naga die Wasservorräte des Schattenmondtals verderben!\n\nUnglücklichweise hat man mich entdeckt und gefangen genommen. Nicht auszudenken, welch grausame Dinge sie mit mir vorhatten!\n\nWir müssen hier weg. Helft mir zu fliehen und sucht dann Torlok beim Altar der Verdammnis auf.", sourceObjective = "Begleitet Erdheilerin Wilda aus der Zisterne der Echsennarbe hinaus und sucht dann Erdheiler Torlok beim Altar der Verdammnis am westlichen Rang der Hand von Gul'dan auf.", completion = "Gelobt sei die Erdenmutter! Ich bin mir sicher, dass Wilda nach Hause finden wird. Bitte nehmt dies als Zeichen unserer Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[10455] = { id = 10455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nahende Wildnis", description = "Wir haben den Lebenden Hain sehr schnell zum Wachsen gebracht, aber nun haben wir die Kontrolle über die Luchse verloren.\n\nEinst war ihre Population gleichmäßig, aber nun kommen die Hainpirscherluchse immer näher an Sylvanaar heran. In letzter Zeit gab es schon einige unerfreuliche Zwischenfälle.\n\nIch nehme an, dass die Arakkoa vom Lashhversteck dahinter stecken, aber zunächst sind die Luchse selbst unser Problem.\n\nIch wäre Euch sehr dankbar, wenn Ihr uns dabei helfen würdet, mit dieser Lage fertigzuwerden.", sourceObjective = "Erlegt 12 Hainpirscherluchse.", completion = "Das ging schnell. Seid Ihr sicher, dass Ihr so viele getötet habt, wie es nötig war?\n\nGut, dann könnt Ihr uns bei einer weiteren Angelegenheit helfen, wenn Ihr möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10456] = { id = 10456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marodierende Wölfe", description = "Die abscheulichen Völker der Horde haben eine alte Siedlung im Osten eingenommen. Sie haben ein großes Rudel von Terrorwölfen mitgebracht, die sie gerne als Reittiere und Wachhunde einsetzen.\n\nDiese \"Wachhunde\" haben jedoch begonnen, hinter der Brücke, die uns voneinander trennt, Schaden anzurichten. Sie belästigen unsere Feendrachen, die für die Bestäubung unseres Waldes unersetzlich sind.\n\nNehmt den östlichen Ausgang, um die Brücke über der Blutschlägerklamm, die zum Zackengrat im Osten führt, zu überqueren, und bringt mir ihre Schwänze!", sourceObjective = "Beschafft Euch 4 Schwänze eines Terrorwolfs der Donnerfürsten.", progress = "Ich kann nicht deutlich genug sagen, dass diese Terrorwölfe der Donnerfürsten erledigt werden müssen. Ihre bloße Anwesenheit stört das Gleichgewicht des lebenden Hains und all unsere Arbeit hier.", completion = "Gut. Ich werde schauen, ob ich aus diesen Schwänzen etwas Nützliches machen kann.\n\nDie Horde wird ohne Zweifel einen Weg finden, Ihr Wolfsrudel wieder zu vergrößern, aber nun können wir etwas freier durchatmen.\n\n{name}, wenn Ihr dazu bereit seid, habe ich eine letzte Bitte an Euch, um Sylvanaar und den lebenden Hain zu verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10457] = { id = 10457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eigenen schützen", description = "Trotz der guten Arbeit, die Ihr geleistet habt, bin ich immer noch der Meinung, dass der Lebende Hain mehr Schutz braucht.\n\nBitte, nehmt diesen kleinen Zweig. Ich habe ihn mit der Macht der Natur verstärkt. Wenn er bei den Setzlingen, die ich im Hain gepflanzt habe, eingesetzt wird, ruft er einen Sturm herbei, der sie schnell zu großen Treantverteidigern heranwachsen lässt.\n\nDiese Treants sind für die Verteidigung des Waldes unverzichtbar, besonders, wenn man nicht für immer in Sylvanaar leben möchte.", sourceObjective = "Benutzt Rinas Zweig bei 5 Hainsetzlingen, um Verteidigung für den Lebenden Hain herbeizurufen.", progress = "Wie geht es mit der Verstärkung der Verteidigung des lebenden Hains voran?\n\nSolange wir nicht wissen, was die Arakkoa im Lashhversteck vorhaben und die Horde sich auf der anderen Seite der Klamm befindet, habe ich Angst, dass wir unser neues Heim und unsere Arbeit nicht mehr verteidigen können, wenn wir nicht bald handeln.", completion = "Nun, da Ihr die Verteidigung des Hains verstärkt habt, fühle ich mich viel sicherer.\n\nIhr habt Euch mehr als nur unseren Dank und unsere Wertschätzung verdient.\n\nMir fällt gerade ein, dass es da noch etwas gibt, bei dem ich Eure Hilfe brauchen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[10458] = { id = 10458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Geister des Feuers und der Erde", description = "Wir müssen versuchen, die Dinge zu ändern. Wir müssen mit den Elementen dieser Gegend kommunizieren und schauen, ob wir etwas tun können!\n\nIch gebe Euch das Totem der Geister, {race}. Wenn Ihr einen wütenden Elementargeist in der Nähe des Totems umbringt, wird es die Seele des Elementars aufnehmen. Ihr müsst viele Seelen mithilfe des Totems einfangen, bevor Ihr zu mir zurückkehrt.\n\nSammelt zuerst die Seelen der Geister des Feuers und der Geister der Erde. Kehrt zu mir zurück, wenn das Totem voll ist.", sourceObjective = "Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 8 Erdenseelen und 8 Feuerseelen einzufangen.", progress = "Ich fürchte, dass es keine Hoffnung für dieses Land gibt.", completion = "Wenn alle Elementarseelen dieser Gegend in diesem Totem eingefangen sind, werden wir mit ihnen reden und herausfinden, ob wir etwas für das Schattenmondtal tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10459] = { id = 10459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von der Expedition des Cenarius verehrt", description = "Eure Erfolge sind uns aufgefallen, {name}. Was Ihr für uns getan habt geht weit über das, was wir von Verbündeten erwarten, hinaus.\n\nIch habe eine besondere Bitte an Euch, aber zunächst muss ich Eure Hingabe testen.", sourceObjective = "Ysiel Windsänger bei der Zuflucht des Cenarius möchte, dass Euch einen respektvollen Ruf bei der Expedition des Cenarius verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[10460] = { id = 10460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versprechen des Verteidigers", sourceObjective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, {name}? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDieser Ring wurde mit einem Tropfen aus dem Brunnen der Ewigkeit verstärkt. Wenn Ihr Euch den Wächtern der Sande gegenüber beweist, wird er an Macht gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10461] = { id = 10461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versprechen des Bewahrers", sourceObjective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, {name}? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDieser Ring wurde mit einem Tropfen aus dem Brunnen der Ewigkeit verstärkt. Wenn Ihr Euch den Wächtern der Sande gegenüber beweist, wird er an Macht gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
