quests[10463] = { id = 10463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versprechen des Weisen", sourceObjective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, {name}? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDieser Ring wurde mit einem Tropfen aus dem Brunnen der Ewigkeit verstärkt. Wenn Ihr Euch den Wächtern der Sande gegenüber beweist, wird er an Macht gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10464] = { id = 10464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gelöbnis des Weisen", description = "Ihr habt Euer Versprechen gegeben, {class}. Jetzt liegt es an Euch, es einzuhalten.\n\nDient den Wächtern der Sande wohl, und Ihr werdet Euren Lohn erhalten.\n\nWenn Ihr scheitert, wird die Zeitlinie, wie wir sie kennen, zerrissen werden!", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen wohlwollenden Ruf bei den Wächtern der Sande erlangt habt.", progress = "Ihr leistet uns weiterhin gute Dienste, {name}.", completion = "Ihr habt Euch als würdig erwiesen, {race}. Zumindest bis zu einem gewissen Punkt.\n\nDie Gunst der Hauptgefährtin Nozdormus ist nicht so leicht zu erlangen.", sourceObjectiveStatus = "unverified-source-field" }
