quests[10467] = { id = 10467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gelöbnis des Verteidigers", description = "Ihr habt Euer Versprechen gegeben, {class}. Jetzt liegt es an Euch, es einzuhalten.\n\nDient den Wächtern der Sande wohl, und Ihr werdet Euren Lohn erhalten.\n\nWenn Ihr scheitert, wird die Zeitlinie, wie wir sie kennen, zerrissen werden!", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen wohlwollenden Ruf bei den Wächtern der Sande erlangt habt.", progress = "Ihr leistet uns weiterhin gute Dienste, {name}.", completion = "Ihr habt Euch als würdig erwiesen, {race}. Zumindest bis zu einem gewissen Punkt.\n\nDie Gunst der Hauptgefährtin Nozdormus erlangt man nicht so schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[10468] = { id = 10468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur des Weisen", description = "Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, {name}. Und dafür steht Euch die gebührende Anerkennung zu.\n\nWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Ihr seid zurück. Möchtet Ihr mit mir sprechen?", completion = "Ihr seid in der Tat ein würdiger Verbündeter. Und je mächtiger Ihr werdet, desto mächtiger wird auch das Band der Ewigkeit!", sourceObjectiveStatus = "unverified-source-field" }
