quests[10470] = { id = 10470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur des Helden", description = "Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, {name}. Und dafür steht Euch die gebührende Anerkennung zu.\n\nWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Ihr seid zurück. Möchtet Ihr mit mir sprechen?", completion = "Ihr seid in der Tat ein würdiger Verbündeter. Und je mächtiger Ihr werdet, desto mächtiger wird auch das Band der Ewigkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[10471] = { id = 10471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur des Verteidigers", description = "Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, {name}. Und dafür steht Euch die gebührende Anerkennung zu.\n\nWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Ihr seid zurück. Möchtet Ihr mit mir sprechen?", completion = "Ihr seid in der Tat ein würdiger Verbündeter. Und je mächtiger Ihr werdet, desto mächtiger wird auch das Band der Ewigkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[10472] = { id = 10472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bündnis des Weisen", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, {name}.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Möge die Zeit immer mit Euch sein, {name}.", completion = "Ihr gehört zur Zeit, {name}. Ihr gehört zu uns.\n\nSchaut! Sogar aus diesem kleinen Rest aus den Brunnen der Ewigkeit strömt noch Macht, die kein sterbliches Wesen begreifen kann.\n\nNehmt dieses Geschenk an, auf dass alle von Eurem Bündnis mit den Wächtern der Zeit erfahren... auf dass alle von Eurem Bündnis mit der Zeit selbst erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10473] = { id = 10473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bündnis des Bewahrers", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, {name}.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Möge die Zeit immer mit Euch sein, {name}.", completion = "Ihr gehört zur Zeit, {name}. Ihr gehört zu uns.\n\nSchaut! Sogar aus diesem kleinen Rest aus den Brunnen der Ewigkeit strömt noch Macht, die kein sterbliches Wesen begreifen kann.\n\nNehmt dieses Geschenk an, auf dass alle von Eurem Bündnis mit den Wächtern der Zeit erfahren... auf dass alle von Eurem Bündnis mit der Zeit selbst erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10474] = { id = 10474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bündnis des Helden", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, {name}.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Möge die Zeit immer mit Euch sein, {name}.", completion = "Ihr gehört zur Zeit, {name}. Ihr gehört zu uns.\n\nSchaut! Sogar aus diesem kleinen Rest aus den Brunnen der Ewigkeit strömt noch Macht, die kein sterbliches Wesen begreifen kann.\n\nNehmt dieses Geschenk an, auf dass alle von Eurem Bündnis mit den Wächtern der Zeit erfahren... auf dass alle von Eurem Bündnis mit der Zeit selbst erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10475] = { id = 10475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bündnis des Verteidigers", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, {name}.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10476] = { id = 10476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmige Feinde", description = "Wenn Ihr Eure Treue uns gegenüber beweisen wollt, dann gibt es keinen besseren Weg, als unsere Feinde zu bekämpfen.\n\nUnter diesen Feinden gibt es keinen, der so stark und so wild ist, wie die Oger. Bringt mir die Kriegsperlen, die sie um den Hals tragen, als Beweis für ihr Ableben. Wenn Ihr das tut, lasse ich die anderen von Eurem Heldenmut wissen.", sourceObjective = "Aufseher Moi'bff Jill in Telaar möchte, dass Ihr 10 Obsidiankriegsperlen von den verschiedenen Ogern in Nagrand besorgt.", progress = "Nun, {name}? Könnt Ihr nur Reden schwingen, oder habt Ihr mir etwas vorzuweisen?", completion = "Ihr beweist Euch allmählich als wertvoller Verbündeter und Kämpfer. Macht weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[10477] = { id = 10477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Kriegsperlen", progress = "Habt Ihr noch mehr Obsidiankriegsperlen dabei, {name}?", completion = "Ihr beweist Euch weiterhin als wertvoll, {name}. Möge Eure Stärke nie versagen." }
quests[10478] = { id = 10478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Kriegsperlen!", progress = "Habt Ihr noch mehr Obsidiankriegsperlen besorgt, {name}?", completion = "Ihr beweist uns auch weiterhin Eure Stärke und Ehre, {name}." }
quests[10479] = { id = 10479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke beweisen", description = "Auch wenn wir ein friedvolles Leben suchen, haben wir doch viele Feinde.\n\nUnter diesen Feinden gibt es keinen, der so viel rohe Macht besitzt, wie die Oger. Wenn Ihr uns Euren Heldenmut beweisen wollt, bringt mir die Kriegsperlen, die sie um den Hals tragen. Wenn Ihr das tut, lasse ich die anderen von Euren Taten wissen.", sourceObjective = "Aufseher Bullrok in Garadar möchte, dass Ihr 10 Obsidiankriegsperlen von den verschiedenen Ogern in Nagrand besorgt.", progress = "Habt Ihr etwas, das Ihr mir zeigen möchtet, {name}?", completion = "Ihr seid wirklich ein starker Verbündeter, {name}. Den Ogern der Scherbenwelt Auge in Auge gegenüberzutreten ist nichts, was jeder einfach so tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10480] = { id = 10480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Geister des Wassers", description = "Die Naga der Illidari in dieser Gegend haben die Kontrolle über die einzige reine Wasserversorgung im Schattenmondtal an sich gerissen.\n\nDirekt nördlich von hier findet Ihr das Nest der Naga, die Echsennarbe. Um die Echsennarbe herum findet Ihr Ansammlungen von tosendem Wasser, die ihre Qual ins Land hinausschreien. Bei diesen Ansammlungen streifen die wütenden Geister des Wassers umher.\n\nReist zur Echsennarbe und benutzt das Totem der Geister, um ihre Wasserseelen einzufangen. Die größte Ansammlung dieser Geister findet Ihr in der Nähe der Zisterne der Echsennarbe.", sourceObjective = "Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 5 Wasserseelen einzufangen.", progress = "Wo auch immer Ihr die Naga findet, könnt Ihr sicher auch die gequälten Wassergeister finden.", completion = "Und zurück bleibt nichts als Luft, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10481] = { id = 10481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Geister der Luft", description = "Begebt Euch nach Südosten, Held. Wenn Ihr große blaue Kristalle aus dem Boden herausragen seht, habt Ihr Euer Ziel erreicht. Dort, auf den Netherschwingenfeldern, werdet Ihr die wütenden Geister der Luft finden. Sie streifen rings um die Felder auf den Klippen und um die Berge herum umher.\n\nZerstört ihre gequälten Körper und fangt ihre Seelen im Totem der Geister ein. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 10 Luftseelen einzufangen.", progress = "Bald werden wir mit den Geistern sprechen.", completion = "Erlaubt mir, dass ich Euch für diese wagemutige Tat belohne, Held.\n\nJetzt müssen wir uns an die Arbeit machen! Bitte tretet zurück, damit ich das Totem aufstellen und die Seelen freilassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10482] = { id = 10482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plünderer der Höllenorcs", description = "Plünderer, Orcs des Knochenmalmerklans, treiben sich bei den zerstörten Kriegsmaschinerien am Pfad des Ruhmes herum. Wir müssen davon ausgehen, dass diese Höllenorcs Teile der Maschinen für ihre Meister in der Höllenfeuerzitadelle sammeln. Wir müssen sie aufhalten!\n\nSucht im Norden nach den Knochenmalmern, {name}. Sucht sie und tötet sie! Aber seid vorsichtig. Auch wenn diese Orcs einem niederrangigeren Höllenklan angehören, sind sie doch genauso stark wie alle Orcs, die wir bisher getroffen haben.", sourceObjective = "Tötet 20 Orcs der Knochenmalmer und kehrt danach zu Amadi in der Ehrenfeste zurück.", completion = "Sehr gut. Ich bin mir sicher, dass ihr Verlust in der Höllenfeuerzitadelle bemerkt wird. Auch wenn diese dunkle Bastion uns überschattet und unüberwindlich scheint, können wir mit stolzen Taten wie Eurer sicher einen Weg finden, sie zu besiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10483] = { id = 10483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarze Magie", description = "{name}, in unseren Schlachten mit den Höllenorcs des Blutenden Auges haben wir Schmuckstücke mit magischen Kräften bei ihnen gefunden. Diese Orcs haben die Insignien der gefallenen Soldaten der Ehrenfeste gesammelt und verfluchte Talismane aus ihnen gemacht. Wir befürchten, dass die schwarze Magie des Blutenden Auges unsere Insignien in böse Amulette verwandelt haben, die sie gegen uns einsetzen können!\n\nSucht einen solchen Talisman bei den Orcs des Blutenden Auges in Zeth'Gor im Osten. Bringt ihn zu Korporal Eisengrat beim Expeditionsposten nordöstlich von Zeth'Gor.", sourceObjective = "Leutnant Amadi in der Ehrenfeste möchte, dass Ihr einen verfluchten Talisman zu Korporal Eisengrat im Expeditionsposten bringt.", progress = "Bringt Ihr Neues von der Ehrenfeste, {name}? Das ist gut. Unseren Vorgehen gegen die Dämonen und Höllenorcs gehen so langsam die fähigen Kämpfer aus!", completion = "Ah, Ihr habt ein Insigne von den Orcs des Blutenden Auges ergattert? Gut! Es ist eine Schande, dass sie unsere Symbole gegen uns verwenden und sich über unsere Kameraden, die im Kampf gegen diese rothäutigen Bestien gefallen sind, lustig machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10484] = { id = 10484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchte Talismane", description = "{name}, wir können nicht zulassen, dass die Orcs des Blutenden Auges diese verfluchten Talismane besitzen! Ihr müsst sie für uns beschaffen, damit wir sie zerstören können und so die gefallenen Soldaten, denen sie gehörten, für ihr Opfer ehren.\n\nGeht nach Zeth'Gor, der verfluchten Behausung des Blutenden Auges, und führt Eure grausame Aufgabe durch... Kehrt zu mir zurück, wenn Ihr die Talismane gesammelt habt.", sourceObjective = "Bringt 12 verfluchte Talismane zu Korporal Eisengrat am Expeditionsposten.", progress = "Habt Ihr die Talismane, {name}? Es schmerzt mich zu wissen, dass diese verdammten Orcs die Insignien unserer Soldaten besitzen...", completion = "Danke, {name}. Mein Herz ist voller Trauer, wenn ich diese Talismane betrachte. Sie unterstreichen die zahlreichen Verluste, die wir in der Ehrenfeste gegen die Höllenorcs hinnehmen mussten. Aber es freut mich zu sehen, dass Ihr Erfolg gegen sie hattet. Wenn wir genügend von ihnen töten können, treten wir vielleicht als Sieger aus diesem Krieg hervor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10485] = { id = 10485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr des Blutenden Auges", description = "Ihr habt große Stärke und großes Geschick bewiesen, denn Ihr habt Euch in den Kampf in Zeth'Gor gestürzt und überlebt! Nun wollen wir hoffen, dass das Glück Euch weiterhin hold ist, denn ich muss Euch eine düstere Aufgabe auftragen...\n\nIn der Kaserne von Zeth'Gor sitzt Kriegsherr Morkh und befehligt seine Truppen gegen uns. Seine Taktiken sind genauso schlau wie grausam und ich muss zugeben, dass seine Erfolge bei uns tiefe Wunden geschlagen haben. Deshalb möchte ich Euch bitten, Morkh aus dem Weg zu räumen. Bringt mir seine Rüstung, damit wir sie meinen Soldaten zeigen und ihnen Mut machen können!", sourceObjective = "Bringt Kriegsherr Morkhs zerschmetterte Rüstung zu Korporal Eisengrat im Expeditionsposten.", progress = "Habt Ihr Morkhs zerschmetterte Rüstung? Habt Ihr Euch wieder todesmutig nach Zeth'Gor begeben?", completion = "Ihr habt es geschafft! Morkh ist tot! Jetzt haben wir eine Chance im Kampf gegen die Bestien der Höllenorcs!\n\nVielen Dank, {name}. Eure Hilfe in diesem Krieg ist unermesslich.", sourceObjectiveStatus = "unverified-source-field" }
quests[10486] = { id = 10486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nahende Wildnis", description = "Die Donnerfürsten waren einst ein stolzer Orcklan. Doch dann wurden sie durch Mannoroths Blut in Höllenorcs verwandelt.\n\nVor Kurzem haben wir diesen Orcstützpunkt von den Ogern, die sich in der Klamm unter uns breitgemacht haben, zurückgefordert. Nachdem die Donnerfürsten verschwunden waren, hatten sie hier Einzug gehalten.\n\nWir möchten diesen Ort behalten und Euch gerne bitten, uns dabei zu helfen.\n\nIm Zackengrat im Süden und Westen findet Ihr Blutvergießer, die sich zu einer wahren Seuche entwickeln. Sie fressen und vermehren sich unaufhörlich.\n\nTötet sie und kehrt dann zu mir zurück.", sourceObjective = "Tötet 12 Messerschwingenblutvergießer.", completion = "Das ging schnell. Seid Ihr sicher, dass Ihr so viele getötet habt, wie nötig war?\n\nGut. Es gibt noch eine weitere Aufgabe, bei der wir Eure Hilfe benötigen. Eine weitaus wichtigere.", sourceObjectiveStatus = "unverified-source-field" }
quests[10487] = { id = 10487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenstaub", description = "Vor kurzem hat die Allianz im Westen Einzug gehalten und mit Hilfe ihrer Elfenmagie ein Dorf und einen Hain praktisch aus dem Nichts entstehen lassen. Wir müssen ihre Verteidigung so schwach wie möglich halten, damit sie nicht auch noch ein Rückgrat entwickeln!\n\nIch habe einen Plan, mit dem wir dies und noch mehr erreichen können. Ich möchte, dass Ihr die Brücke nach Südwesten, die über die Blutschlägerklamm in den lebenden Hain führt, überquert.\n\nGreift ihre Siechdrachenverteidigung im lebenden Hain an und bringt mir etwas von dem magischen Staub, der sich manchmal auf ihren Flügeln befindet.", sourceObjective = "Beschafft Euch 4 Einheiten Feendrachenstaub.", progress = "Es sieht aus, als hätte die Allianz vor, uns überallhin zu folgen. Wir wollen ihnen beweisen, dass ihre Anwesenheit uns keineswegs einschüchtert.\n\nHabt Ihr besorgt, worum ich Euch gebeten habe?", completion = "Ihr habt nicht nur ihre Verteidigung geschwächt. Mit dem Staub werden wir dazu noch unsere eigene Verteidigung gegen die Allianz stärken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10488] = { id = 10488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eigenen schützen", description = "Ich habe aus dem magischen Staub, den Ihr gesammelt habt, eine Salbe hergestellt, die uns bei unserer Verteidigung helfen wird.\n\nAls wir hierher kamen, haben wir ein wundervolles Rudel Terrorwölfe mitgebracht. Sie sind die perfekte Kombination aus Reittier, Wachhund und Freund, aber der Abschaum der Allianz hat begonnen, sie im Zackengrat zu jagen.\n\n{name}, ich möchte, dass Ihr diese Salbe nehmt und sie an unseren Terrorwolffreunden anwendet. Das wird der Allianz eine böse Überraschung bescheren, wenn sie das nächste Mal auf die Jagd geht.\n\nSeid Euch jedoch bewusst, dass einige der Wölfe das vielleicht nicht leiden mögen und Euch angreifen werden.", sourceObjective = "Wendet Gor'dreks Salbe an 5 Terrorwölfen der Donnerfürsten an.", progress = "Wie geht es mit der Verstärkung unserer Terrorwolfverteidigung voran?", completion = "Nun, da Ihr die Wölfe und unsere Verteidigung gestärkt habt, können wir uns wieder einigen tödlicheren Angelegenheiten, wie zum Beispiel den Ogern, zuwenden.\n\nIhr habt uns hier gut geholfen. Wenn Ihr Euch entscheidet zu bleiben, könnten wir auch weiterhin die Dienste von jemandem, der so fähig ist wie Ihr, brauchen.\n\nWie auch immer Ihr Euch entscheiden mögt, Ihr habt meinen Respekt und meine Wertschätzung sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[10489] = { id = 10489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen uralten Baum fällen", description = "GESUCHT!\n\nStarkast Tiefenwurz, Urtum des Krieges und Hauptverteidiger des Lebenden Hains südlich von Sylvanaar.\n\nIhr findet ihn, indem Ihr nach Westen geht und die Brücke über der Blutschlägerklamm überquert.\n\nBringt seinen abgeschlagenen Stumpf zu Tor'chunk Zweiklaue.", sourceObjective = "Besorgt Starkast Tiefenwurz' Stumpf.", progress = "Was habt Ihr da? Ihr seid aber stark!", completion = "Starkast Tiefwurz' Stumpf! Habt Ihr ihn selbst gefällt?\n\nSicher habt Ihr das. Wisst Ihr, ein starker {class} wie Ihr es seid, ist genau die Hilfe, nach der Rexxar und ich gesucht haben. Besonders bei den ständigen Problemen, die wir mit den Ogern haben, könnten wir Euch brauchen. Setzt Euch mit mir in Verbindung, wenn Ihr Interesse habt.\n\nNun, dieser Stumpf ist ein stichhaltiger Beweis. Ihr seid hier, um das Kopfgeld einzustreichen, nicht um mit mir zu plaudern. Wohlan, sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10490] = { id = 10490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Scharfseher Nobundo hat nach Euch gefragt.\n\nIhr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.\n\nIch nehme an, Ihr wisst noch, wie Ihr mit dem Boot von Auberdine an der Dunkelküste in Kalimdor aus zurück zur Exodar kommt? Und Ihr wisst noch, dass Ihr ihn in der Kristallhalle in der Exodar findet, ja?", sourceObjective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", completion = "So treffen wir uns wieder. Ich habe Eure Fortschritte aus der Ferne beobachtet, Schamane, ich bin sehr zufrieden.\n\nEs ist jetzt an der Zeit, dass Ihr mit dem Element des Wassers vertraut werdet. Ihr sollt die Geheimnisse des Wassers erlernen und Euch diesem Wissen widmen, um es mit der Zeit auch beherrschen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10491] = { id = 10491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "{name}, Scharfseher Nobundo hat erneut nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!\n\nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.\n\nNehmt das Boot von Auberdine an der Dunkelküste in Kalimdor aus. Überquert das Verhüllte Meer und sucht den Weissager in der Kristallhalle der Exodar auf der Azurmythosinsel auf.", sourceObjective = "Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", completion = "Schließlich kommen wir zu dem letzten der vier großen Elemente, der Luft. Glaubt Ihr weise genug zu sein, um fortzufahren, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[10492] = { id = 10492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterquell heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Bindungen der Elemente zu Deliana in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[10493] = { id = 10493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Ich grüße Euch, {class}. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.", sourceObjective = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Lichts zu Mokvar in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10494] = { id = 10494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die angemessene Entlohnung", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir den Gürtel und die Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.", sourceObjective = "Bringt Deliana in Eisenschmiede eine Kordel der Elemente und ein Paar Stulpen der Elemente.", sourceObjectiveStatus = "unverified-source-field" }
quests[10495] = { id = 10495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die angemessene Entlohnung", description = "Ihr habt große Verlässlichkeit bewiesen, {name}. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", sourceObjective = "Bringt Mokvar in Orgrimmar einen Gürtel des Lichts und ein Paar Stulpen des Lichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[10496] = { id = 10496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel der Elemente, einem Kilt der Elemente und einem Paar Schulterstücke der Elemente zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10497] = { id = 10497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel des Lichts, ein Paar Beinplatten des Lichts und einer Schiftung des Lichts zu Mokvar in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10498] = { id = 10498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, {name}! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", sourceObjective = "Gebt Deliana Eure Helmkappe der Elemente und Eure Weste der Elemente.", sourceObjectiveStatus = "unverified-source-field" }
quests[10499] = { id = 10499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, {name}! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", sourceObjective = "Gebt Mokvar Euren Helm des Lichts und Eure Brustplatte des Lichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[10500] = { id = 10500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Euch!", description = "Hallo, schön dass Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, {name}! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, {class}? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", sourceObjective = "Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10501] = { id = 10501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Euch!", description = "Hallo, schön dass Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Allianz braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Allianz braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, {name}! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Feldmarschall Schneefall. Können wir auf Euch zählen, {class}? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", sourceObjective = "Sprecht mit Feldmarschall Schneefall im Militärviertel von Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[10502] = { id = 10502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oger der Blutschläger", description = "Es gibt eine Bedrohung für Sylvanaar, die weitaus tödlicher ist, als die Horde in der Donnerfeste.\n\nIch spreche von den einheimischen Ogern in diesen Bergen. Im Süden und Osten, unten in der Klamm, lebt der Stamm der Blutschläger. Sie sind zwar nicht der einzige Stamm, der uns bedroht, aber sie sind am nächsten.\n\nIch möchte, dass Ihr nach Süden durch den Lebenden Hain hindurch geht und dann den Pfad nach Osten nehmt, der zu ihrem Außenposten führt. Tötet so viele Oger der Blutschläger im Außenposten der Blutschläger, wie Ihr nur könnt.", sourceObjective = "Tötet 30 Oger der Blutschläger im Außenposten der Blutschläger.", completion = "Das ist ein guter Anfang, um Sylvanaar und den Hain zu schützen.\n\nJetzt, da die Oger nicht mehr ganz so zahlreich sind, überlegen die Blutschläger es sich sicher zweimal, bevor sie uns hier angreifen.\n\nWenn das doch nur der einzige Ogerstamm wäre, mit dem wir Probleme hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10503] = { id = 10503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Speerspießerbedrohung", description = "Es gibt eine Bedrohung für die Donnerfeste, die weitaus tödlicher ist, als die Allianz in Sylvanaar.\n\nIch spreche von den einheimischen Ogern in diesen Bergen. Im Westen, unten in der Klamm, lebt der Stamm der Speerspießer. Sie sind zwar nicht der einzige Stamm, der uns bedroht, aber sie sind am nächsten und die, die wir besiegen mussten, um diesen Ort hier beziehen zu können.\n\nIch möchte, dass Ihr nach Norden durch den Zackengrat hindurch geht und dann den Pfad nach unten nehmt, der in ihre Festung führt. Tötet so viele Oger der Speerspießer und ihre Raptoren in der Wehr der Speerspießer und im Grund der Speerspießer, wie Ihr nur könnt.", sourceObjective = "Tötet 30 Oger der Speerspießer und 10 Raptoren der Speerspießer in der Wehr der Speerspießer und im Grund der Speerspießer.", completion = "Das ist ein guter Anfang, um unsere Position hier gegen die Oger zu verteidigen.\n\nJetzt, da die Oger nicht mehr ganz so zahlreich sind, überlegen die Speerspießer es sich sicher zweimal, bevor sie versuchen, die Donnerfeste zurück zu erobern.\n\nWenn das doch nur der einzige Ogerstamm wäre, mit dem wir Probleme hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10504] = { id = 10504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oger der Speerspießer", description = "Nördlich des Blutschlägerstamms liegt eine noch gefährlichere Bedrohung: die Wehr der Speerspießer.\n\nDie Oger der Speerspießer sind die stärksten in den Bergen und stehen in der Gunst des Gronn namens Gruul der Drachenschlächter und seiner sieben Söhne.\n\nJetzt, da Ihr den Blutschlägern eine Abreibung verpasst habt, ist es an der Zeit, sich ihren Rivalen zuzuwenden.\n\nGeht vom Außenposten der Blutschläger aus nach Norden durch die Klamm, bis Ihr die Wehr der Speerspießer und den Grund der Speerspießer erreicht. Tötet so viele Oger der Speerspießer, wie Ihr nur könnt.", sourceObjective = "Tötet 30 Oger der Speerspießer in der Wehr der Speerspießer und dem Grund der Speerspießer.", completion = "Eure Taten gegen die Blutschläger und Speerspießer sind ein großer Schritt nach vorne für die Sicherung der Zukunft Sylvanaars. Als wir hier ankamen, fanden wir diesen Flecken Land unbewohnt. Wir haben kein Interesse daran, uns noch weiter auszubreiten, aber wir werden auch nicht dulden, dass man uns vertreibt.\n\nDa Ihr uns gute Dienste geleistet habt, möchte ich Euch mit der Wertschätzung der Allianz belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10505] = { id = 10505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oger der Blutschläger", description = "Südlich des Speerspießerstamms liegt noch eine weitere Bedrohung: der Außenposten der Blutschläger.\n\nDie Oger der Blutschläger sind nicht die stärksten in den Bergen. Da sie nicht in der Gunst des Gronn namens Gruul der Drachenschlächter stehen, kommen sie nur an zweiter Stelle.\n\nJetzt, da Ihr den Speerspießern eine Abreibung verpasst habt, ist es an der Zeit, sich ihren Rivalen zuzuwenden.\n\nGeht von der Wehr der Speerspießer aus nach Süden durch die Klamm, bis Ihr den Außenposten der Blutschläger erreicht. Tötet so viele Oger der Blutschläger, wie Ihr nur könnt.", sourceObjective = "Tötet 30 Oger der Blutschläger im Außenposten der Blutschläger.", completion = "Eure Taten gegen die Blutschläger und Speerspießer sind ein großer Schritt nach vorne für die Sicherung der Zukunft der Donnerfeste. Wir werden nicht dulden, dass sich jemand unserem Schicksal in den Weg stellt.\n\nDa Ihr uns gute Dienste geleistet habt, möchte ich Euch mit der Wertschätzung der Horde belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10506] = { id = 10506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine düstere Lage", description = "Jetzt, da ihr Wolfsrudel dezimiert wurde, ist die Horde auf der Suche nach Ersatz. Unglücklicherweise können sie den gleich in der Nähe finden.\n\nDie Oger der Blutschläger in der Klamm im Osten unter uns halten sich selbst ein Rudel als Wachhunde. Ich war nicht sehr froh darüber, Euch loszuschicken, um die Wölfe der Donnerfürsten zu töten. Lasst uns dieses Mal etwas anderes versuchen.\n\nIch habe ein magisches Pulver aus dem Staub, der von den Flügeln unserer Feendrachen fällt, hergestellt. Streut es auf die Terrorwölfe der Blutschläger, damit sie für die Horde nicht länger interessant sind.", sourceObjective = "Streut Rinas Schwächungspulver auf 5 Terrorwölfe der Blutschläger im Außenposten der Blutschläger in der Blutschlägerklamm.", progress = "Hattet Ihr Glück da draußen? Ich weiß, dass es wegen der Oger der Blutschläger sehr gefährlich ist, aber wenn wir es vermeiden können, die Tiere zu töten, bin ich sehr froh.", completion = "Ich bin froh zu hören, dass es geklappt hat. Je weniger Wesen der Natur sterben müssen, desto besser.\n\nIch muss sagen, dass ich Euch nach all dem, was Ihr für uns getan habt, ins Herz geschlossen habe.\n\nGebt auf Euch Acht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10507] = { id = 10507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wendepunkt", description = "Das ist die Gelegenheit, auf die wir gewartet haben, {name}. Wir können vor unserem Volk nicht nur belegen, was Kael'thas wirklich vorhat, sondern auch unsere Stärke beweisen, indem wir seine neuen Meister besiegen.\n\nMeine schlechte Gesundheit hindert mich leider daran, Euch selbst zu helfen, aber ich biete Euch einen Gegenstand an, mit dem ich meine Kräfte über den Kontinent hinweg ausüben kann.", sourceObjective = "Benutzt Socrethars Teleportationsstein beim Invasionspunkt: Oberanführer im Norden der Konstruktionsbasis: Vergessenheit, um Eure Gruppe zu Socrethars Sitz zu bringen. Wenn Ihr dort seid, benutzt Voren'thals Präsenz, um Socrethar zu besiegen.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Ist es vollbracht, {name}?", completion = "Ihr verfügt über unglaubliche Kraft, {name}. Die Seher können sich glücklich schätzen, Euch als Verbündeten zu haben.\n\nWenn sich die Nachricht von Kaels neuem Bündnis verbreitet, werden mehr Leute die Sache wie wir sehen. Die Tatsache, dass wir einen solch entscheidenden Sieg über Kael'thas errungen haben, bringt uns in eine äußerst günstige Lage.\n\nIch werde Eure Taten nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10508] = { id = 10508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Voren'thal", description = "Ich möchte Euch nicht mit leeren Händen zu Voren'thal zurückschicken. Jemanden unbeeindruckt zu lassen ist nicht mein Stil.\n\nUm Zugang zu Socrethars Sitz im Norden zu erlangen, müsst Ihr einen seiner Teleporter benutzen. Dazu braucht Ihr einen Teleportationsstein. Die erste Hälfte des Steins befindet sich im Besitz von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit. Die zweite Hälfte hat der Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna.\n\nBesorgt Euch den Stein, dann wird Voren'thal über alle Maßen beeindruckt sein.", sourceObjective = "Spionagemeister Thalodien in Area 52 möchte, dass Ihr die erste Hälfte von Socrethars Stein von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit und die zweite Hälfte des Steins von Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna besorgt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr Socrethars Teleportationsstein schon besorgt, {name}?", completion = "Ihr erstaunt mich immer wieder, {name}! Gut, dass Ihr auf unserer Seite steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10509] = { id = 10509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Ruhm bestimmt", description = "Jetzt kann ich Euch ruhigen Gewissens nach Shattrath zurückschicken. Ihr habt Beweise dafür gefunden, dass Kael'thas sich mit der Brennenden Legion verbündet hat. Außerdem habt Ihr den Schlüssel zur Hintertür des Oberanführers erlangt.\n\nGebt jedoch Acht, dass sich Voren'thal nicht vor lauter Aufregung überschlägt - der alte Mann wird langsam etwas gebrechlich, wenn Ihr versteht, was ich meine. Ihr findet ihn in der Bibliothek der Seher auf der Sehertreppe.", sourceObjective = "Bringt Socrethars Teleportationsstein zu Voren'thal dem Seher auf der Sehertreppe in Shattrath.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ihr habt keine Ahnung, was das für die Seher bedeutet, {name}. Ihr müsst mich entschuldigen, während ich nach Atem ringe und die Situation einschätze.", sourceObjectiveStatus = "unverified-source-field" }
quests[10510] = { id = 10510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Draenethystmine", description = "Schön jemanden zu sehen, der uns hier helfen will!\n\nBorgrim und ich gehören zur Forscherliga. Wir sind hier, um so viel von diesen Bergen zu lernen, wie wir nur können. Wir haben schon allerlei Geschichten darüber gehört. Ich kann es kaum abwarten, mich hier niederzulassen und mit der Arbeit zu beginnen.\n\nEine Sache hat meine besondere Aufmerksamkeit erregt. Die Nachtelfen erzählen von einem Ort in der Klamm im Osten, der als Draenethystmine bekannt ist. Sie liegt am südlichen Ende des Außenpostens der Blutschläger. Ich hätte gerne ein paar der Kristalle, die dort wachsen.", sourceObjective = "Sammelt 5 Kristalle der Draenethystmine.", progress = "Ist das nicht aufregend? Nach dem ganzen Dreck und den Insekten in Silithus ist dieser Ort hier ein wahres Paradies!", completion = "Ooh, so wie sie aussehen, handelt es sich hierbei um ganz tolle Exemplare! Ich kann es kaum abwarten, sie mit meinen Untersuchungsgeräten genau unter die Lupe zu nehmen!\n\nVielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[10511] = { id = 10511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merkwürdiges Gebräu", description = "Wenn ich diesen Urlaub richtig beginnen will, brauche ich mehr gutes Gebräu. Leider haben diese Elfen keine Ahnung von der hohen Kunst des Gärens.\n\nIch habe gehört, dass die Oger der Blutschläger in der Klamm ganze Mengen davon auf Lager haben. Das will ich gerne versuchen.\n\nTut Ihr mir einen Gefallen? Geht nach Süden durch den Lebenden Hain und dann den Abstieg im Osten hinunter zum Außenposten der Blutschläger und besorgt mir ein wenig davon. Ich habe gehört, dass sie große Fässer davon herumliegen haben. Ihre Braumeister schenken es an all die anderen Oger aus.", sourceObjective = "Sammelt 11 Einheiten von Blutschlägers Hauweggebräu.", progress = "Ziemlich trocken hier. Wie soll ich denn meinen Urlaub ohne etwas zu Trinken genießen?", completion = "Was riecht hier so? Oh nein, bitte sagt mir nicht, dass dies das Ogergebräu ist?\n\nIch habe fast schon Angst, es zu probieren. Ach zur Hölle, was soll's? Hoch die Tassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10512] = { id = 10512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Speerspießer abfüllen", description = "Ich nehme keinen weiteren Schluck von diesem übel riechenden Gesöff! Aber mir kommt da eine Idee.\n\n<Borgrims Augen beginnen zu funkeln.>\n\nDas ist der Plan. Wir wissen, dass die Blutschläger praktisch von dieser Brühe leben. Aber ich frage mich, was wohl ihre Feinde, die Speerspießer, davon halten.\n\n{name}, ich möchte, dass Ihr den Rest dieses Gesöffs nehmt und schaut, ob wir die Oger der Speerspießer damit betrunken machen können. Ihr findet sie nördlich vom Außenposten der Blutschläger in der Klamm.", sourceObjective = "Versucht, mit Blutschlägers Hauweggebräu 5 Oger der Speerspießer betrunken zu machen.", progress = "Wie sieht es aus? Sind die Speerspießer so anspruchslos wie die Blutschläger oder sind sie auch fast dabei umgekommen wie ich?", completion = "Ah, hahaha! Das habe ich mir gedacht. Oger trinken wahrscheinlich alles.\n\nWas für ein dummer Haufen!\n\nAuch wenn ich mein Gebräu nicht bekommen habe, habt Ihr mir doch einen guten Start in den Urlaub bereitet.\n\nIch sage Euch was... wir haben hier allen möglichen Kram, den wir nicht wirklich brauchen. Kann ich Euch etwas davon anbieten?", sourceObjectiveStatus = "unverified-source-field" }
quests[10513] = { id = 10513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oronok Herzeleid", description = "Ich weiß nicht, wie wir an den Zauberspruch, den die Geister erwähnt haben, herankommen sollen, {name}. Um die Wahrheit zu sagen, habe ich nicht einmal eine Ahnung, wo man so eine Suche beginnen könnte.\n\n<Torlok starrt gedankenverloren in die Ferne.>\n\nHmm... Das ist zwar ein Schuss ins Blaue, aber es ist vielleicht unsere einzige Chance. Es gibt einen Orc, den ich schon des Öfteren in dieser Gegend gesehen habe. Ich habe einmal kurz mit ihm gesprochen. Er ist ein Einsiedler, der angeblich in der Zisterne der Echsennarbe im Nordosten lebt. Findet diesen Orc namens Oronok Herzeleid.\n\nWie gesagt, es ist ein Schuss ins Blaue.", sourceObjective = "Sucht Oronok Herzeleid auf dem zerschlagenen Vorsprung nördlich der Zisterne der Echsennarbe.", completion = "Litanei der Verdammnis? Nie davon gehört. Hört auf meinen Rat und lasst die Toten ruhen.\n\nAber wenn Ihr schon hier seid, könnt Ihr mir ja gleich bei ein paar Dingen helfen. Was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[10514] = { id = 10514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich war schon vieles...", description = "Ich war schon vieles, Fremder, aber was ich einst war, ist nicht von Belang. Es zählt nur, was ich jetzt bin, und jetzt bin ich ein Bauer.\n\nIch benutze trainierte Hölleneber, um Knollen in der harten Erde der Zerschlagenen Weiten aufzuspüren. In letzter Zeit greifen jedoch Felshetzer aus einem Gelege im Nordosten meine Tiere an und halten mich vom Sammeln der Knollen ab.\n\nWürdet Ihr für mich in der Gegend nördlich von hier ein paar Knollen sammeln? Benutzt diese Pfeife, wenn Ihr auf einem Schattenmondknollenhügel steht. Einer der Eber wird herbeieilen, und die Knolle ausgraben.", sourceObjective = "Oronok Herzeleid bei Oronoks Hof im Schattenmondtal möchte, dass Ihr 10 Schattenmondknollen aus den Zerschlagenen Weiten besorgt.\n\nBringt Oronoks Eberpfeife zu ihm zurück, wenn Ihr fertig seid.", progress = "Holt mir diese Knollen!", completion = "Ihr sagt, da waren viel mehr Felshetzer, als Ihr erwartet habt? Sieht aus, als wäre es an der Zeit, die Situation etwas zu entschärfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10515] = { id = 10515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion gelernt", description = "Wir müssen diesen Felshetzern zeigen, was es heißt, Oronoks Geschäften in die Quere zu kommen!\n\nIch möchte, dass Ihr in die Zerschlagenen Weiten zurückkehrt und jedes Felshetzerei zerstört, das Ihr finden könnt. Sie befinden sich sicher tief im Felshetzergebiet. Seid also wachsam.", sourceObjective = "Oronok Herzeleid bei Oronoks Hof im Schattenmondtal möchte, dass Ihr 10 Eier eines gefräßigen Schinders in den zerschlagenen Weiten zerstört.", completion = "Das wird den verdammten, bösartigen Tieren zeigen, dass man meine Eber nicht töten sollte! Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10516] = { id = 10516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefangenschaft der Verteidigerin", description = "Ich weiß, es klingt merkwürdig, aber ich möchte wirklich in diesem Käfig bleiben. Er gibt mir die perfekte Gelegenheit, um das zu tun, weswegen ich hier bin: Informationen über die Oger der Speerspießer sammeln.\n\nIch kann hier zwar jederzeit raus, aber mein Schwert und meinen Schild hätte ich gerne wieder zurück.\n\nZwei ihrer Anführer haben sich meine Sachen unter den Nagel gerissen. Droggam hat mein Schwert und Mugdorg meinen Schild.\n\nWenn Ihr es für nötig haltet, besorgt Euch das Gebräu der Blutschläger aus ihrem Außenposten im Süden, um die Unterstützung der beiden außer Gefecht zu setzen, aber gebt auf ihre nüchternen Wachen Acht, die nichts trinken werden!", sourceObjective = "Holt Verteidigerin Vuuleens Klinge und Verteidigerin Vuuleens Schild zurück.", progress = "{class}, habt Ihr mein Schwert und meinen Schild?\n\nIch kann zwar jederzeit hier raus, aber es wäre mir sehr peinlich, wenn ich ohne meine Ausrüstung nach Sylvanaar zurückkehren müsste.", completion = "Ich stehe tief in Eurer Schuld, denn Ihr habt mir meine Ehre wiedergegeben. Aber unsere Arbeit hier ist noch nicht vorüber.", sourceObjectiveStatus = "unverified-source-field" }
quests[10517] = { id = 10517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Zeit ist gekommen, Gorr'Dim...", description = "Der Anführer der Wehr der Speerspießer ist Gorr'Dim.\n\nEr ist auf keinen Fall zu unterschätzen. Seine Gerissenheit hat die Speerspießer zu den Lieblingen von Gruul dem Drachenschlächter und dem vorherrschenden Klan in den Bergen gemacht. Gorr'Dim hat auf Schritt und Tritt seine private Eskorte dabei, darunter auch Verteidiger, die schwören mussten, niemals auch nur einen Tropfen des Gebräus der Blutschläger anzurühren.\n\nFür die Sicherheit Sylvanaars und all der friedliebenden Wesen der Berge bitte ich Euch, zur Wehr zurückzukehren und ihn zur Strecke zu bringen.", sourceObjective = "Tötet Gorr'Dim, den Anführer der Oger in der Wehr der Speerspießer.", completion = "Sehr gut. Ihr seid ein sehr gewitzter {class}, so viel ist sicher.\n\nIch frage mich, ob Ihr wohl noch eine Sache für mich und Sylvanaar tun könntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10518] = { id = 10518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Banner aufstellen", description = "Ich möchte, dass Ihr das Banner der Speerspießer von einem ihrer Champions stehlt und es nach Süden zum Außenposten der Blutschläger bringt. Stellt es auf dem Nordschlägerturm auf.\n\nDas wird die Blutschläger erzürnen. Sie werden Euch ohne mit der Wimper zu zucken angreifen. Aber es wird auch ihren Hass auf die Speerspießer schüren und sie von Sylvanaar ablenken.\n\nIhr habt Eure Aufgabe erfüllt, wenn Ihr Gurn Grubnoshs Helm in den Händen haltet. Bringt ihn nach Sylvanaar.\n\n{name}, das wird nicht einfach. Nehmt ein oder zwei Freunde mit.", sourceObjective = "Benutzt das Banner der Speerspießer auf dem Nordschlägerturm, um Gurn Grubnosh anzulocken, und beschafft Euch das Banner der Speerspießer sowie Gurn Grubnoshs Helm.", progress = "Was führt Euch zu mir? Es gibt doch nicht etwa Ärger mit den Blutschlägern?", completion = "Gurn Grubnoshs Helm und ein Banner der Speerspießer?\n\nEin ziemlich gewitzter Plan von der Verteidigerin und Euch.\n\nWenn die Blutschläger weiter mit den Speerspießern beschäftigt sind, nimmt uns das viel von dem Druck, unter dem wir hier in letzter Zeit leiden.\n\nBitte, {name}, nehmt dieses bescheidene Geschenk von Sylvanaar an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10519] = { id = 10519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Litanei der Verdammnis - Wahrheit und Geschichte", description = "<Oronok nimmt Haltung an und richtet sich zu seiner vollen Größe auf.>\n\nIch musste sichergehen, {name}. Und dazu musste ich Euch erst prüfen. Bitte verzeiht meine kleine Maskerade. Ich bin so sehr ein Bauer, wie Ihr ein Teufelseber seid, nämlich gar nicht.\n\nWenn Ihr die Litanei der Verdammnis beschaffen wollt, müsst Ihr mir erst zuhören. Wenn Ihr bereit seid, lasst es mich wissen, und ich werde Euch die Geschichte erzählen.", sourceObjective = "Oronok Herzeleid bei Oronoks Hof im Schattenmondtal möchte, dass Ihr Euch seine Geschichte anhört. Sprecht mit Oronok, um ihm zusagen, dass er mit der Geschichte beginnen kann.", progress = "Habt Geduld und hört zu, {name}.", completion = "Versteht Ihr, was getan werden muss? Findet die Söhne Oronoks. Findet meine Jungs...", sourceObjectiveStatus = "unverified-source-field" }
quests[10520] = { id = 10520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Hirschhaupt helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Hirschhaupt an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", sourceObjective = "Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10521] = { id = 10521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grom'tor, Sohn von Oronok", description = "Mein Erstgeborener, Grom'tor, hat sich aufgemacht, um die Echsennarbe zu durchsuchen. Sie befindet sich direkt südwestlich von hier.\n\nEr ist der Krieger der Familie, jähzornig und blutdurstig... Das hat er von seiner Mutter. Sucht um die Echsennarbe herum nach ihm. Wenn Ihr irgendwo Nagaleichen liegen seht, ist Grom'tor sicher in der Nähe.\n\nWenn Ihr ihn findet, dann sagt ihm dies: \"Wir vergießen Blut für eine gerechte Sache\". Dann wird er wissen, dass Ihr ein Freund Herzeleids seid und Euch nicht vorschnell töten.", sourceObjective = "Sucht Grom'tor, Sohn von Oronok in der Echsennarbe im Schattenmondtal.", completion = "<Grom'tor grunzt.>\n\nGut dass Ihr hier seid. Diese Made hat gerade geplaudert. Jetzt haben wir sie!", sourceObjectiveStatus = "unverified-source-field" }
quests[10522] = { id = 10522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Litanei der Verdammnis - Grom'tors Angriff", description = "Dieser Nagaabschaum ist schon der sechste, den ich heute befragt habe. Wegen der schicken Rüstung dachte ich, dass er sicher etwas weiß. Die anderen waren völlig nutzlos.\n\n<Grom'tor zeigt auf die Nagaleichen um sich herum.>\n\nIch musste ihn nur einmal schlagen, da hat er mir schon alles erzählt.\n\nDer erste Teil der Litanei befindet sich in einer Nagatruhe in der Echsennarbe oder der Zisterne der Echsennarbe im Osten. Er sagt, dass die Naga die Schlüssel haben. Tötet sie, nehmt ihre Schlüssel und benutzt sie, um die Truhen der Echsennarbe zu öffnen. Kehrt zu mir zurück, wenn Ihr die Litanei gefunden habt.", sourceObjective = "Grom'tor, Sohn von Oronok, in der Echsennarbe im Schattenmondtal möchte, dass Ihr den ersten Teil der Litanei der Verdammnis besorgt.", progress = "Hattet Ihr Glück?", completion = "Das müsst Ihr sofort zurück zu Vater bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10523] = { id = 10523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Litanei der Verdammnis - Erster Teil", description = "<Grom'tor wickelt die Dokumente ein und legt sie in eine Schließkassette.>\n\nBringt diese Kassette zu meinem Vater. Er erwartet Eure Rückkehr bei seinem Hof im Nordosten.\n\nSagt ihm, dass ich bald nach Hause kommen werde. Sobald ich meinen Spaß hier hatte...", sourceObjective = "Bringt Grom'tors Schließkassette zu Oronok Herzeleid bei Oronoks Hof im Schattenmondtal.", progress = "Hattet Ihr Erfolg?", completion = "Wenn die Litanei der Verdammnis wieder zusammengefügt ist, werden wir diesen Fluch beenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[10524] = { id = 10524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefakte der Donnerfürsten", description = "Das Artefakt verfügt über Markierungen, die es als Kunstwerk der Orcs der Donnerfürsten identifizieren. Diese Orcs lebten einst in der Donnerfeste, bevor sie zu Höllenorcs wurden.\n\nEine Zeitlang wohnten die Oger der Speerspießer in der Feste, bis die Horde sie von dort vertrieben hat.\n\nIhr habt schon von weiteren Artefakten gehört, die vermisst werden. Ihr wisst, dass sich unter den Objekten, nach denen gesucht wird, eine Trommel, ein Pfeil und eine Schrifttafel befinden.\n\nDurchsucht die Wehr der Speerspießer nach ihnen und bringt sie zu Rokgah Blutgriff.", sourceObjective = "Beschafft Euch die Trommel der Donnerfürsten, den Pfeil der Donnerfürsten und die Schrifttafel der Donnerfürsten.", progress = "Kenne ich Euch?", completion = "Ich kann meinen Augen nicht trauen! Wenn das ein Scherz sein soll, ziehe ich Euch die Haut vom Leibe, {class}!\n\nSchnell, lasst mich diese unschätzbaren Artefakte untersuchen, bevor Ihr sie noch mit Euren zwei linken Händen zerbrecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10525] = { id = 10525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wegweisende Visionen", description = "<Dummer/Dumme:r> {race}. Ihr hättet fast die Trommel zerstört!\n\nIch habe so hart daran gearbeitet und bis jetzt stand ich immer mit leeren Händen da. Wenigstens hattet Ihr Erfolg, wo alle anderen versagt haben.\n\nJetzt, da wir diese vier Artefakte des Klans haben, ist es an der Zeit, eine Vision herbeizurufen, die Euch zu dem letzten Artefakt, nach dem ich suche, führen wird.\n\nNehmt dieses feurige Fragment meiner Seele. Damit könnt Ihr Euren Körper in eine Flamme verwandeln und Euren Geist in eine wegweisende Vision versetzen, die Euch den Aufenthaltsort des letzten Relikts der Donnerfürsten zeigen wird.", sourceObjective = "Benutzt das feurige Seelenfragment, um Euren Geist in eine wegweisende Vision zu versetzen, wodurch Ihr den Aufenthaltsort des letzten Artefakts der Donnerfürsten erfahren solltet.", progress = "Was habt Ihr gesehen? Sagt es mir! Ich muss wissen, wo es ist!", completion = "In der Draenethystmine? Die Blutschläger müssen es von dem Speerspießern gestohlen haben.\n\nPah! Das ist zu weit weg... zu tief im Blutschlägergebiet, als dass ich dorthin reisen könnte.\n\nAber Ihr! Ihr kennt den Weg. Ihr sollt an meiner statt dorthin gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10526] = { id = 10526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Donnerlanze", description = "Wenn die Vision, die ich Euch gewährt habe, wahr ist, dann müsst Ihr hinunter in das südliche Ende der Blutschlägerklamm reisen. Dort findet Ihr die Draenethystmine.\n\nReist bis ans Ende der Mine und beschafft die Donnerlanze. Beachtet nichts anderes! Ich interessiere mich nicht für die Kristalle in der Mine.\n\nSobald Ihr den Speer habt, bringt ihn zu mir zurück.\n\nUnd {name}, seid vorsichtig damit... Ich mag mir gar nicht ausmalen, was Euch zustoßen wird, wenn Ihr ihn zerbrecht.", sourceObjective = "Beschafft Euch die Donnerlanze.", progress = "Ihr könnt sicher nicht verstehen, wie wichtig diese Artefakte sind.\n\nWenn ich alle fünf beisammen habe, werde ich ein Ritual durchführen, das unser Besitzrecht an der Donnerfeste durch die Besänftigung der toten Geister festigen wird.\n\nVersteht Ihr nun, was daran so wichtig ist? Versteht Ihr nun, warum ich keine Zeit für Geplänkel habe?", completion = "Ich bin beeindruckt. Könnt Ihr Euch überhaupt vorstellen, wie viele zuvor bei dem Versuch, die Relikte zu bergen, gestorben sind?\n\nWir können uns glücklich schätzen, dass Ihr hier mit uns zusammenarbeitet, {name}. Auch wenn Ihr etwas langsam seid.\n\nErlaubt mir, Eure Aufopferung für unsere Sache zu belohnen. Wählt, aber wählt weise. Wenn Ihr fertig seid, werde ich die Geister der Donnerfeste besänftigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10527] = { id = 10527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ar'tor, Sohn von Oronok", description = "Mein jüngster Sohn, Ar'tor, hat sich bei der Stätte der Illidari auf die Suche begeben. Sie befindet sich weit im Südwesten, zwischen der Feste der Legion und der Burg Wildhammer.\n\nAuch wenn Ar'tor ein ausgezeichneter Jäger und Fährtenleser ist, befürchte ich, dass er sich dieses Mal übernommen hat. Die Stätte der Illidari ist eine Prüfungsstätte für Illidans Dämonen. Diese Dämonen haben die Brennende Legion verlassen, um sich dem Verräter anzuschließen!\n\nReist zur Stätte der Illidari und findet Ar'tor, {name}!", sourceObjective = "Findet Ar'tor, Sohn von Oronok, bei der Stätte der Illidari im Schattenmondtal.", completion = "Ar'tors Körper hängt leblos in der Luft. Ihr wisst nicht, wie lange er schon tot ist, aber Euch überkommt große Traurigkeit für Oronok.\n\nVielleicht solltet Ihr versuchen, seine Leiche zu seinem Vater zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10528] = { id = 10528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Kristallgefängnisse", description = "Eurer Einschätzung nach wird Ar'tors Körper von der Energie der Kristalle, die um die Rune herum schweben, in der Luft gehalten. Ihr versucht alles, was Ihr könnt, aber Ar'tor lässt sich nicht bewegen.\n\nEuch fällt auf, dass die Kristalle im unteren Teil eine Vertiefung aufweisen, vielleicht für einen Schlüssel. Neben den Kristallen scheinen Sukkuben regelmäßig eine Art Ritual durchzuführen.\n\nDurchsucht die Stätte der Illidari nach ihrer Anführerin. Vielleicht hat sie den Schlüssel zu Ar'tors Befreiung.", sourceObjective = "Sucht und tötet Schmerzensmeisterin Gabrissa in der Stätte der Illidari und kehrt mit dem kristallenen Schlüssel zum Leichnam von Ar'tor, Sohn von Oronok, zurück.", progress = "Ar'tor schwebt leblos vor Euch.", completion = "Ihr steckt den Schlüssel in die Öffnungen im unteren Teil jedes dämonischen Kristalls.", sourceObjectiveStatus = "unverified-source-field" }
quests[10529] = { id = 10529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Jägers", description = "Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer hat eine Audienz mit allen fähigen Jägern gefordert. Es wäre sicher von Vorteil für Euch, wenn Ihr Euch so schnell wie möglich bei Ihr meldet, {name}. Sie ist ein wahrer Quell der Weisheit für Euresgleichen.\n\nDie Zuflucht der Weltenwanderer liegt südlich von Silbermond.", sourceObjective = "Sprecht mit Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer im Immersangwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[10530] = { id = 10530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Jägers", description = "Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer hat eine Audienz mit allen fähigen Jägern gefordert. Es wäre sicher von Vorteil für Euch, wenn Ihr Euch so schnell wie möglich bei Ihr meldet, {name}. Sie ist ein wahrer Quell der Weisheit für Euresgleichen.\n\nDie Zuflucht der Weltenwanderer liegt südlich von Silbermond.", sourceObjective = "Sprecht mit Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer im Immersangwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[10531] = { id = 10531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um das Arathibecken!", description = "{name}, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpositionen anzugreifen.\n\nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!\n\nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpositionen gelungen ist.", sourceObjective = "Erobert die Mine, das Sägewerk, die Schmiede und den Hof und meldet Euch anschließend bei Feldmarschall Lichtmark in der Zuflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10532] = { id = 10532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschlagt die Versorgungslinien Arathors", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, {name}. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpunkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.", sourceObjective = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[10534] = { id = 10534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Ah, <ein/eine:c> {class}...\n\nJa, vor Kurzem war ein Priester Eures Ordens hier, {name}. Er hat mir gesagt, dass es an der Zeit für Euch ist, zur Exodar zurückzukehren und Caedmos zu treffen. Es klang, als wäre es ziemlich dringend. Lasst Euch also nicht allzu viel Zeit.", sourceObjective = "Caedmos in der Exodar wünscht Euch zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10535] = { id = 10535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ressourcen des Arathibeckens", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, {name}. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.", sourceObjective = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10537] = { id = 10537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lohn'goron, Bogen des Herzeleid", description = "Es ist ein Zeichen, {name}. Nicht einmal der Tod kann mich aufhalten. Einen Teil der Litanei der Verdammnis zu beschaffen ist mein Schicksal. Mit Eurer Hilfe werde ich es erfüllen.\n\nBevor wir uns auf diese Reise begeben, brauche ich meinen Langbogen, Lohn'goron. Er ist ein Familienerbstück, das seit Generationen von Herzeleid zu Herzeleid weitergegeben wurde.\n\nMeine Instinkte sagen mir, dass einer der Dämonen ihn von meiner Leiche gestohlen hat. Tötet die Dämonen hier, bis Ihr meinen Bogen habt.", sourceObjective = "Der Geist von Ar'tor bei der Stätte der Illidari im Schattenmondtal möchte, dass Ihr Lohn'goron, den Bogen des Herzeleid, von den Dämonen in der Gegend beschafft.", progress = "Fürchtet Euch nicht, Held. Wenn die Zeit gekommen ist, werde ich Euch helfen...", completion = "Der Name bedeutet in meiner Sprache 'Heldenruh'. Und auch jetzt, in einer Gegend, in der all unsere Helden gestorben sind, bewahrheitet er sich.\n\nUnd doch scheint einer sich immer wieder zu erheben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10538] = { id = 10538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochendes Blut", description = "Das letzte Experiment war kein kompletter Fehlschlag. Ich habe ein wenig von dem Blut, das Ihr mir gebracht habt, aufgehoben. Jetzt, da es abgekocht ist, sollte es frei von allen Flüchen sein, mit denen die Hexen des Blutenden Auges das Blut ihres Volkes belegt haben.\n\nIch brauche jedoch noch mehr Blut für meine Untersuchungen. Begebt Euch nach Zeth'Gor und sammelt dort das Blut der Orcs. Kocht es danach in ihrem verfluchten Kessel und bringt es mir.", sourceObjective = "Benutzt den Verfluchten Kessel, um das Blut des Blutenden Auges in gekochtes Blut zu verwandeln. Bringt danach 12 Einheiten gekochtes Blut zu Apotheker Albreck im Rückenbrecherposten.", progress = "Habt Ihr das gekochte Blut, {name}? Ich würde es furchtbar gerne ohne Unterbrechungen untersuchen können...", completion = "Sehr gut. Jetzt kann ich meine Tests viel leichter durchführen...\n\nVielen Dank, {name}. Eure Begabungen sind beachtlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[10539] = { id = 10539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Ah, <ein/eine:c> {class}...\n\nJa, vor Kurzem war ein Priester Eures Ordens hier, {name}. Er hat mir gesagt, dass es an der Zeit für Euch ist, zur Exodar zurückzukehren und Caedmos zu treffen. Es klang, als wäre es ziemlich dringend. Lasst Euch also nicht allzu viel Zeit.", sourceObjective = "Caedmos in der Exodar wünscht Euch zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10540] = { id = 10540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Litanei der Verdammnis - Ar'tors Angriff", description = "Endlich sind wir bereit. Ich werde Euch einen Teil meines Geistes verleihen, Held. Er wird Euch den Weg weisen und Euch im Kampf gegen das Böse unterstützen.\n\nDann müsst Ihr von hier aus nach Süden an die Rückseite der Stätte der Illidari reisen. Versteckt im Astralraum befindet sich eine bösartige Kreatur namens Veneratus der Vielgesichtige. Mein Geistjäger wird ihn hervorlocken, wenn er in der Nähe ist.\n\nVernichtet Veneratus und nehmt ihm den zweiten Teil der Litanei der Verdammnis ab.", sourceObjective = "Der Geist von Ar'tor bei der Stätte der Illidari im Schattenmondtal möchte, dass Ihr den zweiten Teil der Litanei der Verdammnis von Veneratus dem Vielgesichtigen besorgt.\n\nKreaturen, die vom Geistjäger angegriffen werden oder Schaden erleiden, gewähren Euch keine Beute oder Erfahrung.", progress = "Die Litanei muss gefunden werden!", completion = "<Ar'tors Silhouette wird unscharf und wieder schärfer.>\n\nEs scheint, als wäre meine Zeit bald zu Ende, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[10541] = { id = 10541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Litanei der Verdammnis - Zweiter Teil", description = "Ich danke Euch, Held. Ohne Euch wäre mein Geist auf ewig an diesem verfluchten Ort gefangen.\n\n<Ar'tor reicht Euch eine spektrale Schließkassette.>\n\nNehmt sie und bringt sie zu meinem Vater beim Hof im Nordosten, über der Zisterne der Echsennarbe... darin befinden sich Lohn'goron und der zweite Teil der Litanei.\n\nEr wird sehr traurig über meinen Tod sein. Versprecht mir, dass Ihr ihm versichert, dass ich als freie Seele gestorben bin. Sagt ihm, dass ich die Jagdgründe sehe und dass sie wundervoll sind. Sagt ihm, dass ich dort auf ihn warte...", sourceObjective = "Bringt Ar'tors Schließkassette zu Oronok Herzeleid bei Oronoks Hof im Schattenmondtal.", progress = "<Eine einzelne Träne läuft über Oronoks Wange.>", completion = "<Oronok wischt sich die Träne aus dem Auge und lächelt Euch an.>\n\nDanke. Ich verspreche Euch, Held, dass ein ehrenhaftes Lied über Euch erklingen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10542] = { id = 10542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ham meine Pfeife und mein Gesöff geklaut!", description = "T'chali war immer ein gediegener Troll. Ich kam hierher, um den Blutschlägern beizubringen, wie man Bier braut. Aber dann ham die Blutschläger mich hier begraben und lassen mich hier verrotten!\n\nDas Schlimmste ist, dass die meine Wasserpfeife geklaut ham!\n\nWollt Ihr T'chali also helfen? Bringt mir meine Wasserpfeife zurück! T'chali glaubt, dass die Oger, die sie gestohlen ham, nach Südwesten bei der Mine drüben abgehauen sind.\n\nUnd wenn Ihr schon da seid, nehmt noch etwas von meinem Gebräu mit!", sourceObjective = "Beschafft Euch T'chalis Wasserpfeife und 10 Einheiten von Blutschlägers Hauweggebräu zurück.", progress = "He, habt Ihr meine Wasserpfeife und das Gebräu schon?", completion = "Ja, genau davon hat T'chali geredet! Ist sich nicht ganz sicher, was die Oger da reingetan ham. Die Pfeife riecht nicht nach T'chalis Tabak.\n\nEgal, T'chali ist glücklich. Sogar so glücklich, dass er Euch um einen weiteren Gefallen bitten will.", sourceObjectiveStatus = "unverified-source-field" }
quests[10543] = { id = 10543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimnok und Korgaah, ich komm' Euch holen!", description = "T'chali hat auf seine Rache gewartet!\n\nAn dem Tag, an dem sie T'chali begraben und zum Sterben hier gelassen ham, hat Grimnok Schlachttaufe der Blutschläger sie angeführt. Und am nächsten Tag kam Korgaah nach Süden, um zu Plündern und T'chali gegen den Kopf zu treten.\n\nIch will die beiden tot sehen! Ihr findet Grimnok auf dem Südschlägerturm im Außenposten der Blutschläger. Korgaah befindet sich auf einem Gebäude am nördlichen Ende der Wehr der Speerspießer. Korgaah hat nüchterne Freunde bei sich. Ihr werdet also vielleicht das Gebräu brauchen, um ihn von ihnen wegzulocken.", sourceObjective = "Tötet Grimnok Schlachttaufe und Korgaah.", completion = "T'chali ist zufrieden, dass Korgaah und Grimnok Schlachttaufe jetzt auch die Radieschen von unten anschauen.\n\nAber T'chalis Rachedurst ist noch nicht gestillt. Ihr müsst noch etwas anders machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10544] = { id = 10544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflucht seien Eure beiden Klans!", description = "T'chali hat beschlossen, dass er Rache an allen Ogern will!\n\nT'chali war in seinem Leben ein mächtiger Hexendoktor. Wenn Ihr in mein Grab fasst, findet Ihr dort einen verdammt mächtigen Fetisch.\n\nNehmt den Fetisch und ruft seine Magie, um die Gebäude der Wehr der Speerspießer und des Außenpostens der Blutschläger zu verfluchen. Der Voodoo wird einen bösen Geist rufen, den Ihr vernichten müsst. Das wird wiederum das Haus verfluchen.\n\nAber Vorsicht! Wenn Ihr versucht, ein Haus zu verfluchen, das bereits verflucht ist, ruft Ihr damit einen weiteren bösen Geist!", sourceObjective = "Benutzt den heimtückischen mächtigen Fetisch, um 5 Gebäude in der Wehr der Speerspießer und 2 Gebäude im Außenposten der Blutschläger zu verfluchen.", progress = "T'chali will nicht mehr sprechen, bis {name} den Fetisch benutzt hat, um die Häuser der Speerspießer und der Blutschläger zu verfluchen!", completion = "Hahaha, Rache ist süss!\n\nAber T'chali sieht, dass Ihr nun, da meine Rache verübt wurde, gerne weiterziehen wollt. Ich versteh' schon, Kumpel... lassen wir das Leben den Lebenden.\n\nIch sag' Euch was, T'chali hat hier immer noch ein paar Sahnestückchen in seinem Grab. Sucht Euch aus, was Euch am besten gefällt!", sourceObjectiveStatus = "unverified-source-field" }
quests[10545] = { id = 10545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saufgelage der Speerspießer", description = "Wie T'chali schon gesagt hat, hat er seinen Freunden von den Blutschlägern dabei geholfen, Ihr Gebräu zu brauen. Aber T'chali hat ihnen nicht gesagt, warum.\n\nDie Blutschläger stecken ziemlich in der Klemme. Da die Speerspießer drohen, sie zu zermalmen, brauchten die Blutschläger eine neue Waffe, um sie im Kampf zu unterstützen.\n\nDa kam T'chali auf eine tolle Idee. Warum nicht das perfekte Getränk brauen, das einen selbst stärkt und die Feinde schwächt? Der Haken ist nur, dass T'chali nicht weiß, ob es geklappt hat.\n\nBringt dieses Gebräu also zur Wehr der Speerspießer und schaut, ob es funktioniert!", sourceObjective = "Macht mit Blutschlägers Hauweggebräu 5 Oger der Speerspießer betrunken.", progress = "Sagt es T'chali... hat das Gebräu funktioniert? Haben die Speerspießer es gemocht?", completion = "Das sind gute Nachrichten! Das Gebräu wird bei der nächsten Aufgabe, die T'chali für Euch hat, nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10546] = { id = 10546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borak, Sohn von Oronok", description = "Während Ar'tor auf der Jagd war und Grom'tor kämpfte, verbrachte Borak seine Zeit mit Lernen. Dann nahm er eine Stelle als Gelehrter an und ist nach Draenor aufgebrochen. Vor ein paar Jahren kam er als ganz neuer Orc zurück.\n\nSeine erhöhte Aufmerksamkeit und Geistesschärfe haben ihn zu einem schweigsamen Meuchelmörder gemacht.\n\nJetzt, da er ein Orc mit Selbstvertrauen und Macht ist, hat er sich aufgemacht, um das bestgehütete Teil der Litanei zu beschaffen.\n\nSucht Borak. Er versteckt sich in der Nähe der Stätte der Mondfinsternis, weit im Süden. Er liegt im Schatten der Brücke auf der Lauer.", sourceObjective = "Sucht Borak, Sohn von Oronok, in der Nähe der Stätte der Mondfinsternis im Schattenmondtal.", completion = "<Borak ist für einen Moment still.>\n\nIch beobachte diese Blutelfen schon seit Wochen und versuche herauszufinden, wo sie den dritten Teil der Litanei der Verdammnis aufbewahren.\n\nSo weit habe ich jedoch keine brauchbaren Hinweise sammeln könne. Ich weiß nur, dass Illidan einmal am Tag einen Entsandten vom Schwarzen Tempel herschickt.\n\nDieser Entsandte ist unantastbar. Ich habe ihn eine Woche lang überwacht und nach einem Weg gesucht, ihn von seiner Leibwache zu trennen. Die Leibwache verlässt jedoch unglücklicherweise nie seine Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[10547] = { id = 10547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Distelköpfen und Eiern...", description = "Wenn es mir nicht aufgefallen wäre, hätte ich aufgegeben. Er ist ein Distelabhängiger. Zuerst habe ich es nicht verstanden, aber die Zeichen sind alle da...\n\nWenn wir an ein paar Blutdisteln herankämen, wären wir im Geschäft.\n\nAuf meinen Reisen habe ich in Shattrath einen zwielichtigen Zerschlagenen namens Tobias getroffen.\n\nTobias verdient sein Geld damit, den Blutelfen im Austausch gegen verfaulte Arakkoaeier Blutdisteln zu geben.\n\nDirekt westlich von hier befinden sich Ruinen der Arakkoa. Durchsucht sie nach einem Ei und begebt Euch dann in das Untere Viertel von Shattrath. Dort findet Ihr Tobias.", sourceObjective = "Borak, Sohn von Oronok, bei der Brücke nördlich der Stätte der Mondfinsternis möchte, dass Ihr ein verfaultes Arakkoaei besorgt und es zu Tobias dem Faulfraß in Shattrath, nordwestlich der Wälder von Terokkar, bringt.", progress = "<Tobias hebt eine Augenbraue.>\n\nBlutdistel? Nie davon gehört... Seid Ihr ein Friedensbewahrer? Ihr wisst, dass Ihr mir sagen müsst, wenn Ihr einer seid... Ich habe schließlich Rechte!", completion = "Ihr habt ein verfaultes Arakkoaei? Nun, warum habt Ihr das denn nicht gleich gesagt? Ich denke, wir sind im Geschäft.\n\n<Tobias lächelt und entblößt dabei eine Reihe verfaulter und vergilbter Zähne.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10548] = { id = 10548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die traurige Wahrheit", description = "Erinnert Ihr Euch daran, dass ich von einem fetten Händler sprach, der auf der Suche nach diesem Ring war? Wie es aussieht, hat er seinen Sohn, der Archäologe ist, danach geschickt. Es scheint jedoch kein allzu gutes Ende genommen zu haben. Mit nicht allzu gut meine ich, dass sie ihn getötet und einen Schrumpfkopf aus ihm gemacht haben.\n\nDas klingt jetzt vielleicht eiskalt, berechnend und unheimlich gefühllos, aber er ist bereit, eine stolze Summe für den Kopf seines Sohns hinzublättern. Klingt nach der perfekten Aufgabe für Euch!\n\nGeht nach Osten, bis Ihr die Trollruinen von Zeb'Tela und Zeb'Nowa erreicht. Er müsste sich dort in einer der Truhen befinden.", sourceObjective = "Eralan in Tristessa möchte, dass Ihr den Schrumpfkopf des Archäologen aus einer der Truhen in Zeb'Tela oder Zeb'Nowa besorgt.", progress = "Wie geht die kopflose Suche voran?", completion = "Oh, wow. Das ist nicht gerade hübsch. Ich bin mir sicher, dass der Händler ihn mehr schätzen wird, als ich.\n\nAls Bezahlung hat der Händler angeboten, Euch eine meiner Spezialwaren zu kaufen. Also sucht Euch etwas aus, Süsse!", sourceObjectiveStatus = "unverified-source-field" }
quests[10550] = { id = 10550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bündel von Blutdisteln", description = "Ich habe nicht gelogen. Das Ei war unglaublich. Woher hattet Ihr es?\n\nNun, falls Ihr jemals mehr Blutdisteln brauchen solltet, wisst Ihr ja, wo Ihr mich findet und was ich benötige.\n\nDa habt Ihr ein Bündel von dem Zeug. Bringt es zurück zu Eurem Auftraggeber.", sourceObjective = "Bringt das Blutdistelbündel zurück zu Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal.", progress = "Habt Ihr die Blutdisteln?", completion = "Jetzt müssen wir die Falle stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10551] = { id = 10551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyalität gegenüber den Aldor", sourceObjective = "Seid Ihr Euch Eurer Wahl sicher, {name}? Die Aldor heißen Euch gerne als Verbündeten willkommen, aber die Seher werden Euch Eure Entscheidung nicht so leicht vergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10552] = { id = 10552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyalität gegenüber den Sehern", sourceObjective = "Seid Ihr Euch Eurer Wahl sicher, {name}? Die Seher heißen Euch gerne als Verbündeten willkommen, aber die Aldor werden Euch Eure Entscheidung nicht so leicht vergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10553] = { id = 10553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voren'thal der Seher", description = "Jetzt, da Ihr Euch für eine Seite entschieden habt, {name}, solltet Ihr den Anführer der Seher kennenlernen.\n\nIhr findet Voren'thal den Seher in der Bibliothek der Seher auf der Sehertreppe.\n\nSchaut nach, ob Ihr ihn unterstützen könnt. Er wird sich über Eure Entscheidung, den Sehern beizustehen, sehr freuen.", sourceObjective = "Sprecht mit Voren'thal dem Seher in der Bibliothek der Seher bei der Sehertreppe in Shattrath.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Khadgar hat einen neuen Rekruten geschickt? Dann wollen wir Euch mal beschäftigen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10554] = { id = 10554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishanah", description = "Jetzt, da Ihr Euch für eine Seite entschieden habt, {name}, solltet Ihr die Anführer der Aldor kennenlernen. Ihr findet Hohepriesterin Ishanah im Schrein des unendlichen Lichts.", sourceObjective = "Sprecht mit Ishanah im Schrein des unendlichen Lichts auf der Aldorhöhe in Shattrath.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Willkommen, {name}. Ich bin froh, dass Ihr Euch entschieden habt, unserer Sache beizustehen. Möge das Licht Euch stets beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10555] = { id = 10555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fauler Zauber", description = "Die Magie der Arakkoa der Lashh'an ist unnatürlich. Sie reißen sich ganze Hände voll - oder Klauen voll - ihrer eigenen Federn als Reagenz heraus!\n\nFür mich klingt das nicht gerade nach guter Magie. Ich bin hierhergekommen, um mehr über ihre Zauber zu erfahren, aber näher heranzugehen ist einfach eine Nummer zu groß für mich.\n\nIhr könntet es jedoch schaffen. Wirkt einen ihrer Zauber auf Euch selbst und kehrt dann zu mir zurück. Ihr müsst eines ihrer Zauberbücher finden, das sich hoch oben in den Bäumen des Lashhverstecks befindet.\n\nUnd falls Euch nicht irgendwo am Körper versteckte Federn wachsen, müsst Ihr ein paar davon sammeln.", sourceObjective = "Sammelt 18 ausgezupfte Federn der Lashh'an.", progress = "Die groben Piktogramme in dem uralten Folianten weisen darauf hin, dass eine große Menge von Federn der Lashh'an benötigt wird, um die Sprüche in dem Buch zu wirken.", completion = "Ihr blättert die Seiten voll gekritzelter Notizen in der dünnen Schrift der Arakkoa der Lashh'an durch und findet ein Piktogramm, das die Kreise der Macht, die Ihr im Lashhversteck gesehen habt, darstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10556] = { id = 10556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gekritzel", description = "Die Piktogramme deuten darauf hin, dass für das Wirken der Zauber in den Zirkeln der Macht im Lashhversteck Federn benutzt werden.\n\nVerwirrende Bilder scheinen einen Arakkoa zu zeigen, der vom Geist eines Kaliri eingehüllt wird.", sourceObjective = "Benutzt die Handvoll Federn im Zauberzirkel der Lashh'an.", progress = "Das ist so aufregend! Ich kann es kaum abwarten, die Wirkung des Zaubers zu untersuchen!", completion = "Ich weiß nicht, was ich sagen soll. Dieser Zauber ist sehr merkwürdig. Es handelt sich nicht um eine einfache Beschwörung oder Verzauberung, sondern eher um eine Art Vereinigungs- oder Kommunikationszauber.\n\nIch weiß nicht, was ich davon halten soll, {name}. Ich muss noch ein wenig darüber nachdenken.\n\nAber trotzdem vielen Dank für Eure Hilfe! Ich bin sicher, dass ich früher oder später dahinter komme.", sourceObjectiveStatus = "unverified-source-field" }
quests[10557] = { id = 10557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testflug: Das Zephyriumkapazitorium", description = "Ich habe ein sagenhaftes Gerät erfunden: das Zephyriumkapazitorium. Ich bin mir sicher, dass es einwandfrei funktionieren wird, aber... habt Ihr Lust, es für mich zu testen?\n\nEs gibt auch genügend Gefahrenzulage!\n\nSprecht mit Rally, meinem Zwilling da drüben. Viel Glück, {name}. Kommt nach dem Experiment zu mir zurück. Oder.. falls das wegen erlittener Verletzungen nicht möglich ist, schickt einen nahen Verwandten, um Eure Bezahlung abzuholen.", sourceObjective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium.", progress = "Keine Angst! Es ist für die Wissenschaft, und Wissenschaft ist Krieg!", completion = "Wow, Ihr habt es geschafft! Und kein einziger blauer Fleck oder offener Knochenbruch! Seht Ihr, ich habe Euch doch gesagt, dass alles funktionieren wird!\n\nHier ist Eure Bezahlung, {name}. Ich habe die Arztkosten gleich dazu gerechnet, aber da Ihr sie nicht gebraucht habt, seht es einfach als kleinen Bonus an!", sourceObjectiveStatus = "unverified-source-field" }
quests[10558] = { id = 10558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respektvoller Ruf in der Ehrenfeste", description = "Ihr habt Euch für unsere Sache als hilfreich erwiesen, {name}. Jemand wie Ihr hat das Zeug, ein großer Anführer zu werden.\n\nKämpft auch weiterhin gegen unsere Feinde in den Zerschmetterten Hallen und verdient Euch die Achtung meiner Männer. Wenn Ihr meine Erwartungen erfüllt, werde ich Euch großartigere Aufträge geben.", sourceObjective = "Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr Euch einen respektvollen Ruf in der Ehrenfeste verschafft, indem Ihr die Höllenorcs in den Zerschmetterten Hallen der Höllenfeuerzitadelle tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10559] = { id = 10559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respektvoller Ruf in Thrallmar", description = "Ihr habt Euch immer und immer wieder als würdig erwiesen, {class}. Und doch warten noch mehr Prüfungen auf Euch.\n\nKämpft weiter gegen die Höllenhorde in den Zerschmetterten Hallen der Höllenfeuerzitadelle. Dann wird Euer Name bald allen Freunden Thrallmars im ganzen Land bekannt sein!", sourceObjective = "Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel möchte, dass Ihr Euch einen respektvollen Ruf in Thrallmar verschafft, indem Ihr die Höllenorcs in den Zerschmetterten Hallen der Höllenfeuerzitadelle tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10560] = { id = 10560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respektvoller Ruf bei den Sha'tar", description = "<Die beruhigenden melodischen Töne, die von A'dal ausgehen, werden leiser und dunkler.>\n\n<Euch wird das große Naarugebäude, das als Festung der Stürme bekannt ist, gezeigt. Jetzt wird es von Kael'thas Streitmächten bewohnt und seine Macht wird zu bösartigen Zielen eingesetzt. A'dal verspricht Euch größere Aufgaben, wenn Ihr Euren Teil in der Festung der Stürme beigetragen habt.", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Euch einen respektvollen Ruf bei den Sha'tar verschafft, indem Ihr Kael'thas Streitkräfte in der Festung der Stürme tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10561] = { id = 10561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respektvoller Ruf bei den Hütern der Zeit", description = "Ihr habt Euch bewiesen, {race}. Jedoch ist die Zeitlinie immer noch nicht sicher.\n\nWir brauchen Helden; und Ihr könntet einer davon sein.\n\nBeschützt die Geschehnisse der Vergangenheit auch weiterhin gegen Eindringlinge. Dann werdet Ihr die Achtung bekommen, die Euch zusteht.", sourceObjective = "Andormu in den Höhlen der Zeit in Tanaris möchte, dass Ihr Euch einen respektvollen Ruf bei den Hütern der Zeit verdient, indem Ihr weiterhin die Ereignisse im Alten Hügelland und dem Schwarzen Morast in den Höhlen der Zeit verteidigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10562] = { id = 10562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagert!", description = "Ihr müsst weiterhin wachsam bleiben, {race}. Wir stehen unter ständigem Angriff der Brennenden Legion.\n\nDie Dämonen lassen von ihrem Lager in der Feste der Legion aus ständig neue Höllenbestien auf uns herabregnen. Und sobald wir sie getötet haben, schlagen neue Meteoriten ein und eine neue Angriffswelle geht los.\n\nMeine Männer sind erschöpft und ausgelaugt. Ich weiß nicht, wie lange sie das noch durchhalten. Bitte, {name}, helft uns bei der Verteidigung. Nehmt Euren Platz in der Linie ein und haltet den Vormarsch der Höllenbestien auf!", sourceObjective = "Schwadronskommandant Nuainn außerhalb der Wildhammerfeste möchte, dass Ihr 10 angreifende Höllenbestien tötet.", completion = "Danke, dass Ihr meine Männer unterstützt habt, {name}. Mit Eurer Hilfe und der Hilfe anderer, können wir vielleicht noch länger durchhalten. Unglücklicherweise ist Durchhalten leider nicht genug. Wir müssen zum Angriff übergehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10563] = { id = 10563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Feste der Legion", description = "Die Feste der Legion ist fast uneinnehmbar. Und um ganz ehrlich zu sein kann ich keine Streitkräfte für einen Angriff entbehren. Unsere Hoffnungen ruhen auf Euch, {name}.\n\nDie wenigen Informationen, die wir sammeln konnten, weisen darauf hin, dass die Legion die Höllenbestien in der Feste lagert und vorbereitet. Ich möchte, dass Ihr die Feste in der Verkleidung, die ich Euch geben werde, nach detaillierten Informationen über die Pläne der Legion durchsucht. Wir können nur hoffen, dass Ihr die Gespräche zwischen ihren Kommandanten abfangen oder belauschen könnt. Viel Glück, {name}.", sourceObjective = "Begebt Euch zur Feste der Legion und findet das Kommunikationsgerät der Legion. Benutzt die Verkleidung, während Ihr in der Nähe des Kommunikationsgeräts steht, um mehr über die Pläne der Legion herauszufinden. Kehrt danach zu Schwadronskommandant Nuainn in der Wildhammerfeste zurück.", progress = "Was habt Ihr herausgefunden?", completion = "<Schwadronskommandant Nuainn hört sich Euren Bericht an und wird mit jedem Satz nervöser.>\n\nIhr sagt also, dass sie genügend Höllenbestien haben, um die Angriffe noch zu verstärken? Wenn wir sie nicht aufhalten, bevor sie die nächste Phase ihres Plans umsetzen können, ist die Wildhammerfeste verloren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10564] = { id = 10564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt die Höllenbestien in die Luft!", description = "Das Gerät, das wir zusammengebaut haben, würde keinen Schönheitspreis gewinnen, aber es sollte die Höllenbestien in der Feste der Legion zerstören können. Danach zu urteilen, was der Kraftkern des Teufelshäschers bei dem Fauligen Teich angerichtet hat, muss darin eine gehörige Explosionskraft stecken.\n\nWenn Ihr das Gerät in der Mitte der grünen Glyphe in der Feste platzieret, solltet Ihr alle Höllenbestien erwischen können.", sourceObjective = "Zündet die Teufelsbombe, während Ihr auf der grünen Glyphe in der Feste der Legion steht. Meldet Euch bei Schwadronskommandant Nuainn in der Wildhammerfeste zurück, wenn Ihr Euren Auftrag erledigt habt.", progress = "Habt Ihr einen Weg gefunden, um den Vorrat an Höllenbestien der Legion zu zerstören?", completion = "Gut gemacht, {name}! Ich wünschte, ich könnte behaupten, dass die Legion nach einem Rückschlag wie diesem aufgeben wird, aber das würdet Ihr mir ohnehin nicht glauben. Die Todesschmiede, von der Ihr erfahren habt, wird unser nächstes Ziel sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10565] = { id = 10565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Steine der Vekh'nir", description = "Die Arakkoa der Vekh'nir sind uns schon seit vielen Jahren ein Dorn im Auge. Sie praktizieren eine merkwürdige Religion, die sie in ständiger Betriebsamkeit hält. Sie tragen nun diese Kristalle bei sich, die sie für irgendwelche dunklen Zwecke einsetzen.\n\nIch kenne mich ein wenig mit ihren Ritualen aus. Sie bringen die Kristalle zu ihren Zauberzirkeln, um sie dort aufzuladen. Wir im Dorf wüssten gerne mehr darüber. Lauert ein paar der Arakkoa auf, bis Ihr einen Kristall findet. Ladet ihn danach auf und bringt ihn zu mir zurück.", sourceObjective = "Sammelt einen Kristall der Vekh'nir und benutzt ihn beim Zauberzirkel der Vekh'nir, um ihn aufzuladen.", progress = "Die Arakkoa der Vekh'nir waren viele Jahre lang gütige Wesen., doch nun hat sie etwas aufgehetzt.", completion = "Ah, schaut nur, wie er leuchtet! Ich muss ihn sofort ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10566] = { id = 10566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probieren geht über Studieren", description = "Ich habe vier Zauberstäbe hergestellt, die die Macht der Arakkoakristalle verstärken sollten. Bringt diese Stäbe zu Trogmas Besitz und probiert sie an den Ogersklaven aus.\n\nIhr benötigt einen energieerfüllten Kristall von den Arakkoa in der Gegend, um die Stäbe zu benutzen.\n\nKommt zu mir zurück, sobald Ihr herausgefunden habt, welcher Stab am besten funktioniert.", sourceObjective = "Probiert jeden von Dertroks Zauberstäben an einem Ogersklaven der Arakkoa aus. Ihr benötigt einen energieerfüllten Kristall der Vekh'nir für jeden Stab, den Ihr benutzen wollt.", progress = "Ich warte gespannt auf Eure Ergebnisse, {name}.", completion = "Diese Informationen werden uns sehr viel weiterhelfen, {name}. Ich werde den Zauberstab noch verbessern und schauen, ob wir ihn auch für weitere Zwecke einsetzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10567] = { id = 10567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herstellung des Anhängers", description = "Unter den Arakkoa des Ruuanwaldes nehmen die Herolde des Raben innerhalb der Brut eine besondere Stellung ein, da sie die Boten ihres Gottes sind.\n\nDie Arakkoa glauben, dass die Herolde vom Himmel aus, wo sie den Lehren des Raben lauschen, über sie wachen und hinabsteigen, um sein Wort zu verbreiten.\n\nDie Herolde haben einen starken Einfluss auf die Seelen der Arakkoa. Sie benutzen magische Anhänger, die wir benötigen.\n\nLockt einen der Herolde herbei, indem Ihr seine Brut tötet und ihre Klauen abtrennt. Legt die Klauen auf den Altar, um seine Aufmerksamkeit zu erregen.", sourceObjective = "Sammelt 6 Klauen der Ruuan'ok und benutzt sie bei dem Orakelkreis der Ruuan'ok, um einen Herold des Raben herbeizurufen. Tötet ihn, um den Anhänger des Herolds an Euch zu bringen.", progress = "Sobald der Herold bemerkt, dass Ihr seine Brut angreift, wird er sicher schnell reagieren.", completion = "Ihr habt ihn!\n\nMit diesem Anhänger werde ich dafür sorgen können, dass Ihr die Sprache der Arakkoa aus Grishnath versteht.\n\nHiermit werden wir die Arakkoa und das Wesen des Raben besser verstehen lernen. Ich brauche dazu Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10568] = { id = 10568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrifttafeln von Baa'ri", description = "Vor vielen Jahren schuf der gefürchtete Orchexenmeister Gul'dan den Vulkan, der sich in der Mitte von Schattenmond befindet. Die Draeneistadt Baa'ri wurde mitsamt seiner Einwohner und vielen wichtigen religiösen Artefakten unter der Lava begraben.\n\nDie verräterischen Zerschlagenen der Aschenzungen wurden von Illidan beauftragt, in dieser Gegend Ausgrabungen durchzuführen. Wir müssen diese Chance nutzen, um an die Schrifttafeln von Baa'ri zu kommen. Dieser alte Text soll angeblich die Geheimnisse des Tempels von Karabor, der heute als Schwarzer Tempel bekannt ist, enthalten.", sourceObjective = "Anachoret Ceyla beim Altar der Sha'tar möchte, dass Ihr 12 Schrifttafeln von Baa'ri vom Boden und von den Arbeitern der Aschenzungen in den Ruinen von Baa'ri sammelt.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr die Schrifttafeln schon gefunden, {name}?", completion = "Die Schrifttafeln von Baa'ri! Ja, die werden uns sehr wichtige Informationen liefern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10569] = { id = 10569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wrack der Sketh'lon", description = "Unsere Späher haben uns erschütternde Berichte aus den zerstörten Arakkoalagern in der Gegend geliefert.\n\nDie Geister der mächtigen Arakkoamagier verfügen über nie geahnte Kräfte! Sie scheinen sich zu formieren, als ob sie etwas planten, aber wir wissen nur sehr wenig darüber. Wir können uns nicht leisten, die Augen davor zu verschließen!\n\nReist nach Norden zum Wrack der Sketh'lon, nordwestlich der Todesschmiede, und sucht nach Anzeichen für ihre Beweggründe.", sourceObjective = "Besorgt das Tagebuch des Kommandanten der Sketh'lon - Seite 1, das Tagebuch des Kommandanten der Sketh'lon - Seite 2 und das Tagebuch des Kommandanten der Sketh'lon - Seite 3 von den Arakkoa des Dunklen Rats beim Wrack der Sketh'lon und bringt die Seiten zu Greifenreiter Kieran.", progress = "Was habt Ihr entdeckt?", completion = "<Kieran wirft einen kurzen Blick auf die Tagebuchseiten.>\n\nVieles davon ist unleserlich, aber ich kann hier und da ein paar Worte verstehen. Es geht um eine fehlgeschlagene Vorbereitung eines Zaubers, Opfer und eine sich verschlechternde Situation. Hier steht auch irgendetwas Merkwürdiges über einen 'Deserteur'.", sourceObjectiveStatus = "unverified-source-field" }
quests[10570] = { id = 10570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Distelsüchtigen fangen", description = "<Borak nimmt Euch das Blutdistelbündel ab und riecht daran.>\n\nStechend...\n\nJetzt nehmt das Bündel und legt es am anderen Ende dieser Brücke ab. Wenn der Entsandte seine tägliche Runde macht, wird er gar nicht anders können, als es aufzuheben - ohne seine Leibwache. Wisst Ihr, Blutelfen verachten Blutdistelabhängige. Wenn einer seiner Gefährten das je herausfinden würde...\n\nIhr müsst nur daliegen und abwarten, bis er seine Leibwache fortschickt. Wenn er alleine ist, schlagt zu! Tötet ihn und nehmt Euch den Schriftwechsel.", sourceObjective = "Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr Sturmgrimms Schriftwechsel beschafft.", progress = "Beeilt Euch, Junge!", completion = "<Borak nimmt den Schriftwechsel und beginnt zu lesen.>\n\nGerissene Hunde! Dies ist eine Anordnung von Illidan, die besagt, wo die Litanei der Verdammnis als nächstes versteckt werden soll. Offensichtlich ändern sie den Aufenthaltsort ständig. Aber wir wissen leider nicht, wo es sich im Augenblick befindet... Wenn wir diesen Brief doch nur abliefern könnten, jetzt, da wir wissen, wo sie es dann verstecken werden.\n\nWie schade, dass das Siegel nun zerbrochen und der Brief damit nutzlos ist.\n\nHmm... Es sei denn...", sourceObjectiveStatus = "unverified-source-field" }
quests[10571] = { id = 10571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oronu der Älteste", description = "Laut den Schrifttafeln wurde in Baa'ri ein Artefakt, das als Medaillon von Karabor bekannt ist, aufbewahrt. Nur die höchstrangigen Draeneipriester durften es tragen, da es uneingeschränkten Zugang zum Tempel von Karabor bot.\n\nWir müssen herausfinden, ob die Aschenzungen das Medaillon schon gefunden haben. Seine Macht wäre uns eine große Hilfe im Kampf gegen Illidan.\n\nAkamas Leutnant in Baa'ri, Oronu der Älteste, erhält täglich schriftliche Befehle von Akama. Besorgt sie Euch und bringt sie mir.", sourceObjective = "Anachoret Ceyla beim Altar der Sha'tar möchte, dass Ihr die Befehle von Akama von Oronu dem Ältesten in den Ruinen von Baa'ri besorgt.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Gibt es schon Neuigkeiten, {name}? Wir haben nicht viel Zeit.", completion = "Akamas Handschrift. Es ist wirklich sehr traurig, was aus jemandem werden konnte, der so weise und beliebt war wie er.", sourceObjectiveStatus = "unverified-source-field" }
quests[10572] = { id = 10572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bombe bauen", description = "Wir können der Legion nicht erlauben, die Wildhammerfeste auf ihrem Marsch zum Schwarzen Tempel zu zertrampeln.\n\nEs gibt nur einen Weg, um sie aufzuhalten, {name}. Ihr müsst einen Sprengkörper herstellen, der groß genug ist, um den gesamten Vorrat an Höllenbestien in der Feste der Legion zu zerstören.\n\nAm Fauligen Teich in der Nähe der Feste der Legion gibt es viele alte Teufelshäscherkraftkerne, die Ihr als Grundlage für Euer Gerät verwenden könnt. Durchsucht die anderen Trümmer in der Nähe der Feste nach einer Rüstungsplatte, aus der wir ein Gehäuse bauen können.", sourceObjective = "Besorgt Euch einen Teufelshäscherkraftkern und eine Teufelshäscherrüstungsplatte und bringt sie zu Schwadronskommandant Nuainn in der Wildhammerfeste.", progress = "<Ihr reicht dem Schwadronskommandanten die Materialien.>", completion = "<Der Schwadronskommandant setzt den Kraftkern in die Rüstplatten und versiegelt nickend das Gerät.>\n\nDas sollte klappen. Und es sollte auch eine ziemlich große Explosion von sich geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10573] = { id = 10573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todesschmiede", description = "Von Euren Entdeckungen in der Feste der Legion konnten wir erfahren, dass die Verbündeten der Legion vom Schattenrat Höllenbestien in der Todesschmiede herstellen. Ich habe einen kleinen Spähertrupp geschickt, um die Gegend zu überwachen, aber leider können sie nicht alle anstehenden Aufgaben erfüllen.\n\nWenn wir die Todesschmiede weiter arbeiten lassen, werden sie den Vorrat an Höllenbestien, den Ihr vernichtet habt, im Handumdrehen wieder aufgestockt haben.\n\nIch möchte, dass Ihr Euch mit Sturmrufer Ewan Wildschwinge unterhaltet. Ihr findet ihn im Turm der Todesschmiede, der die Schmiede überblickt, nordwestlich von hier.", sourceObjective = "Meldet Euch bei Sturmrufer Ewan Wildschwinge im Turm der Todesschmiede.", completion = "<Der Zwerg nickt.>\n\nVerstärkung ist gut. Wir haben bisher grundlegende Informationen über die Pläne des Schattenrats hier gesammelt, aber ich wäre sehr froh, wenn wir endlich gegen sie vorgehen könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10574] = { id = 10574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderber der Aschenzungen", description = "Laut Akamas Brief wurden vier Teile des Medaillons ausgegraben und den Verderbern der Aschenzungen übergeben. Diese gefürchteten Zerschlagenen waren einst mächtige Schamanen, die nun die Elemente schänden, die sie einst verehrten.\n\nHaalum, der Verderber der Luft, befindet sich am Netherschwingenpass. Eykenen und Uylaru, die Verderber der Erde und des Feuers, wurden zuletzt bei den Teufelsgruben in der Nähe der Hand des Gul'dan gesehen. Lakaan, der Verderber des Wassers, soll sich in der Nähe der Echsennarbe aufhalten.\n\nFindet sie und besorgt Euch die Medaillonfragmente von ihnen.", sourceObjective = "Beschafft die vier Medaillonfragmente von Haalum, Eykenen, Lakaan und Uylaru und kehrt danach zu Anachoret Ceyla beim Altar der Sha'tar im Schattenmondtal zurück.\n\nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr die vier Fragmente des Medaillons, {name}?", completion = "Ja! Die vier Fragmente des Medaillons. Und nun setzt sie zusammen...", sourceObjectiveStatus = "unverified-source-field" }
